cat > /workspace/src/sox.h << 'CEOF'
#ifndef SOX_H
#define SOX_H

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <errno.h>
#include <stdarg.h>
#include <stdbool.h>

#define SOX_VERSION "14.4.2"
#define SOX_DEFAULT_RATE 48000
#define SOX_DEFAULT_CHANNELS 1
#define SOX_MAX_EFFECTS 256

/* Sample type */
typedef int32_t sox_sample_t;
#define SOX_SAMPLE_MIN (-2147483648)
#define SOX_SAMPLE_MAX (2147483647)

/* SOX_SAMPLE_TO_FLOAT: convert sample to float in range [-1.0, 1.0) */
#define SOX_SAMPLE_TO_FLOAT(s) ((double)(s) / ((double)SOX_SAMPLE_MAX + 1.0))
#define FLOAT_TO_SOX_SAMPLE(f) ((sox_sample_t)((f) * ((double)SOX_SAMPLE_MAX + 1.0)))

/* Audio encoding types */
typedef enum {
    SOX_ENCODING_UNKNOWN = 0,
    SOX_ENCODING_SIGN2,      /* signed integer PCM */
    SOX_ENCODING_UNSIGNED,   /* unsigned integer PCM */
    SOX_ENCODING_FLOAT,      /* floating point */
    SOX_ENCODING_ULAW,       /* mu-law */
    SOX_ENCODING_ALAW,       /* A-law */
    SOX_ENCODING_IMA_ADPCM,  /* IMA ADPCM */
    SOX_ENCODING_MS_ADPCM,   /* MS ADPCM */
    SOX_ENCODING_GSM_FULL_RATE, /* GSM full rate */
    SOX_ENCODING_LAST
} sox_encoding_t;

/* Signal info */
typedef struct {
    uint32_t rate;
    unsigned channels;
    unsigned precision;   /* bits per sample */
    uint64_t length;     /* samples (per channel), 0 if unknown */
    double *mult;
} sox_signalinfo_t;

/* Encoding info */
typedef struct {
    sox_encoding_t encoding;
    unsigned bits_per_sample;
    double compression;
    int reverse_bytes;
    int reverse_nibbles;
    int reverse_bits;
    int opposite_endian;
} sox_encodinginfo_t;

/* Forward declarations */
typedef struct sox_format_s sox_format_t;
typedef struct sox_effect_s sox_effect_t;
typedef struct sox_effect_handler_s sox_effect_handler_t;

/* Format handler */
typedef struct {
    const char *name;
    const char **names;
    unsigned flags;
    int (*startread)(sox_format_t *ft);
    size_t (*read)(sox_format_t *ft, sox_sample_t *buf, size_t len);
    int (*stopread)(sox_format_t *ft);
    int (*startwrite)(sox_format_t *ft);
    size_t (*write)(sox_format_t *ft, const sox_sample_t *buf, size_t len);
    int (*stopwrite)(sox_format_t *ft);
    int (*seek)(sox_format_t *ft, uint64_t offset);
    char const * const *write_formats;
    sox_rate_t const *write_rates;
    size_t priv_size;
    const char *description;
} sox_format_handler_t;

typedef double sox_rate_t;

/* File format structure */
struct sox_format_s {
    char *filename;
    sox_signalinfo_t signal;
    sox_encodinginfo_t encoding;
    char *filetype;
    FILE *fp;
    void *priv;
    char *buf;
    size_t buf_len;
    size_t buf_ptr;
    int mode;           /* 'r' or 'w' */
    double volume;
    int ignore_length;
    const sox_format_handler_t *handler;
    char *oob_comment;  /* out-of-band comment */
    uint64_t data_start; /* byte offset of audio data */
};

/* Effect parameters */
#define SOX_EFF_PRIV_SIZE 4096
#define MAX_EFF_ARGS 16

/* Effect flow return values */
#define SOX_SUCCESS 0
#define SOX_EOF -1
#define SOX_EFF_NULL 1

struct sox_effect_handler_s {
    const char *name;
    const char *usage;
    unsigned flags;
    int (*getopts)(sox_effect_t *effp, int argc, char *argv[]);
    int (*start)(sox_effect_t *effp);
    int (*flow)(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf,
                size_t *isamp, size_t *osamp);
    int (*drain)(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp);
    int (*stop)(sox_effect_t *effp);
    int (*kill)(sox_effect_t *effp);
    size_t priv_size;
};

struct sox_effect_s {
    char *name;
    sox_signalinfo_t in_signal;
    sox_signalinfo_t out_signal;
    sox_encodinginfo_t in_encoding;
    sox_encodinginfo_t out_encoding;
    const sox_effect_handler_t *handler;
    void *priv;
    uint64_t clips;
    int eof;
    sox_sample_t *obuf;
    size_t obeg;
    size_t oend;
    size_t bufsiz;
};

/* Global options */
typedef struct {
    int verbosity;
    int combine_method;
    int no_dither;
    int show_progress;
    int guard;
    int norm;
    int replay_gain;
    int no_clobber;
    size_t bufsiz;
    char *effects_file;
    char *temp_dir;
    char *play_rate_arg;
    int plot;
    int single_threaded;
    int multi_threaded;
} sox_globals_t;

extern sox_globals_t sox_globals;

/* Verbosity levels */
#define SOX_V0 0
#define SOX_V1 1
#define SOX_V2 2
#define SOX_V3 3
#define SOX_V4 4

/* Message functions */
void sox_warn(const char *fmt, ...);
void sox_fail(const char *fmt, ...);
void sox_info(const char *fmt, ...);
void sox_debug(const char *fmt, ...);
void sox_report(int level, const char *fmt, ...);

/* Format functions */
sox_format_t *sox_open_read(const char *path, const sox_signalinfo_t *signal,
                             const sox_encodinginfo_t *encoding, const char *filetype);
sox_format_t *sox_open_write(const char *path, const sox_signalinfo_t *signal,
                              const sox_encodinginfo_t *encoding, const char *filetype,
                              const sox_oob_t *oob, const char *comment);
int sox_close(sox_format_t *ft);
size_t sox_read(sox_format_t *ft, sox_sample_t *buf, size_t len);
size_t sox_write(sox_format_t *ft, const sox_sample_t *buf, size_t len);

typedef struct {
    char *comments;
    char *artist;
    char *title;
    char *album;
} sox_oob_t;

/* Endian-ness conversion */
static inline uint16_t swap16(uint16_t x) {
    return ((x & 0xFF) << 8) | ((x >> 8) & 0xFF);
}
static inline uint32_t swap32(uint32_t x) {
    return ((x & 0xFF) << 24) | (((x >> 8) & 0xFF) << 16) |
           (((x >> 16) & 0xFF) << 8) | ((x >> 24) & 0xFF);
}
static inline uint64_t swap64(uint64_t x) {
    return ((uint64_t)swap32(x & 0xFFFFFFFF) << 32) | swap32(x >> 32);
}

/* Byte order detection */
static inline int is_big_endian(void) {
    union { uint16_t s; uint8_t b[2]; } u = {0x0001};
    return u.b[0] != 1;
}

/* Clipping */
static inline sox_sample_t clip_sample(int64_t s) {
    if (s > SOX_SAMPLE_MAX) return SOX_SAMPLE_MAX;
    if (s < SOX_SAMPLE_MIN) return SOX_SAMPLE_MIN;
    return (sox_sample_t)s;
}

/* u-law and a-law */
uint8_t lin16_to_ulaw(int16_t x);
int16_t ulaw_to_lin16(uint8_t u);
uint8_t lin16_to_alaw(int16_t x);
int16_t alaw_to_lin16(uint8_t a);

#endif /* SOX_H */
CEOF
echo "Created sox.h"

