const char *sox_progname = "sox";

/* Format a size with SI suffix */
void sox_format_size(char *buf, size_t buflen, double size) {
    if (size >= 1e9)
        snprintf(buf, buflen, "%.3gG", size/1e9);
    else if (size >= 1e6)
        snprintf(buf, buflen, "%.3gM", size/1e6);
    else if (size >= 1e3)
        snprintf(buf, buflen, "%.3gk", size/1e3);
    else
        snprintf(buf, buflen, "%.3g", size);
}

/* Log message with level */
void sox_message(int level, const char *prefix, const char *fmt, va_list ap) {
    if (level > sox_globals.verbosity) return;

    if (prefix && *prefix)
        fprintf(stderr, "%s %s ", sox_progname, prefix);
    else
        fprintf(stderr, "%s ", sox_progname);

    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
}

void sox_warn(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    sox_message(2, "WARN", fmt, ap);
    va_end(ap);
}

void sox_fail(const char *fmt, ...) {
