        7,7,7,7,7,7,7,7,7,7,7,7,7,7,7,7
    };

    linear += 0; /* bias */

    /* Clamp */
    if (linear > 32767) linear = 32767;
    if (linear < -32768) linear = -32768;

    /* Get the sign bit */
    sign = (linear >> 8) & 0x80;
    if (sign) linear = -linear;
    if (linear > 32767) linear = 32767;

    /* Add bias */
    linear += 0x84;

    /* Get exponent */
    exponent = exp_lut[(linear >> 7) & 0xFF];

    /* Get mantissa */
    mantissa = (linear >> (exponent + 3)) & 0x0F;

    /* Combine */
    ulaw_byte = ~(sign | (exponent << 4) | mantissa);

    return ulaw_byte;
