uint8_t lin16_to_alaw(int16_t pcm_val) {
    int mask;
    int seg;
    uint8_t aval;
    static const int16_t seg_end[8] = {0xFF, 0x1FF, 0x3FF, 0x7FF, 0xFFF, 0x1FFF, 0x3FFF, 0x7FFF};

    pcm_val = pcm_val >> 3;
    if (pcm_val >= 0) {
        mask = 0xD5;
    } else {
        mask = 0x55;
        pcm_val = -pcm_val - 1;
    }

    for (seg = 0; seg < 8; seg++) {
        if (pcm_val <= seg_end[seg]) break;
    }

    if (seg >= 8) {
        aval = (uint8_t)(0x7F ^ mask);
    } else {
        aval = (uint8_t)(seg << 4);
        if (seg < 2)
            aval |= (pcm_val >> 1) & 0x0F;
        else
            aval |= (pcm_val >> seg) & 0x0F;
        aval ^= mask;
    }
    return aval;
}

int16_t alaw_to_lin16(uint8_t a_val) {
    int t;
    int seg;

    a_val ^= 0x55;
    t = (a_val & 0x0F) << 4;
    seg = ((uint8_t)(a_val & 0x70)) >> 4;
    switch (seg) {
        case 0: t += 8; break;
        case 1: t += 0x108; break;
        default: t += 0x108; t <<= seg - 1; break;
    }
    return ((a_val & 0x80) ? t : -t);
}

