#define FLOAT64_TO_SOX_SAMPLE(f) ((sox_sample_t)((f) * ((double)SOX_SAMPLE_MAX + 1.0)))

typedef double sox_rate_t;

/* Encoding types */
typedef enum {
    SOX_ENCODING_UNKNOWN = 0,
    SOX_ENCODING_SIGN2,       /* signed integer PCM */
    SOX_ENCODING_UNSIGNED,    /* unsigned integer PCM */
    SOX_ENCODING_FLOAT,       /* floating point PCM */
    SOX_ENCODING_FLOAT_TEXT,  /* floating-point text */
    SOX_ENCODING_FLAC,
    SOX_ENCODING_HCOM,
    SOX_ENCODING_WAVPACK,
    SOX_ENCODING_WAVPACKF,
    SOX_ENCODING_ULAW,        /* mu-law */
    SOX_ENCODING_ALAW,        /* A-law */
