    SOX_ENCODING_G723,
    SOX_ENCODING_CL_ADPCM,
    SOX_ENCODING_CL_ADPCM16,
    SOX_ENCODING_MS_ADPCM,    /* MS ADPCM */
    SOX_ENCODING_IMA_ADPCM,   /* IMA ADPCM */
    SOX_ENCODING_OKI_ADPCM,
    SOX_ENCODING_DPCM,
    SOX_ENCODING_DWVW,
    SOX_ENCODING_DWVWN,
    SOX_ENCODING_GSM_FULL_RATE, /* GSM full rate */
    SOX_ENCODING_MP3,
    SOX_ENCODING_VORBIS,
    SOX_ENCODING_AMR_WB,
    SOX_ENCODING_AMR_NB,
    SOX_ENCODING_CVSD,
    SOX_ENCODING_LPC10,
    SOX_ENCODING_OPUS,
    SOX_ENCODING_LAST
} sox_encoding_t;

/* Signal info */
typedef struct {
    sox_rate_t rate;
    unsigned channels;
    unsigned precision;   /* bits of precision */
    uint64_t length;     /* samples (per channel), 0 if unknown */
    double *mult;
} sox_signalinfo_t;

/* Encoding info */
typedef struct {
    sox_encoding_t encoding;
    unsigned bits_per_sample;
    double compression;
    int reverse_bytes;
    int reverse_nibbles;
    int reverse_bits;
    int opposite_endian;
} sox_encodinginfo_t;

/* Out-of-band data (comments, etc.) */
typedef struct {
    char *comment;   /* primary comment/annotation */
} sox_oob_t;

/* Forward declarations */
typedef struct sox_format_s sox_format_t;
typedef struct sox_effect_s sox_effect_t;
typedef struct sox_effect_handler_s sox_effect_handler_t;

/* Format handler */
typedef struct {
    const char *name;
    const char *const *names;   /* alternate names */
    unsigned flags;
    int (*startread)(sox_format_t *ft);
    size_t (*read)(sox_format_t *ft, sox_sample_t *buf, size_t len);
    int (*stopread)(sox_format_t *ft);
    int (*startwrite)(sox_format_t *ft);
    size_t (*write)(sox_format_t *ft, const sox_sample_t *buf, size_t len);
    int (*stopwrite)(sox_format_t *ft);
    int (*seek)(sox_format_t *ft, uint64_t offset);
    const char *const *write_formats;
    const sox_rate_t *write_rates;
    size_t priv_size;
    const char *description;
    const char *const *write_encodings;
