    double volume;
    double volume_db;
    int ignore_length;
    const sox_format_handler_t *handler;
    sox_oob_t oob;
    uint64_t data_start; /* byte offset of audio data */
    off_t filesize;      /* file size in bytes */
    char seekable;
};

/* Effect flags */
#define SOX_EFF_CHAN    1   /* Can alter number of channels */
#define SOX_EFF_RATE    2   /* Can alter sample rate */
#define SOX_EFF_PREC    4   /* Can alter precision */
#define SOX_EFF_LENGTH  8   /* Can alter audio length */
#define SOX_EFF_MCHAN  16   /* Is multi-channel aware */
#define SOX_EFF_NULL   32   /* Has no effect (pass-through) */
#define SOX_EFF_DEPRECATED 64
#define SOX_EFF_GAIN   128  /* Gain effect */
#define SOX_EFF_INTERNAL 256 /* For internal use only */
#define SOX_EFF_MODIFY 512  /* Can modify signal */
#define SOX_EFF_ALPHA  1024 /* Alphabetical order */
#define SOX_EFF_REPORT 2048 /* Report-only effect */

/* Effect return values */
#define SOX_SUCCESS  0
#define SOX_EOF     -1
#define SOX_EFF_NULL_FN 1  /* Returned by null effects */

struct sox_effect_handler_s {
    const char *name;
    const char *usage;
    unsigned flags;
    int (*getopts)(sox_effect_t *effp, int argc, char *argv[]);
    int (*start)(sox_effect_t *effp);
    int (*flow)(sox_effect_t *effp, const sox_sample_t *ibuf, sox_sample_t *obuf,
                size_t *isamp, size_t *osamp);
    int (*drain)(sox_effect_t *effp, sox_sample_t *obuf, size_t *osamp);
    int (*stop)(sox_effect_t *effp);
    int (*kill)(sox_effect_t *effp);
    size_t priv_size;
};

#define MAX_EFF_PRIV_SIZE 8192

struct sox_effect_s {
    sox_effect_handler_t handler;
    sox_signalinfo_t in_signal;
    sox_signalinfo_t out_signal;
    sox_encodinginfo_t in_encoding;
    sox_encodinginfo_t out_encoding;
    void *priv;
    uint64_t clips;
    int eof;
    sox_sample_t *obuf;
    size_t obeg;
    size_t oend;
    size_t bufsiz;
    size_t odone;
    int global_info_kludge;
};

/* Global options */
typedef struct {
    int verbosity;
    int combine_method;
    int no_dither;
    int show_progress;
    int guard;
    int norm;
    int replay_gain;
    int no_clobber;
    size_t bufsiz;
    size_t input_bufsiz;
    char *effects_file;
    char *temp_dir;
    char *play_rate_arg;
    int plot;
    int single_threaded;
    int multi_threaded;
    unsigned dft_min;
    char *add_comment;
    char *comment;
    char *comment_file;
