void sox_format_size(char *buf, size_t buflen, double size);
void sox_warn(const char *fmt, ...);
void sox_fail(const char *fmt, ...);
void sox_info(const char *fmt, ...);
void sox_debug(const char *fmt, ...);
void sox_report(int level, const char *fmt, ...);

/* Codec functions */
uint8_t lin16_to_ulaw(int16_t x);
int16_t ulaw_to_lin16(uint8_t u);
uint8_t lin16_to_alaw(int16_t x);
int16_t alaw_to_lin16(uint8_t a);

/* Byte order conversion */
static inline uint16_t bswap16(uint16_t x) {
    return (uint16_t)((x << 8) | (x >> 8));
}
static inline uint32_t bswap32(uint32_t x) {
    return ((x & 0xFF) << 24) | (((x >> 8) & 0xFF) << 16) |
           (((x >> 16) & 0xFF) << 8) | ((x >> 24) & 0xFF);
}
static inline uint64_t bswap64(uint64_t x) {
    return ((uint64_t)bswap32(x & 0xFFFFFFFF) << 32) | bswap32(x >> 32);
}

static inline int sys_is_bigendian(void) {
    union { uint16_t s; uint8_t b[2]; } u;
    u.s = 0x0102;
    return u.b[0] == 0x01;
}

/* Read/write macros for little/big endian */
static inline uint16_t read_le16(const uint8_t *p) {
    return (uint16_t)(p[0] | (p[1] << 8));
}
static inline uint32_t read_le32(const uint8_t *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | (p[3] << 24));
}
static inline uint16_t read_be16(const uint8_t *p) {
    return (uint16_t)((p[0] << 8) | p[1]);
}
static inline uint32_t read_be32(const uint8_t *p) {
    return (uint32_t)((p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]);
}

