extern const sox_format_handler_t sox_s32_format;
extern const sox_format_handler_t sox_u32_format;
extern const sox_format_handler_t sox_f32_format;
extern const sox_format_handler_t sox_f64_format;
extern const sox_format_handler_t sox_ulaw_format;
extern const sox_format_handler_t sox_alaw_format;
extern const sox_format_handler_t sox_dat_format;
extern const sox_format_handler_t sox_sox_format;
extern const sox_format_handler_t sox_voc_format;
extern const sox_format_handler_t sox_svx_format;
extern const sox_format_handler_t sox_gsrt_format;
extern const sox_format_handler_t sox_sph_format;

/* Encoding precision mapping */
static inline unsigned sox_precision(sox_encoding_t encoding, unsigned bits) {
    switch (encoding) {
        case SOX_ENCODING_SIGN2: return bits;
        case SOX_ENCODING_UNSIGNED: return bits;
        case SOX_ENCODING_FLOAT: return bits == 32 ? 25 : bits == 64 ? 54 : bits;
        case SOX_ENCODING_ULAW: return 14;
        case SOX_ENCODING_ALAW: return 13;
        case SOX_ENCODING_IMA_ADPCM: return 13;
        case SOX_ENCODING_MS_ADPCM: return 14;
        case SOX_ENCODING_GSM_FULL_RATE: return 13;
        default: return bits;
    }
}

/* String to encoding */
sox_encoding_t sox_str_to_encoding(const char *str);
const char *sox_encoding_to_str(sox_encoding_t enc);
const char *sox_encoding_to_human(sox_encoding_t enc, unsigned bits);

/* Time parsing */
double sox_parse_time(const char *s);
char *sox_format_time_str(char *buf, size_t len, double t);

/* Number formatting */
char *sox_num_to_str(char *buf, size_t len, double val, const char *unit);

#endif /* SOX_INT_H */
