/* Parse encoding from string */
static sox_encoding_t parse_encoding(const char *str) {
    if (!strcasecmp(str, "signed-integer") || !strcasecmp(str, "signed"))
        return SOX_ENCODING_SIGN2;
    if (!strcasecmp(str, "unsigned-integer") || !strcasecmp(str, "unsigned"))
        return SOX_ENCODING_UNSIGNED;
    if (!strcasecmp(str, "floating-point") || !strcasecmp(str, "float"))
        return SOX_ENCODING_FLOAT;
    if (!strcasecmp(str, "mu-law") || !strcasecmp(str, "ulaw") || !strcasecmp(str, "u-law"))
        return SOX_ENCODING_ULAW;
    if (!strcasecmp(str, "a-law") || !strcasecmp(str, "alaw"))
        return SOX_ENCODING_ALAW;
    if (!strcasecmp(str, "ima-adpcm") || !strcasecmp(str, "ima_adpcm"))
        return SOX_ENCODING_IMA_ADPCM;
    if (!strcasecmp(str, "ms-adpcm") || !strcasecmp(str, "ms_adpcm"))
        return SOX_ENCODING_MS_ADPCM;
    if (!strcasecmp(str, "gsm-full-rate") || !strcasecmp(str, "gsm"))
        return SOX_ENCODING_GSM_FULL_RATE;
    return SOX_ENCODING_UNKNOWN;
}

/* Parse time string (hh:mm:ss.ss or just seconds) */
static double parse_time(const char *str) {
    double total = 0;
    int h = 0, m = 0;
    double s = 0;

    /* Try hh:mm:ss.ss format */
    if (strchr(str, ':')) {
        sscanf(str, "%d:%d:%lf", &h, &m, &s);
        total = h * 3600 + m * 60 + s;
    } else {
        total = strtod(str, NULL);
        /* Handle k/m/g suffixes for samples */
        char *p = (char *)str;
        while (*p && (isdigit(*p) || *p == '.' || *p == '-')) p++;
        if (*p == 'k' || *p == 'K') total *= 1000;
        else if (*p == 'm' || *p == 'M') total *= 60;  /* minutes? No, for time 'm' = minutes */
    }
    return total;
}

