        7,7,7,7,7,7,7,7,7,7,7,7,7,7,7,7
    };
    int sign, exponent, mantissa;
    uint8_t ulaw_byte;
    sign = (linear >> 8) & 0x80;
    if (sign) linear = (int16_t)(-linear);
    if (linear > 32767) linear = 32767;
    linear += 0x84;
