    else { mask = 0x55; pcm_val = -pcm_val - 1; }
    for (seg = 0; seg < 8; seg++) {
        if (pcm_val <= seg_aend[seg]) break;
    }
    if (seg >= 8) {
        aval = (uint8_t)(0x7F ^ mask);
    } else {
        aval = (uint8_t)(seg << 4);
        if (seg < 2) aval |= (pcm_val >> 1) & 0x0F;
        else aval |= (pcm_val >> seg) & 0x0F;
        aval ^= mask;
    }
    return aval;
}

static int16_t alaw_to_lin16(uint8_t a_val) {
    int t, seg;
    a_val ^= 0x55;
    t = (a_val & 0x0F) << 4;
    seg = ((uint8_t)(a_val & 0x70)) >> 4;
    switch (seg) {
        case 0: t += 8; break;
        case 1: t += 0x108; break;
        default: t += 0x108; t <<= (seg - 1); break;
    }
    return (int16_t)((a_val & 0x80) ? t : -t);
}

/* =====================================================================
 * BYTE ORDER UTILITIES  
 * ===================================================================== */

static int is_bigendian(void) {
    union { uint16_t s; uint8_t b[2]; } u; u.s = 0x0102; return u.b[0] == 1;
}

static uint16_t swap16(uint16_t x) { return (uint16_t)((x << 8) | (x >> 8)); }
static uint32_t swap32(uint32_t x) {
    return ((x & 0xFF) << 24) | (((x >> 8) & 0xFF) << 16) |
           (((x >> 16) & 0xFF) << 8) | ((x >> 24) & 0xFF);
}

static uint16_t read_le16(const uint8_t *p) { return (uint16_t)(p[0] | (p[1] << 8)); }
static uint32_t read_le32(const uint8_t *p) {
    return (uint32_t)(p[0] | (p[1] << 8) | (p[2] << 16) | (p[3] << 24));
}
static uint16_t read_be16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t read_be32(const uint8_t *p) {
    return (uint32_t)((p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]);
}

static void write_le16(uint8_t *p, uint16_t v) { p[0] = v & 0xFF; p[1] = v >> 8; }
static void write_le32(uint8_t *p, uint32_t v) {
    p[0] = v & 0xFF; p[1] = (v >> 8) & 0xFF;
    p[2] = (v >> 16) & 0xFF; p[3] = (v >> 24) & 0xFF;
}
static void write_be16(uint8_t *p, uint16_t v) { p[0] = v >> 8; p[1] = v & 0xFF; }
static void write_be32(uint8_t *p, uint32_t v) {
    p[0] = v >> 24; p[1] = (v >> 16) & 0xFF;
    p[2] = (v >> 8) & 0xFF; p[3] = v & 0xFF;
}

/* =====================================================================
 * SAMPLE CONVERSION ROUTINES
 * ===================================================================== */

/* Convert raw bytes to sox_sample_t (32-bit signed PCM internally) */
static sox_sample_t bytes_to_sample(const uint8_t *buf, unsigned bits, 
                                     sox_encoding_t enc, int big_endian) {
    switch (enc) {
        case SOX_ENCODING_UNSIGNED: {
            uint32_t v = 0;
            if (bits == 8) v = buf[0];
            else if (bits == 16) v = big_endian ? read_be16(buf) : read_le16(buf);
            else if (bits == 24) {
                if (big_endian) v = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
                else v = buf[0] | ((uint32_t)buf[1] << 8) | ((uint32_t)buf[2] << 16);
            }
            else if (bits == 32) v = big_endian ? read_be32(buf) : read_le32(buf);
            /* Convert to signed 32-bit: subtract midpoint, scale */
            {
                double max = (double)(1u << bits);
                double val = (double)v / max * 2.0 - 1.0;
                /* val is in [-1, 1) for unsigned */
                return (sox_sample_t)(val * 2147483648.0);
            }
        }
        case SOX_ENCODING_SIGN2: {
            int32_t v = 0;
            if (bits == 8) v = (int8_t)buf[0];
            else if (bits == 16) {
                uint16_t u = big_endian ? read_be16(buf) : read_le16(buf);
                v = (int16_t)u;
            } else if (bits == 24) {
                if (big_endian)
                    v = ((int32_t)(int8_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
                else
                    v = (int32_t)buf[0] | ((uint32_t)buf[1] << 8) | ((int32_t)(int8_t)buf[2] << 16);
            } else if (bits == 32) {
                uint32_t u = big_endian ? read_be32(buf) : read_le32(buf);
                v = (int32_t)u;
            }
            /* Scale to 32-bit */
            if (bits == 32) return (sox_sample_t)v;
            if (bits == 16) return (sox_sample_t)(v * 65536);
            if (bits == 8) return (sox_sample_t)(v * 16777216);
            if (bits == 24) return (sox_sample_t)(v * 256);
            return (sox_sample_t)v;
        }
        case SOX_ENCODING_FLOAT: {
            if (bits == 32) {
                float f;
                uint32_t u = big_endian ? read_be32(buf) : read_le32(buf);
                memcpy(&f, &u, 4);
                double d = f;
                if (d >= 1.0) { return SOX_SAMPLE_MAX; }
                if (d < -1.0) { return SOX_SAMPLE_MIN; }
                return (sox_sample_t)(d * 2147483648.0);
            } else { /* 64 */
                double d;
                uint64_t u;
                u = ((uint64_t)(big_endian ? read_be32(buf) : read_le32(buf)) << 32) |
                    (big_endian ? read_be32(buf+4) : read_le32(buf+4));
                if (!big_endian) { /* little endian: low bytes first */
                    uint32_t lo = read_le32(buf);
                    uint32_t hi = read_le32(buf+4);
                    u = ((uint64_t)hi << 32) | lo;
                } else {
                    uint32_t hi = read_be32(buf);
                    uint32_t lo = read_be32(buf+4);
                    u = ((uint64_t)hi << 32) | lo;
                }
                memcpy(&d, &u, 8);
                if (d >= 1.0) return SOX_SAMPLE_MAX;
                if (d < -1.0) return SOX_SAMPLE_MIN;
                return (sox_sample_t)(d * 2147483648.0);
            }
        }
        case SOX_ENCODING_ULAW:
            return (sox_sample_t)(ulaw_to_lin16(buf[0]) * 65536);
        case SOX_ENCODING_ALAW:
            return (sox_sample_t)(alaw_to_lin16(buf[0]) * 65536);
        default:
            return 0;
    }
}

/* Convert sox_sample_t to raw bytes */
static void sample_to_bytes(uint8_t *buf, sox_sample_t s, unsigned bits,
                              sox_encoding_t enc, int big_endian, uint64_t *clips) {
    switch (enc) {
        case SOX_ENCODING_SIGN2: {
            int32_t v;
            if (bits == 32) v = s;
            else if (bits == 16) {
                int32_t t = s >> 16;
                /* Round and clip */
                if (s & 0x8000) t++;
                if (t > 32767) { t = 32767; if (clips) (*clips)++; }
                else if (t < -32768) { t = -32768; if (clips) (*clips)++; }
                v = t;
            } else if (bits == 8) {
                int32_t t = s >> 24;
                if (s & 0x800000) t++;
                if (t > 127) { t = 127; if (clips) (*clips)++; }
                else if (t < -128) { t = -128; if (clips) (*clips)++; }
                v = t;
            } else if (bits == 24) {
                int32_t t = s >> 8;
                if (s & 0x80) t++;
                if (t > 8388607) { t = 8388607; if (clips) (*clips)++; }
                else if (t < -8388608) { t = -8388608; if (clips) (*clips)++; }
                v = t;
            } else v = s;

            if (bits == 8) buf[0] = (uint8_t)v;
            else if (bits == 16) {
                uint16_t u = (uint16_t)(int16_t)v;
                if (big_endian) write_be16(buf, u);
                else write_le16(buf, u);
            } else if (bits == 24) {
                uint32_t u = (uint32_t)v & 0xFFFFFF;
                if (big_endian) { buf[0] = (u >> 16) & 0xFF; buf[1] = (u >> 8) & 0xFF; buf[2] = u & 0xFF; }
                else { buf[0] = u & 0xFF; buf[1] = (u >> 8) & 0xFF; buf[2] = (u >> 16) & 0xFF; }
            } else if (bits == 32) {
                if (big_endian) write_be32(buf, (uint32_t)v);
                else write_le32(buf, (uint32_t)v);
            }
            break;
        }
        case SOX_ENCODING_UNSIGNED: {
            /* Convert signed to unsigned */
            double d = (double)s / 2147483648.0; /* -1 to <1 */
            d = (d + 1.0) / 2.0; /* 0 to 1 */
            double maxval = (double)(1u << bits);
            double fv = d * maxval;
            uint32_t v;
            if (fv >= maxval) { v = (uint32_t)maxval - 1; if (clips) (*clips)++; }
            else if (fv < 0) { v = 0; if (clips) (*clips)++; }
            else v = (uint32_t)fv;

            if (bits == 8) buf[0] = (uint8_t)v;
            else if (bits == 16) {
                if (big_endian) write_be16(buf, (uint16_t)v);
                else write_le16(buf, (uint16_t)v);
            } else if (bits == 24) {
                if (big_endian) { buf[0] = (v >> 16) & 0xFF; buf[1] = (v >> 8) & 0xFF; buf[2] = v & 0xFF; }
                else { buf[0] = v & 0xFF; buf[1] = (v >> 8) & 0xFF; buf[2] = (v >> 16) & 0xFF; }
            } else if (bits == 32) {
                if (big_endian) write_be32(buf, v);
                else write_le32(buf, v);
            }
            break;
        }
        case SOX_ENCODING_FLOAT: {
            if (bits == 32) {
                float f = (float)((double)s / 2147483648.0);
                uint32_t u;
                memcpy(&u, &f, 4);
                if (big_endian) write_be32(buf, u);
                else write_le32(buf, u);
            } else { /* 64 */
                double d = (double)s / 2147483648.0;
                uint64_t u;
                memcpy(&u, &d, 8);
                if (big_endian) {
                    write_be32(buf, (uint32_t)(u >> 32));
                    write_be32(buf+4, (uint32_t)(u & 0xFFFFFFFF));
                } else {
                    write_le32(buf, (uint32_t)(u & 0xFFFFFFFF));
                    write_le32(buf+4, (uint32_t)(u >> 32));
                }
            }
            break;
        }
        case SOX_ENCODING_ULAW: {
            /* Scale to 16-bit */
            int32_t t = s >> 16;
            if (s & 0x8000) t++;
            if (t > 32767) { t = 32767; if (clips) (*clips)++; }
            else if (t < -32768) { t = -32768; if (clips) (*clips)++; }
            buf[0] = lin16_to_ulaw((int16_t)t);
            break;
        }
        case SOX_ENCODING_ALAW: {
            int32_t t = s >> 16;
            if (s & 0x8000) t++;
            if (t > 32767) { t = 32767; if (clips) (*clips)++; }
            else if (t < -32768) { t = -32768; if (clips) (*clips)++; }
            buf[0] = lin16_to_alaw((int16_t)t);
            break;
        }
        default:
            memset(buf, 0, bits/8);
            break;
    }
}

