/* Convert raw bytes to sox_sample_t (32-bit signed PCM internally) */
static sox_sample_t bytes_to_sample(const uint8_t *buf, unsigned bits, 
                                     sox_encoding_t enc, int big_endian) {
    switch (enc) {
        case SOX_ENCODING_UNSIGNED: {
            uint32_t v = 0;
            if (bits == 8) v = buf[0];
            else if (bits == 16) v = big_endian ? read_be16(buf) : read_le16(buf);
