                return (sox_sample_t)(d * 2147483648.0);
            }
        }
        case SOX_ENCODING_ULAW:
            return (sox_sample_t)(ulaw_to_lin16(buf[0]) * 65536);
        case SOX_ENCODING_ALAW:
            return (sox_sample_t)(alaw_to_lin16(buf[0]) * 65536);
        default:
