                v = t;
            } else if (bits == 8) {
                int32_t t = s >> 24;
                if (s & 0x800000) t++;
                if (t > 127) { t = 127; if (clips) (*clips)++; }
                else if (t < -128) { t = -128; if (clips) (*clips)++; }
                v = t;
            } else if (bits == 24) {
                int32_t t = s >> 8;
                if (s & 0x80) t++;
                if (t > 8388607) { t = 8388607; if (clips) (*clips)++; }
                else if (t < -8388608) { t = -8388608; if (clips) (*clips)++; }
