                else write_le16(buf, (uint16_t)v);
            } else if (bits == 24) {
                if (big_endian) { buf[0] = (v >> 16) & 0xFF; buf[1] = (v >> 8) & 0xFF; buf[2] = v & 0xFF; }
                else { buf[0] = v & 0xFF; buf[1] = (v >> 8) & 0xFF; buf[2] = (v >> 16) & 0xFF; }
            } else if (bits == 32) {
                if (big_endian) write_be32(buf, v);
                else write_le32(buf, v);
            }
            break;
        }
        case SOX_ENCODING_FLOAT: {
            if (bits == 32) {
                float f = (float)((double)s / 2147483648.0);
                uint32_t u;
                memcpy(&u, &f, 4);
                if (big_endian) write_be32(buf, u);
                else write_le32(buf, u);
            } else { /* 64 */
                double d = (double)s / 2147483648.0;
                uint64_t u;
                memcpy(&u, &d, 8);
                if (big_endian) {
                    write_be32(buf, (uint32_t)(u >> 32));
                    write_be32(buf+4, (uint32_t)(u & 0xFFFFFFFF));
                } else {
                    write_le32(buf, (uint32_t)(u & 0xFFFFFFFF));
                    write_le32(buf+4, (uint32_t)(u >> 32));
                }
            }
            break;
        }
        case SOX_ENCODING_ULAW: {
            /* Scale to 16-bit */
            int32_t t = s >> 16;
            if (s & 0x8000) t++;
