            else if (t < -32768) { t = -32768; if (clips) (*clips)++; }
            buf[0] = lin16_to_ulaw((int16_t)t);
            break;
        }
        case SOX_ENCODING_ALAW: {
            int32_t t = s >> 16;
            if (s & 0x8000) t++;
            if (t > 32767) { t = 32767; if (clips) (*clips)++; }
            else if (t < -32768) { t = -32768; if (clips) (*clips)++; }
            buf[0] = lin16_to_alaw((int16_t)t);
            break;
        }
        default:
            memset(buf, 0, bits/8);
            break;
    }
}

