static void lsx_vwarn(const char *prefix, const char *fmt, va_list ap) {
    if (prefix)
        fprintf(stderr, "%s %s ", g_progname, prefix);
    else
        fprintf(stderr, "%s ", g_progname);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
}

static void lsx_warn(const char *fmt, ...) {
    if (globals.verbosity < 2) return;
    va_list ap; va_start(ap, fmt);
    lsx_vwarn("WARN", fmt, ap);
    va_end(ap);
}

