}

/* Format a number with SI suffix */
static void format_si(char *buf, size_t len, double val) {
    if (val >= 1e9)
        snprintf(buf, len, "%.3gG", val / 1e9);
    else if (val >= 1e6)
        snprintf(buf, len, "%.3gM", val / 1e6);
    else if (val >= 1e3)
        snprintf(buf, len, "%.3gk", val / 1e3);
    else
        snprintf(buf, len, "%.3g", val);
}

/* Format time as HH:MM:SS.ss */
static char *format_duration(char *buf, size_t len, double secs) {
    int h = (int)(secs / 3600);
    int m = (int)((secs - h * 3600) / 60);
    double s = secs - h * 3600 - m * 60;
    snprintf(buf, len, "%02d:%02d:%05.2f", h, m, s);
    return buf;
}

/* Get precision for encoding */
static unsigned get_precision(sox_encoding_t enc, unsigned bits) {
    switch (enc) {
        case SOX_ENCODING_SIGN2: return bits;
        case SOX_ENCODING_UNSIGNED: return bits;
        case SOX_ENCODING_FLOAT: return bits == 32 ? 25 : bits == 64 ? 54 : bits;
        case SOX_ENCODING_ULAW: return 14;
        case SOX_ENCODING_ALAW: return 13;
        case SOX_ENCODING_IMA_ADPCM: return 13;
        case SOX_ENCODING_MS_ADPCM: return 14;
        case SOX_ENCODING_GSM_FULL_RATE: return 13;
        default: return bits;
    }
}

