/* =====================================================================
 * FORMAT: WAV
 * ===================================================================== */

/* WAV format codes */
#define WAVE_FORMAT_PCM         0x0001
#define WAVE_FORMAT_IEEE_FLOAT  0x0003
#define WAVE_FORMAT_ALAW        0x0006
#define WAVE_FORMAT_MULAW       0x0007
#define WAVE_FORMAT_IMA_ADPCM   0x0011
#define WAVE_FORMAT_MS_ADPCM    0x0002
#define WAVE_FORMAT_GSM610      0x0031
#define WAVE_FORMAT_EXTENSIBLE  0xFFFE

typedef struct {
    uint32_t data_offset;
    uint32_t data_size;
    uint16_t format_tag;
    uint16_t block_align;
    uint32_t samples_per_block;  /* for ADPCM */
    int is_rifx;  /* big-endian RIFX */
} wav_priv_t;

static int wav_startread(sox_format_t *ft) {
    wav_priv_t *p = (wav_priv_t *)ft->priv;
    uint8_t buf[12];
    uint32_t chunk_size;
    int found_fmt = 0, found_data = 0;

    /* Read RIFF header */
    if (fread(buf, 1, 12, ft->fp) != 12) {
        lsx_fail("formats: can't read WAV header");
        return SOX_EOF;
    }

    if (memcmp(buf, "RIFF", 4) == 0) {
        p->is_rifx = 0;
    } else if (memcmp(buf, "RIFX", 4) == 0) {
        p->is_rifx = 1;
    } else {
        lsx_fail("wav: not a WAV file");
        return SOX_EOF;
    }

    if (memcmp(buf + 8, "WAVE", 4) != 0) {
        lsx_fail("wav: missing WAVE identifier");
        return SOX_EOF;
    }

    /* Parse chunks */
    while (!found_data) {
        uint8_t chbuf[8];
        if (fread(chbuf, 1, 8, ft->fp) != 8) {
            if (found_fmt) {
                /* Might be truncated file */
                lsx_warn("wav: Premature EOF on .wav input file");
                ft->signal.length = 0;
                found_data = 1;
                break;
            }
            lsx_fail("wav: unexpected end of file");
            return SOX_EOF;
        }
        chunk_size = p->is_rifx ? read_be32(chbuf+4) : read_le32(chbuf+4);

        if (memcmp(chbuf, "fmt ", 4) == 0) {
            uint8_t fmt[40];
            uint32_t to_read = chunk_size < sizeof(fmt) ? chunk_size : sizeof(fmt);
            if (fread(fmt, 1, to_read, ft->fp) != to_read) {
                lsx_fail("wav: can't read fmt chunk");
                return SOX_EOF;
            }
            if (chunk_size > to_read) {
                fseek(ft->fp, chunk_size - to_read, SEEK_CUR);
            }
            /* Pad to even */
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);

            uint16_t fmt_tag = p->is_rifx ? read_be16(fmt) : read_le16(fmt);
            uint16_t channels = p->is_rifx ? read_be16(fmt+2) : read_le16(fmt+2);
            uint32_t sample_rate = p->is_rifx ? read_be32(fmt+4) : read_le32(fmt+4);
            /* uint32_t byte_rate = p->is_rifx ? read_be32(fmt+8) : read_le32(fmt+8); */
            uint16_t block_align = p->is_rifx ? read_be16(fmt+12) : read_le16(fmt+12);
            uint16_t bits = p->is_rifx ? read_be16(fmt+14) : read_le16(fmt+14);

            p->format_tag = fmt_tag;
            p->block_align = block_align;
            ft->signal.channels = channels;
            ft->signal.rate = sample_rate;

            /* Handle EXTENSIBLE format */
            if (fmt_tag == WAVE_FORMAT_EXTENSIBLE && chunk_size >= 40) {
                fmt_tag = p->is_rifx ? read_be16(fmt+24) : read_le16(fmt+24);
                p->format_tag = fmt_tag;
            }

            switch (fmt_tag) {
                case WAVE_FORMAT_PCM:
                    if (bits > 8)
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                    else
                        ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
                    ft->encoding.bits_per_sample = bits;
                    break;
                case WAVE_FORMAT_IEEE_FLOAT:
                    ft->encoding.encoding = SOX_ENCODING_FLOAT;
                    ft->encoding.bits_per_sample = bits;
                    break;
                case WAVE_FORMAT_MULAW:
                    ft->encoding.encoding = SOX_ENCODING_ULAW;
                    ft->encoding.bits_per_sample = 8;
                    break;
                case WAVE_FORMAT_ALAW:
                    ft->encoding.encoding = SOX_ENCODING_ALAW;
                    ft->encoding.bits_per_sample = 8;
                    break;
                case WAVE_FORMAT_IMA_ADPCM:
                    ft->encoding.encoding = SOX_ENCODING_IMA_ADPCM;
                    ft->encoding.bits_per_sample = 4;
                    break;
                case WAVE_FORMAT_MS_ADPCM:
                    ft->encoding.encoding = SOX_ENCODING_MS_ADPCM;
                    ft->encoding.bits_per_sample = 4;
                    break;
                default:
                    ft->encoding.encoding = SOX_ENCODING_SIGN2;
                    ft->encoding.bits_per_sample = bits;
                    break;
            }
            ft->signal.precision = get_precision(ft->encoding.encoding, 
                                                   ft->encoding.bits_per_sample);
            found_fmt = 1;
        } else if (memcmp(chbuf, "data", 4) == 0) {
            if (!found_fmt) {
                lsx_fail("wav: missing fmt chunk before data");
                return SOX_EOF;
            }
            p->data_offset = ftell(ft->fp);
            p->data_size = chunk_size;
            ft->data_start = p->data_offset;

            /* Calculate number of samples */
            unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
            if (bytes_per_sample > 0 && ft->signal.channels > 0) {
                uint64_t total_samples = chunk_size / bytes_per_sample;
                ft->signal.length = total_samples / ft->signal.channels;
            }
            found_data = 1;
        } else if (memcmp(chbuf, "JUNK", 4) == 0 ||
                   memcmp(chbuf, "PAD ", 4) == 0 ||
                   memcmp(chbuf, "FLLR", 4) == 0) {
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        } else if (memcmp(chbuf, "LIST", 4) == 0) {
            /* LIST chunk - may contain metadata */
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        } else {
            /* Unknown chunk - skip */
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        }
    }

    /* Get file size */
    long pos = ftell(ft->fp);
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, pos, SEEK_SET);

    return SOX_SUCCESS;
}

static size_t wav_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    wav_priv_t *p = (wav_priv_t *)ft->priv;
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];

    /* Check for IMA_ADPCM or MS_ADPCM - simplified handling */
    if (ft->encoding.encoding == SOX_ENCODING_IMA_ADPCM ||
        ft->encoding.encoding == SOX_ENCODING_MS_ADPCM) {
        /* For now just return silence */
        memset(buf, 0, len * sizeof(sox_sample_t));
        return 0;
    }

    for (i = 0; i < len; i++) {
        if (fread(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
        int be = p->is_rifx;
        buf[i] = bytes_to_sample(raw, ft->encoding.bits_per_sample,
                                  ft->encoding.encoding, be);
    }
    return i;
}

static int wav_stopread(sox_format_t *ft) {
    (void)ft;
    return SOX_SUCCESS;
}

static int wav_startwrite(sox_format_t *ft) {
    wav_priv_t *p = (wav_priv_t *)ft->priv;
    uint8_t header[44];
    memset(header, 0, sizeof(header));

    p->is_rifx = 0;

    /* RIFF header - write placeholder */
    memcpy(header, "RIFF", 4);
    write_le32(header+4, 0);  /* size placeholder */
    memcpy(header+8, "WAVE", 4);

    /* fmt chunk */
    memcpy(header+12, "fmt ", 4);
    write_le32(header+16, 16);  /* chunk size */

    uint16_t fmt_tag;
    unsigned bits = ft->encoding.bits_per_sample;
    switch (ft->encoding.encoding) {
        case SOX_ENCODING_FLOAT: fmt_tag = WAVE_FORMAT_IEEE_FLOAT; break;
        case SOX_ENCODING_ULAW: fmt_tag = WAVE_FORMAT_MULAW; bits = 8; break;
        case SOX_ENCODING_ALAW: fmt_tag = WAVE_FORMAT_ALAW; bits = 8; break;
        case SOX_ENCODING_IMA_ADPCM: fmt_tag = WAVE_FORMAT_IMA_ADPCM; break;
        case SOX_ENCODING_MS_ADPCM: fmt_tag = WAVE_FORMAT_MS_ADPCM; break;
        default: fmt_tag = WAVE_FORMAT_PCM; break;
    }
    write_le16(header+20, fmt_tag);
    write_le16(header+22, (uint16_t)ft->signal.channels);
    write_le32(header+24, (uint32_t)ft->signal.rate);
    uint32_t byte_rate = (uint32_t)(ft->signal.rate * ft->signal.channels * bits / 8);
    write_le32(header+28, byte_rate);
    uint16_t block_align = (uint16_t)(ft->signal.channels * bits / 8);
    write_le16(header+32, block_align);
    write_le16(header+34, (uint16_t)bits);

    /* data chunk header */
    memcpy(header+36, "data", 4);
    write_le32(header+40, 0);  /* size placeholder */

    p->data_offset = 44;

    if (fwrite(header, 1, 44, ft->fp) != 44) {
        lsx_fail("wav: error writing header");
        return SOX_EOF;
    }

    ft->data_start = 44;
    return SOX_SUCCESS;
}

static size_t wav_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];

    for (i = 0; i < len; i++) {
        sample_to_bytes(raw, buf[i], ft->encoding.bits_per_sample,
                         ft->encoding.encoding, 0, &ft->clips);
        if (fwrite(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
    }
    return i;
}

static int wav_stopwrite(sox_format_t *ft) {
    /* Update size fields */
