    if (p->header_size > 24) {
        uint32_t ann_len = p->header_size - 24;
        char *ann = malloc(ann_len + 1);
        if (ann) {
            uint32_t n = (uint32_t)fread(ann, 1, ann_len, ft->fp);
            ann[n] = '\0';
