static int au_startwrite(sox_format_t *ft) {
    au_priv_t *p = (au_priv_t *)ft->priv;

    /* Determine AU encoding */
    unsigned bits = ft->encoding.bits_per_sample;
    uint32_t au_enc;
    switch (ft->encoding.encoding) {
        case SOX_ENCODING_ULAW: au_enc = AU_ENCODING_ULAW; break;
        case SOX_ENCODING_ALAW: au_enc = AU_ENCODING_ALAW; break;
        case SOX_ENCODING_FLOAT:
            au_enc = (bits == 32) ? AU_ENCODING_FLOAT32 : AU_ENCODING_FLOAT64; break;
        case SOX_ENCODING_SIGN2:
        default:
            if (bits == 8) au_enc = AU_ENCODING_PCM8;
            else if (bits == 16) au_enc = AU_ENCODING_PCM16;
            else if (bits == 24) au_enc = AU_ENCODING_PCM24;
            else au_enc = AU_ENCODING_PCM32;
            break;
    }
    p->au_encoding = au_enc;

    /* Determine annotation */
    const char *comment = ft->oob.comment ? ft->oob.comment : "Processed by SoX";
    size_t ann_len = strlen(comment);
    /* Header must be multiple of 8 */
    uint32_t hdr_size = 24 + (uint32_t)ann_len + 1;
    hdr_size = (hdr_size + 7) & ~7;

    p->header_size = hdr_size;

    /* Write header */
    uint8_t hdr[256];
    memset(hdr, 0, sizeof(hdr));
    write_be32(hdr+0, AU_MAGIC);
    write_be32(hdr+4, hdr_size);
    write_be32(hdr+8, 0xFFFFFFFF);  /* unknown data size */
    write_be32(hdr+12, au_enc);
    write_be32(hdr+16, (uint32_t)ft->signal.rate);
    write_be32(hdr+20, ft->signal.channels);

