        return SOX_EOF;
    }

    if (memcmp(buf + 8, "WAVE", 4) != 0) {
        lsx_fail("wav: missing WAVE identifier");
        return SOX_EOF;
    }

    /* Parse chunks */
    while (!found_data) {
        uint8_t chbuf[8];
        if (fread(chbuf, 1, 8, ft->fp) != 8) {
            if (found_fmt) {
                /* Might be truncated file */
                lsx_warn("wav: Premature EOF on .wav input file");
                ft->signal.length = 0;
                found_data = 1;
                break;
            }
            lsx_fail("wav: unexpected end of file");
            return SOX_EOF;
        }
        chunk_size = p->is_rifx ? read_be32(chbuf+4) : read_le32(chbuf+4);

        if (memcmp(chbuf, "fmt ", 4) == 0) {
            uint8_t fmt[40];
            uint32_t to_read = chunk_size < sizeof(fmt) ? chunk_size : sizeof(fmt);
            if (fread(fmt, 1, to_read, ft->fp) != to_read) {
                lsx_fail("wav: can't read fmt chunk");
                return SOX_EOF;
            }
            if (chunk_size > to_read) {
                fseek(ft->fp, chunk_size - to_read, SEEK_CUR);
            }
            /* Pad to even */
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);

            uint16_t fmt_tag = p->is_rifx ? read_be16(fmt) : read_le16(fmt);
            uint16_t channels = p->is_rifx ? read_be16(fmt+2) : read_le16(fmt+2);
            uint32_t sample_rate = p->is_rifx ? read_be32(fmt+4) : read_le32(fmt+4);
            /* uint32_t byte_rate = p->is_rifx ? read_be32(fmt+8) : read_le32(fmt+8); */
            uint16_t block_align = p->is_rifx ? read_be16(fmt+12) : read_le16(fmt+12);
            uint16_t bits = p->is_rifx ? read_be16(fmt+14) : read_le16(fmt+14);

            p->format_tag = fmt_tag;
            p->block_align = block_align;
            ft->signal.channels = channels;
            ft->signal.rate = sample_rate;

            /* Handle EXTENSIBLE format */
            if (fmt_tag == WAVE_FORMAT_EXTENSIBLE && chunk_size >= 40) {
                fmt_tag = p->is_rifx ? read_be16(fmt+24) : read_le16(fmt+24);
                p->format_tag = fmt_tag;
            }

            switch (fmt_tag) {
                case WAVE_FORMAT_PCM:
                    if (bits > 8)
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                    else
                        ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
                    ft->encoding.bits_per_sample = bits;
                    break;
                case WAVE_FORMAT_IEEE_FLOAT:
                    ft->encoding.encoding = SOX_ENCODING_FLOAT;
                    ft->encoding.bits_per_sample = bits;
                    break;
                case WAVE_FORMAT_MULAW:
                    ft->encoding.encoding = SOX_ENCODING_ULAW;
                    ft->encoding.bits_per_sample = 8;
                    break;
                case WAVE_FORMAT_ALAW:
                    ft->encoding.encoding = SOX_ENCODING_ALAW;
                    ft->encoding.bits_per_sample = 8;
                    break;
                case WAVE_FORMAT_IMA_ADPCM:
                    ft->encoding.encoding = SOX_ENCODING_IMA_ADPCM;
                    ft->encoding.bits_per_sample = 4;
                    break;
                case WAVE_FORMAT_MS_ADPCM:
                    ft->encoding.encoding = SOX_ENCODING_MS_ADPCM;
                    ft->encoding.bits_per_sample = 4;
                    break;
                default:
                    ft->encoding.encoding = SOX_ENCODING_SIGN2;
                    ft->encoding.bits_per_sample = bits;
                    break;
            }
            ft->signal.precision = get_precision(ft->encoding.encoding, 
                                                   ft->encoding.bits_per_sample);
            found_fmt = 1;
        } else if (memcmp(chbuf, "data", 4) == 0) {
            if (!found_fmt) {
                lsx_fail("wav: missing fmt chunk before data");
                return SOX_EOF;
            }
            p->data_offset = ftell(ft->fp);
            p->data_size = chunk_size;
            ft->data_start = p->data_offset;

            /* Calculate number of samples */
            unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
            if (bytes_per_sample > 0 && ft->signal.channels > 0) {
                uint64_t total_samples = chunk_size / bytes_per_sample;
                ft->signal.length = total_samples / ft->signal.channels;
            }
            found_data = 1;
        } else if (memcmp(chbuf, "JUNK", 4) == 0 ||
                   memcmp(chbuf, "PAD ", 4) == 0 ||
                   memcmp(chbuf, "FLLR", 4) == 0) {
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        } else if (memcmp(chbuf, "LIST", 4) == 0) {
            /* LIST chunk - may contain metadata */
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        } else {
            /* Unknown chunk - skip */
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        }
    }

    /* Get file size */
    long pos = ftell(ft->fp);
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, pos, SEEK_SET);

    return SOX_SUCCESS;
}

static size_t wav_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    wav_priv_t *p = (wav_priv_t *)ft->priv;
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];

    /* Check for IMA_ADPCM or MS_ADPCM - simplified handling */
    if (ft->encoding.encoding == SOX_ENCODING_IMA_ADPCM ||
        ft->encoding.encoding == SOX_ENCODING_MS_ADPCM) {
        /* For now just return silence */
        memset(buf, 0, len * sizeof(sox_sample_t));
        return 0;
    }

    for (i = 0; i < len; i++) {
        if (fread(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
        int be = p->is_rifx;
        buf[i] = bytes_to_sample(raw, ft->encoding.bits_per_sample,
                                  ft->encoding.encoding, be);
    }
    return i;
}

static int wav_stopread(sox_format_t *ft) {
    (void)ft;
    return SOX_SUCCESS;
}

static int wav_startwrite(sox_format_t *ft) {
    wav_priv_t *p = (wav_priv_t *)ft->priv;
    uint8_t header[44];
    memset(header, 0, sizeof(header));

    p->is_rifx = 0;

    /* RIFF header - write placeholder */
    memcpy(header, "RIFF", 4);
    write_le32(header+4, 0);  /* size placeholder */
    memcpy(header+8, "WAVE", 4);

    /* fmt chunk */
    memcpy(header+12, "fmt ", 4);
    write_le32(header+16, 16);  /* chunk size */

    uint16_t fmt_tag;
    unsigned bits = ft->encoding.bits_per_sample;
    switch (ft->encoding.encoding) {
        case SOX_ENCODING_FLOAT: fmt_tag = WAVE_FORMAT_IEEE_FLOAT; break;
        case SOX_ENCODING_ULAW: fmt_tag = WAVE_FORMAT_MULAW; bits = 8; break;
        case SOX_ENCODING_ALAW: fmt_tag = WAVE_FORMAT_ALAW; bits = 8; break;
        case SOX_ENCODING_IMA_ADPCM: fmt_tag = WAVE_FORMAT_IMA_ADPCM; break;
        case SOX_ENCODING_MS_ADPCM: fmt_tag = WAVE_FORMAT_MS_ADPCM; break;
        default: fmt_tag = WAVE_FORMAT_PCM; break;
    }
    write_le16(header+20, fmt_tag);
    write_le16(header+22, (uint16_t)ft->signal.channels);
    write_le32(header+24, (uint32_t)ft->signal.rate);
    uint32_t byte_rate = (uint32_t)(ft->signal.rate * ft->signal.channels * bits / 8);
    write_le32(header+28, byte_rate);
    uint16_t block_align = (uint16_t)(ft->signal.channels * bits / 8);
    write_le16(header+32, block_align);
    write_le16(header+34, (uint16_t)bits);

    /* data chunk header */
    memcpy(header+36, "data", 4);
    write_le32(header+40, 0);  /* size placeholder */

    p->data_offset = 44;

    if (fwrite(header, 1, 44, ft->fp) != 44) {
        lsx_fail("wav: error writing header");
        return SOX_EOF;
    }

    ft->data_start = 44;
    return SOX_SUCCESS;
}

static size_t wav_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];

    for (i = 0; i < len; i++) {
        sample_to_bytes(raw, buf[i], ft->encoding.bits_per_sample,
                         ft->encoding.encoding, 0, &ft->clips);
        if (fwrite(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
    }
    return i;
}

static int wav_stopwrite(sox_format_t *ft) {
    /* Update size fields */
    long end_pos = ftell(ft->fp);
    uint32_t data_size = (uint32_t)(end_pos - 44);
    uint32_t riff_size = data_size + 36;

    fseek(ft->fp, 4, SEEK_SET);
    uint8_t buf[4];
    write_le32(buf, riff_size);
    fwrite(buf, 1, 4, ft->fp);

    fseek(ft->fp, 40, SEEK_SET);
    write_le32(buf, data_size);
    fwrite(buf, 1, 4, ft->fp);

    return SOX_SUCCESS;
}

/* =====================================================================
 * FORMAT: AU (SUN/NeXT)
 * ===================================================================== */

#define AU_MAGIC 0x2e736e64  /* .snd */

/* AU encoding codes */
#define AU_ENCODING_ULAW    1
#define AU_ENCODING_PCM8    2
#define AU_ENCODING_PCM16   3
#define AU_ENCODING_PCM24   4
#define AU_ENCODING_PCM32   5
#define AU_ENCODING_FLOAT32 6
#define AU_ENCODING_FLOAT64 7
#define AU_ENCODING_ALAW    27

typedef struct {
    uint32_t header_size;
    uint32_t data_size;
    uint32_t au_encoding;
} au_priv_t;

static int au_startread(sox_format_t *ft) {
    au_priv_t *p = (au_priv_t *)ft->priv;
    uint8_t header[28];

    if (fread(header, 1, 24, ft->fp) != 24) {
        lsx_fail("au: can't read header");
        return SOX_EOF;
    }

    uint32_t magic = read_be32(header);
    if (magic != AU_MAGIC) {
        lsx_fail("au: not an AU file (magic=%08x)", magic);
        return SOX_EOF;
    }

    p->header_size = read_be32(header+4);
    p->data_size = read_be32(header+8);
    p->au_encoding = read_be32(header+12);
    ft->signal.rate = read_be32(header+16);
    ft->signal.channels = read_be32(header+20);

    /* Read annotation if present */
    if (p->header_size > 24) {
        uint32_t ann_len = p->header_size - 24;
        char *ann = malloc(ann_len + 1);
        if (ann) {
            uint32_t n = (uint32_t)fread(ann, 1, ann_len, ft->fp);
            ann[n] = '\0';
            /* Remove trailing nulls */
            while (n > 0 && ann[n-1] == '\0') n--;
            ann[n] = '\0';
            if (n > 0) {
                ft->oob.comment = ann;
            } else {
                free(ann);
            }
        }
    } else {
        fseek(ft->fp, p->header_size, SEEK_SET);
    }

    ft->data_start = p->header_size;

    /* Map AU encoding to Sox encoding */
    switch (p->au_encoding) {
        case AU_ENCODING_ULAW:
            ft->encoding.encoding = SOX_ENCODING_ULAW;
            ft->encoding.bits_per_sample = 8;
            break;
        case AU_ENCODING_PCM8:
            ft->encoding.encoding = SOX_ENCODING_SIGN2;
            ft->encoding.bits_per_sample = 8;
            break;
        case AU_ENCODING_PCM16:
            ft->encoding.encoding = SOX_ENCODING_SIGN2;
            ft->encoding.bits_per_sample = 16;
            break;
        case AU_ENCODING_PCM24:
            ft->encoding.encoding = SOX_ENCODING_SIGN2;
            ft->encoding.bits_per_sample = 24;
            break;
        case AU_ENCODING_PCM32:
            ft->encoding.encoding = SOX_ENCODING_SIGN2;
            ft->encoding.bits_per_sample = 32;
            break;
        case AU_ENCODING_FLOAT32:
            ft->encoding.encoding = SOX_ENCODING_FLOAT;
            ft->encoding.bits_per_sample = 32;
            break;
        case AU_ENCODING_FLOAT64:
            ft->encoding.encoding = SOX_ENCODING_FLOAT;
            ft->encoding.bits_per_sample = 64;
            break;
        case AU_ENCODING_ALAW:
            ft->encoding.encoding = SOX_ENCODING_ALAW;
            ft->encoding.bits_per_sample = 8;
            break;
        default:
            lsx_fail("au: unsupported encoding %u", p->au_encoding);
            return SOX_EOF;
    }

    ft->signal.precision = get_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);

    /* Calculate length */
    unsigned bps = (ft->encoding.bits_per_sample + 7) / 8;
    if (bps > 0 && ft->signal.channels > 0) {
        uint32_t data_bytes = p->data_size;
        if (data_bytes == 0xFFFFFFFF) {
            /* Unknown size - read to EOF */
            fseek(ft->fp, 0, SEEK_END);
            long end = ftell(ft->fp);
            fseek(ft->fp, ft->data_start, SEEK_SET);
            data_bytes = (uint32_t)(end - ft->data_start);
        }
        ft->signal.length = (data_bytes / bps) / ft->signal.channels;
    }

    /* Get file size */
    long pos = ftell(ft->fp);
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, pos, SEEK_SET);

    return SOX_SUCCESS;
}

static size_t au_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];
    for (i = 0; i < len; i++) {
        if (fread(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
        buf[i] = bytes_to_sample(raw, ft->encoding.bits_per_sample,
                                  ft->encoding.encoding, 1);  /* big endian */
    }
    return i;
}

static int au_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int au_startwrite(sox_format_t *ft) {
    au_priv_t *p = (au_priv_t *)ft->priv;

    /* Determine AU encoding */
    unsigned bits = ft->encoding.bits_per_sample;
    uint32_t au_enc;
    switch (ft->encoding.encoding) {
        case SOX_ENCODING_ULAW: au_enc = AU_ENCODING_ULAW; break;
        case SOX_ENCODING_ALAW: au_enc = AU_ENCODING_ALAW; break;
        case SOX_ENCODING_FLOAT:
            au_enc = (bits == 32) ? AU_ENCODING_FLOAT32 : AU_ENCODING_FLOAT64; break;
        case SOX_ENCODING_SIGN2:
        default:
            if (bits == 8) au_enc = AU_ENCODING_PCM8;
            else if (bits == 16) au_enc = AU_ENCODING_PCM16;
            else if (bits == 24) au_enc = AU_ENCODING_PCM24;
            else au_enc = AU_ENCODING_PCM32;
            break;
    }
    p->au_encoding = au_enc;

    /* Determine annotation */
    const char *comment = ft->oob.comment ? ft->oob.comment : "Processed by SoX";
    size_t ann_len = strlen(comment);
    /* Header must be multiple of 8 */
    uint32_t hdr_size = 24 + (uint32_t)ann_len + 1;
    hdr_size = (hdr_size + 7) & ~7;

    p->header_size = hdr_size;

    /* Write header */
    uint8_t hdr[256];
    memset(hdr, 0, sizeof(hdr));
    write_be32(hdr+0, AU_MAGIC);
    write_be32(hdr+4, hdr_size);
    write_be32(hdr+8, 0xFFFFFFFF);  /* unknown data size */
    write_be32(hdr+12, au_enc);
    write_be32(hdr+16, (uint32_t)ft->signal.rate);
    write_be32(hdr+20, ft->signal.channels);

    /* Copy annotation */
    memcpy(hdr+24, comment, ann_len);

    if (fwrite(hdr, 1, hdr_size, ft->fp) != hdr_size) {
        lsx_fail("au: error writing header");
        return SOX_EOF;
    }

    ft->data_start = hdr_size;
    return SOX_SUCCESS;
}

static size_t au_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];
    for (i = 0; i < len; i++) {
        sample_to_bytes(raw, buf[i], ft->encoding.bits_per_sample,
                         ft->encoding.encoding, 1, &ft->clips);
        if (fwrite(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
    }
    return i;
}

static int au_stopwrite(sox_format_t *ft) {
    /* Update data size */
    au_priv_t *p = (au_priv_t *)ft->priv;
    long end_pos = ftell(ft->fp);
    uint32_t data_size = (uint32_t)(end_pos - p->header_size);

    fseek(ft->fp, 8, SEEK_SET);
    uint8_t buf[4];
    write_be32(buf, data_size);
    fwrite(buf, 1, 4, ft->fp);

    return SOX_SUCCESS;
}

