/* =====================================================================
 * FORMAT: AIFF / AIFC
 * ===================================================================== */

/* AIFF chunk types */
#define AIFF_COMM  "COMM"
#define AIFF_SSND  "SSND"
#define AIFF_MARK  "MARK"
#define AIFF_INST  "INST"
#define AIFF_NAME  "NAME"
#define AIFF_AUTH  "AUTH"
#define AIFF_ANNO  "ANNO"

/* AIFC compression types */
#define AIFC_NONE  0x4e4f4e45  /* 'NONE' */
#define AIFC_ULAW  0x756c6177  /* 'ulaw' */
#define AIFC_ALAW  0x616c6177  /* 'alaw' */
#define AIFC_FL32  0x666c3332  /* 'fl32' */
#define AIFC_FL64  0x666c3634  /* 'fl64' */
#define AIFC_SOWT  0x736f7774  /* 'sowt' - little endian */

typedef struct {
    uint32_t ssnd_offset;
    uint32_t ssnd_blksize;
    uint32_t comm_channels;
    uint32_t comm_frames;
    uint16_t comm_bits;
    uint32_t aifc_comp;  /* 0 = AIFF, else AIFC compression code */
    int is_aiff;         /* 1 = AIFF, 0 = AIFC */
    uint32_t data_offset_in_file;
} aiff_priv_t;

/* Convert 80-bit IEEE 754 extended to double */
static double ieee80_to_double(const uint8_t *buf) {
    int sign = (buf[0] >> 7) & 1;
    int exp = ((buf[0] & 0x7F) << 8) | buf[1];
    uint64_t mant = 0;
    int i;
    for (i = 0; i < 8; i++) mant = (mant << 8) | buf[2+i];

    if (exp == 0 && mant == 0) return 0.0;
    if (exp == 0x7FFF) return sign ? -1e300 * 1e300 : 1e300 * 1e300;

    exp -= 16383;
    double d = (double)mant / 9223372036854775808.0;  /* 2^63 */
    d = ldexp(d, exp);
    return sign ? -d : d;
}

/* Convert double to 80-bit IEEE 754 extended */
static void double_to_ieee80(uint8_t *buf, double d) {
    int sign = 0;
    int exp = 0;
    uint64_t mant = 0;

    if (d < 0) { sign = 1; d = -d; }

    if (d == 0.0) {
        memset(buf, 0, 10);
        return;
    }

    double f = frexp(d, &exp);
    exp += 16382;
    mant = (uint64_t)(f * 9223372036854775808.0 * 2.0);  /* 2^64 */

    buf[0] = (uint8_t)((sign << 7) | (exp >> 8));
    buf[1] = (uint8_t)(exp & 0xFF);
    int i;
    for (i = 7; i >= 0; i--) {
        buf[2+i] = (uint8_t)(mant & 0xFF);
        mant >>= 8;
    }
}

static int aiff_startread(sox_format_t *ft) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;
    uint8_t buf[12];

    if (fread(buf, 1, 12, ft->fp) != 12) {
        lsx_fail("aiff: can't read header");
        return SOX_EOF;
    }

    if (memcmp(buf, "FORM", 4) != 0) {
        lsx_fail("aiff: not an AIFF file");
        return SOX_EOF;
    }

    if (memcmp(buf+8, "AIFF", 4) == 0) {
        p->is_aiff = 1;
        p->aifc_comp = AIFC_NONE;
    } else if (memcmp(buf+8, "AIFC", 4) == 0) {
        p->is_aiff = 0;
    } else {
        lsx_fail("aiff: not an AIFF/AIFC file");
        return SOX_EOF;
    }

    int found_comm = 0, found_ssnd = 0;
    uint32_t file_size = read_be32(buf+4);

    while (!found_ssnd) {
        uint8_t chbuf[8];
        if (fread(chbuf, 1, 8, ft->fp) != 8) {
            if (found_comm) {
                ft->signal.length = 0;
                break;
            }
            lsx_fail("aiff: unexpected EOF");
            return SOX_EOF;
        }
        uint32_t chunk_size = read_be32(chbuf+4);

        if (memcmp(chbuf, "COMM", 4) == 0) {
            uint8_t comm[26];
            uint32_t to_read = chunk_size < 26 ? chunk_size : 26;
            if (fread(comm, 1, to_read, ft->fp) != to_read) {
                lsx_fail("aiff: can't read COMM chunk");
                return SOX_EOF;
            }
            if (chunk_size > to_read)
                fseek(ft->fp, chunk_size - to_read, SEEK_CUR);
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);

            ft->signal.channels = read_be16(comm);
            uint32_t num_frames = read_be32(comm+2);
            uint16_t bits = read_be16(comm+6);
            double rate = ieee80_to_double(comm+8);

            ft->signal.rate = rate;

            if (p->is_aiff) {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = bits;
            } else {
                /* AIFC - read compression type if available */
                if (chunk_size >= 22) {
                    p->aifc_comp = read_be32(comm+18);
                } else {
                    p->aifc_comp = AIFC_NONE;
                }

                switch (p->aifc_comp) {
                    case AIFC_NONE:
                    case AIFC_SOWT:
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                        ft->encoding.bits_per_sample = bits;
                        break;
                    case AIFC_ULAW:
                        ft->encoding.encoding = SOX_ENCODING_ULAW;
                        ft->encoding.bits_per_sample = 8;
                        break;
                    case AIFC_ALAW:
                        ft->encoding.encoding = SOX_ENCODING_ALAW;
                        ft->encoding.bits_per_sample = 8;
                        break;
                    case AIFC_FL32:
                        ft->encoding.encoding = SOX_ENCODING_FLOAT;
                        ft->encoding.bits_per_sample = 32;
                        break;
                    case AIFC_FL64:
                        ft->encoding.encoding = SOX_ENCODING_FLOAT;
                        ft->encoding.bits_per_sample = 64;
                        break;
                    default:
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                        ft->encoding.bits_per_sample = bits;
                        break;
                }
            }
            ft->signal.precision = get_precision(ft->encoding.encoding,
                                                   ft->encoding.bits_per_sample);
            p->comm_frames = num_frames;
            ft->signal.length = num_frames;
            found_comm = 1;
        } else if (memcmp(chbuf, "SSND", 4) == 0) {
            uint8_t ssnd[8];
            if (fread(ssnd, 1, 8, ft->fp) != 8) {
                lsx_fail("aiff: can't read SSND header");
                return SOX_EOF;
            }
            p->ssnd_offset = read_be32(ssnd);
