    uint32_t data_bytes = (uint32_t)(end_pos - p->data_offset_in_file);
    if (data_bytes & 1) { fputc(0, ft->fp); end_pos++; }

    /* Update FORM size */
    uint32_t form_size = (uint32_t)(end_pos - 8);
    fseek(ft->fp, 4, SEEK_SET);
    uint8_t buf[4];
    write_be32(buf, form_size);
    fwrite(buf, 1, 4, ft->fp);

