    /* Find COMM chunk in file - it's right after FORM header (12 bytes) */
    uint32_t bps = ft->encoding.bits_per_sample;
    uint32_t channels = ft->signal.channels;
    uint32_t bps_bytes = (bps + 7) / 8;
    uint32_t num_frames = data_bytes / (bps_bytes * channels);

