/* =====================================================================
 * FORMAT: AIFF / AIFC
 * ===================================================================== */

/* AIFF chunk types */
#define AIFF_COMM  "COMM"
#define AIFF_SSND  "SSND"
#define AIFF_MARK  "MARK"
#define AIFF_INST  "INST"
#define AIFF_NAME  "NAME"
#define AIFF_AUTH  "AUTH"
#define AIFF_ANNO  "ANNO"

/* AIFC compression types */
#define AIFC_NONE  0x4e4f4e45  /* 'NONE' */
#define AIFC_ULAW  0x756c6177  /* 'ulaw' */
#define AIFC_ALAW  0x616c6177  /* 'alaw' */
#define AIFC_FL32  0x666c3332  /* 'fl32' */
#define AIFC_FL64  0x666c3634  /* 'fl64' */
#define AIFC_SOWT  0x736f7774  /* 'sowt' - little endian */

typedef struct {
    uint32_t ssnd_offset;
    uint32_t ssnd_blksize;
    uint32_t comm_channels;
    uint32_t comm_frames;
    uint16_t comm_bits;
    uint32_t aifc_comp;  /* 0 = AIFF, else AIFC compression code */
    int is_aiff;         /* 1 = AIFF, 0 = AIFC */
    uint32_t data_offset_in_file;
} aiff_priv_t;

/* Convert 80-bit IEEE 754 extended to double */
static double ieee80_to_double(const uint8_t *buf) {
    int sign = (buf[0] >> 7) & 1;
    int exp = ((buf[0] & 0x7F) << 8) | buf[1];
    uint64_t mant = 0;
    int i;
    for (i = 0; i < 8; i++) mant = (mant << 8) | buf[2+i];

    if (exp == 0 && mant == 0) return 0.0;
    if (exp == 0x7FFF) return sign ? -1e300 * 1e300 : 1e300 * 1e300;

    exp -= 16383;
    double d = (double)mant / 9223372036854775808.0;  /* 2^63 */
    d = ldexp(d, exp);
    return sign ? -d : d;
}

/* Convert double to 80-bit IEEE 754 extended */
static void double_to_ieee80(uint8_t *buf, double d) {
    int sign = 0;
    int exp = 0;
    uint64_t mant = 0;

    if (d < 0) { sign = 1; d = -d; }

    if (d == 0.0) {
        memset(buf, 0, 10);
        return;
    }

    double f = frexp(d, &exp);
    exp += 16382;
    mant = (uint64_t)(f * 9223372036854775808.0 * 2.0);  /* 2^64 */

    buf[0] = (uint8_t)((sign << 7) | (exp >> 8));
    buf[1] = (uint8_t)(exp & 0xFF);
    int i;
    for (i = 7; i >= 0; i--) {
        buf[2+i] = (uint8_t)(mant & 0xFF);
        mant >>= 8;
    }
}

static int aiff_startread(sox_format_t *ft) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;
    uint8_t buf[12];

    if (fread(buf, 1, 12, ft->fp) != 12) {
        lsx_fail("aiff: can't read header");
        return SOX_EOF;
    }

    if (memcmp(buf, "FORM", 4) != 0) {
        lsx_fail("aiff: not an AIFF file");
        return SOX_EOF;
    }

    if (memcmp(buf+8, "AIFF", 4) == 0) {
        p->is_aiff = 1;
        p->aifc_comp = AIFC_NONE;
    } else if (memcmp(buf+8, "AIFC", 4) == 0) {
        p->is_aiff = 0;
    } else {
        lsx_fail("aiff: not an AIFF/AIFC file");
        return SOX_EOF;
    }

    int found_comm = 0, found_ssnd = 0;
    uint32_t file_size = read_be32(buf+4);

    while (!found_ssnd) {
        uint8_t chbuf[8];
        if (fread(chbuf, 1, 8, ft->fp) != 8) {
            if (found_comm) {
                ft->signal.length = 0;
                break;
            }
            lsx_fail("aiff: unexpected EOF");
            return SOX_EOF;
        }
        uint32_t chunk_size = read_be32(chbuf+4);

        if (memcmp(chbuf, "COMM", 4) == 0) {
            uint8_t comm[26];
            uint32_t to_read = chunk_size < 26 ? chunk_size : 26;
            if (fread(comm, 1, to_read, ft->fp) != to_read) {
                lsx_fail("aiff: can't read COMM chunk");
                return SOX_EOF;
            }
            if (chunk_size > to_read)
                fseek(ft->fp, chunk_size - to_read, SEEK_CUR);
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);

            ft->signal.channels = read_be16(comm);
            uint32_t num_frames = read_be32(comm+2);
            uint16_t bits = read_be16(comm+6);
            double rate = ieee80_to_double(comm+8);

            ft->signal.rate = rate;

            if (p->is_aiff) {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = bits;
            } else {
                /* AIFC - read compression type if available */
                if (chunk_size >= 22) {
                    p->aifc_comp = read_be32(comm+18);
                } else {
                    p->aifc_comp = AIFC_NONE;
                }

                switch (p->aifc_comp) {
                    case AIFC_NONE:
                    case AIFC_SOWT:
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                        ft->encoding.bits_per_sample = bits;
                        break;
                    case AIFC_ULAW:
                        ft->encoding.encoding = SOX_ENCODING_ULAW;
                        ft->encoding.bits_per_sample = 8;
                        break;
                    case AIFC_ALAW:
                        ft->encoding.encoding = SOX_ENCODING_ALAW;
                        ft->encoding.bits_per_sample = 8;
                        break;
                    case AIFC_FL32:
                        ft->encoding.encoding = SOX_ENCODING_FLOAT;
                        ft->encoding.bits_per_sample = 32;
                        break;
                    case AIFC_FL64:
                        ft->encoding.encoding = SOX_ENCODING_FLOAT;
                        ft->encoding.bits_per_sample = 64;
                        break;
                    default:
                        ft->encoding.encoding = SOX_ENCODING_SIGN2;
                        ft->encoding.bits_per_sample = bits;
                        break;
                }
            }
            ft->signal.precision = get_precision(ft->encoding.encoding,
                                                   ft->encoding.bits_per_sample);
            p->comm_frames = num_frames;
            ft->signal.length = num_frames;
            found_comm = 1;
        } else if (memcmp(chbuf, "SSND", 4) == 0) {
            uint8_t ssnd[8];
            if (fread(ssnd, 1, 8, ft->fp) != 8) {
                lsx_fail("aiff: can't read SSND header");
                return SOX_EOF;
            }
            p->ssnd_offset = read_be32(ssnd);
            p->ssnd_blksize = read_be32(ssnd+4);
            fseek(ft->fp, p->ssnd_offset, SEEK_CUR);
            ft->data_start = ftell(ft->fp);
            p->data_offset_in_file = ft->data_start;
            found_ssnd = 1;
        } else if (memcmp(chbuf, "ANNO", 4) == 0) {
            char *ann = malloc(chunk_size + 1);
            if (ann) {
                uint32_t n = (uint32_t)fread(ann, 1, chunk_size, ft->fp);
                ann[n] = '\0';
                while (n > 0 && ann[n-1] == '\0') n--;
                ann[n] = '\0';
                if (n > 0) {
                    free(ft->oob.comment);
                    ft->oob.comment = ann;
                } else free(ann);
            }
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);
        } else if (memcmp(chbuf, "NAME", 4) == 0) {
            if (!ft->oob.comment) {
                char *name = malloc(chunk_size + 1);
                if (name) {
                    uint32_t n = (uint32_t)fread(name, 1, chunk_size, ft->fp);
                    name[n] = '\0';
                    ft->oob.comment = name;
                }
            } else fseek(ft->fp, chunk_size, SEEK_CUR);
            if (chunk_size & 1) fseek(ft->fp, 1, SEEK_CUR);
        } else {
            fseek(ft->fp, chunk_size + (chunk_size & 1), SEEK_CUR);
        }
    }

    /* Get file size */
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    if (found_ssnd) fseek(ft->fp, ft->data_start, SEEK_SET);

    (void)file_size;
    return SOX_SUCCESS;
}

static size_t aiff_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];

    int little_endian = (p->aifc_comp == AIFC_SOWT);

    for (i = 0; i < len; i++) {
        if (fread(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
        buf[i] = bytes_to_sample(raw, ft->encoding.bits_per_sample,
                                  ft->encoding.encoding, !little_endian);
    }
    return i;
}

static int aiff_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int aiff_startwrite(sox_format_t *ft) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;

    p->is_aiff = 1;

    /* Determine if AIFF or AIFC */
    switch (ft->encoding.encoding) {
        case SOX_ENCODING_ULAW:
        case SOX_ENCODING_ALAW:
        case SOX_ENCODING_FLOAT:
            p->is_aiff = 0;  /* AIFC */
            break;
        default:
            p->is_aiff = 1;  /* AIFF */
            break;
    }

    /* Write placeholder header - we'll fix it up at the end */
    /* For now write a minimal header */
    const char *comment = ft->oob.comment ? ft->oob.comment : "Processed by SoX";
    size_t ann_len = strlen(comment);

    /* Calculate chunk sizes */
    /* COMM chunk: 18 bytes for AIFF, 24+ for AIFC */
    uint32_t comm_size = p->is_aiff ? 18 : 24;
    /* ANNO chunk: ann_len + optional padding */
    uint32_t anno_size = (uint32_t)ann_len;
    uint32_t anno_padded = anno_size + (anno_size & 1);
    /* SSND chunk: 8 bytes header + data (filled later) */

    /* Write FORM header placeholder */
    uint8_t hdr[12];
    memcpy(hdr, "FORM", 4);
    write_be32(hdr+4, 0);  /* placeholder */
    memcpy(hdr+8, p->is_aiff ? "AIFF" : "AIFC", 4);
    fwrite(hdr, 1, 12, ft->fp);

    /* Write COMM chunk */
    uint8_t comm_hdr[8];
    memcpy(comm_hdr, "COMM", 4);
    write_be32(comm_hdr+4, comm_size);
    fwrite(comm_hdr, 1, 8, ft->fp);

    uint8_t comm[26];
    memset(comm, 0, sizeof(comm));
    write_be16(comm, (uint16_t)ft->signal.channels);
    write_be32(comm+2, 0);  /* numSampleFrames placeholder */
    write_be16(comm+6, (uint16_t)ft->encoding.bits_per_sample);
    double_to_ieee80(comm+8, ft->signal.rate);

    if (!p->is_aiff) {
        /* AIFC compression type */
        uint32_t comp = AIFC_NONE;
        switch (ft->encoding.encoding) {
            case SOX_ENCODING_ULAW: comp = AIFC_ULAW; break;
            case SOX_ENCODING_ALAW: comp = AIFC_ALAW; break;
            case SOX_ENCODING_FLOAT:
                comp = (ft->encoding.bits_per_sample == 32) ? AIFC_FL32 : AIFC_FL64;
                break;
            default: comp = AIFC_NONE; break;
        }
        write_be32(comm+18, comp);
        /* compression name - Pascal string */
        comm[22] = 0;  /* empty string */
    }

    fwrite(comm, 1, comm_size, ft->fp);
    if (comm_size & 1) fputc(0, ft->fp);

    /* Write ANNO chunk */
    uint8_t anno_hdr[8];
    memcpy(anno_hdr, "ANNO", 4);
    write_be32(anno_hdr+4, anno_size);
    fwrite(anno_hdr, 1, 8, ft->fp);
    fwrite(comment, 1, ann_len, ft->fp);
    if (anno_size & 1) fputc(0, ft->fp);

    /* Write SSND chunk header */
    uint8_t ssnd_hdr[16];
    memcpy(ssnd_hdr, "SSND", 4);
    write_be32(ssnd_hdr+4, 0);  /* placeholder */
    write_be32(ssnd_hdr+8, 0);  /* offset */
    write_be32(ssnd_hdr+12, 0); /* blockSize */
    fwrite(ssnd_hdr, 1, 16, ft->fp);

    ft->data_start = ftell(ft->fp);
    p->data_offset_in_file = ft->data_start;

    return SOX_SUCCESS;
}

static size_t aiff_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    size_t i;
    uint8_t raw[8];
    int little_endian = (p->aifc_comp == AIFC_SOWT);

    for (i = 0; i < len; i++) {
        sample_to_bytes(raw, buf[i], ft->encoding.bits_per_sample,
                         ft->encoding.encoding, !little_endian, &ft->clips);
        if (fwrite(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
    }
    return i;
}

static int aiff_stopwrite(sox_format_t *ft) {
    aiff_priv_t *p = (aiff_priv_t *)ft->priv;
    long end_pos = ftell(ft->fp);

    /* Pad data to even size */
    uint32_t data_bytes = (uint32_t)(end_pos - p->data_offset_in_file);
    if (data_bytes & 1) { fputc(0, ft->fp); end_pos++; }

    /* Update FORM size */
    uint32_t form_size = (uint32_t)(end_pos - 8);
    fseek(ft->fp, 4, SEEK_SET);
    uint8_t buf[4];
    write_be32(buf, form_size);
    fwrite(buf, 1, 4, ft->fp);

    /* Update COMM numSampleFrames */
    /* Find COMM chunk in file - it's right after FORM header (12 bytes) */
    uint32_t bps = ft->encoding.bits_per_sample;
    uint32_t channels = ft->signal.channels;
    uint32_t bps_bytes = (bps + 7) / 8;
    uint32_t num_frames = data_bytes / (bps_bytes * channels);

    /* COMM is at offset 12+8 = 20, numSampleFrames at offset 20+2 = 22 */
    fseek(ft->fp, 22, SEEK_SET);
    write_be32(buf, num_frames);
    fwrite(buf, 1, 4, ft->fp);

    /* Find SSND chunk and update its size */
    /* SSND is after COMM (at 12+8+comm_size+8+anno_with_padding...) - complicated */
    /* Instead let's just find it by position */
    /* SSND data_offset_in_file - 8 (ssnd header) = position of SSND chunk */
    uint32_t ssnd_data_size = data_bytes + 8;  /* 8 for offset+blockSize fields */
    fseek(ft->fp, p->data_offset_in_file - 8, SEEK_SET);
    /* Verify it's SSND */
    uint8_t chunk_id[4];
    fread(chunk_id, 1, 4, ft->fp);
    if (memcmp(chunk_id, "SSND", 4) == 0) {
        write_be32(buf, ssnd_data_size);
        fwrite(buf, 1, 4, ft->fp);
    }

    return SOX_SUCCESS;
}

/* =====================================================================
 * FORMAT: RAW (headerless PCM)
 * ===================================================================== */

static int raw_startread(sox_format_t *ft) {
    /* Signal info must be provided externally */
    if (ft->signal.rate == 0) ft->signal.rate = SOX_DEFAULT_RATE;
    if (ft->signal.channels == 0) ft->signal.channels = SOX_DEFAULT_CHANNELS;
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN) {
        ft->encoding.encoding = SOX_ENCODING_SIGN2;
        ft->encoding.bits_per_sample = 16;
    }
    ft->signal.precision = get_precision(ft->encoding.encoding, ft->encoding.bits_per_sample);

    /* Get file size and calculate length */
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, 0, SEEK_SET);

    unsigned bps = (ft->encoding.bits_per_sample + 7) / 8;
    if (bps > 0 && ft->signal.channels > 0) {
        ft->signal.length = (ft->filesize / bps) / ft->signal.channels;
    }
    ft->data_start = 0;
    return SOX_SUCCESS;
}

static size_t raw_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    int big_endian = ft->encoding.reverse_bytes ? !is_bigendian() : is_bigendian();
    /* For raw, default is little endian unless specified */
    big_endian = ft->encoding.opposite_endian ? !big_endian : big_endian;
    /* Check if format specifies endianness */
    if (ft->encoding.reverse_bytes) big_endian = !big_endian;
    /* Default for raw is native (usually little-endian) */
    /* Actually, raw defaults to little-endian on little-endian systems */
    /* Let's use ft->handler->flags to determine endianness */
    /* For now, use the encoding's settings */
    big_endian = 0;  /* raw defaults to little endian */
    if (ft->encoding.reverse_bytes) big_endian = 1;

    size_t i;
    uint8_t raw[8];
    for (i = 0; i < len; i++) {
        if (fread(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
        buf[i] = bytes_to_sample(raw, ft->encoding.bits_per_sample,
                                  ft->encoding.encoding, big_endian);
    }
    return i;
}

static int raw_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int raw_startwrite(sox_format_t *ft) {
    ft->data_start = 0;
    return SOX_SUCCESS;
}

static size_t raw_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    unsigned bytes_per_sample = (ft->encoding.bits_per_sample + 7) / 8;
    int big_endian = 0;
    if (ft->encoding.reverse_bytes) big_endian = 1;

    size_t i;
    uint8_t raw[8];
    for (i = 0; i < len; i++) {
        sample_to_bytes(raw, buf[i], ft->encoding.bits_per_sample,
                         ft->encoding.encoding, big_endian, &ft->clips);
        if (fwrite(raw, 1, bytes_per_sample, ft->fp) != bytes_per_sample) break;
    }
    return i;
}

static int raw_stopwrite(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

