/* =====================================================================
 * FORMAT: DAT (text)
 * ===================================================================== */

static int dat_startread(sox_format_t *ft) {
    char line[256];
    /* Skip comments and read header */
    ft->signal.rate = 8000;
    ft->signal.channels = 1;
    ft->encoding.encoding = SOX_ENCODING_FLOAT;
    ft->encoding.bits_per_sample = 64;
    ft->signal.precision = 54;

    /* Scan for ; SampleRate and ; Channels */
    long start = ftell(ft->fp);
    while (fgets(line, sizeof(line), ft->fp)) {
        if (line[0] == ';') {
            if (strstr(line, "SampleRate")) {
                sscanf(line + 1, " SampleRate %lf", &ft->signal.rate);
            } else if (strstr(line, "Channels")) {
                unsigned ch;
                sscanf(line + 1, " Channels %u", &ch);
                ft->signal.channels = ch;
            }
        } else {
            break;
        }
    }

    fseek(ft->fp, start, SEEK_SET);
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, start, SEEK_SET);
    return SOX_SUCCESS;
}

static size_t dat_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    size_t n = 0;
    char line[1024];
    while (n < len) {
        if (!fgets(line, sizeof(line), ft->fp)) break;
        if (line[0] == ';') continue;
        /* Parse time + samples */
        char *p = line;
        /* Skip time value */
        while (*p && !my_isspace(*p)) p++;
        while (*p && my_isspace(*p)) p++;
        /* Read channel values */
        unsigned ch;
        for (ch = 0; ch < ft->signal.channels && n < len; ch++) {
            double v = strtod(p, &p);
            while (*p && my_isspace(*p)) p++;
            double d = v;
            if (d >= 1.0) d = 1.0 - 1e-15;
            if (d < -1.0) d = -1.0;
            buf[n++] = (sox_sample_t)(d * 2147483648.0);
        }
    }
    return n;
}

static int dat_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int dat_startwrite(sox_format_t *ft) {
    fprintf(ft->fp, "; Sample Rate %g\n", ft->signal.rate);
    fprintf(ft->fp, "; Channels %u\n", ft->signal.channels);
    ft->data_start = 0;
    return SOX_SUCCESS;
}

static size_t dat_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    static uint64_t sample_count = 0;
    size_t i = 0;
    unsigned ch;

    while (i < len) {
        double t = (double)sample_count / ft->signal.rate;
        fprintf(ft->fp, "%-16.8g", t);
        for (ch = 0; ch < ft->signal.channels && i < len; ch++, i++) {
            double v = (double)buf[i] / 2147483648.0;
            fprintf(ft->fp, " % .8f", v);
        }
        fprintf(ft->fp, "\n");
        sample_count++;
    }
    return i;
}

static int dat_stopwrite(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

/* =====================================================================
 * FORMAT: SOX (native)
 * ===================================================================== */

#define SOX_MAGIC  "Sox!"
#define SOX_MAGIC_V2 0x534f5821

typedef struct {
    uint32_t version;
} soxfmt_priv_t;

static int sox_fmt_startread(sox_format_t *ft) {
    uint8_t buf[32];
    if (fread(buf, 1, 32, ft->fp) != 32) return SOX_EOF;

    if (memcmp(buf, SOX_MAGIC, 4) != 0) {
        lsx_fail("sox: not a Sox format file");
        return SOX_EOF;
    }

    /* Little-endian header */
    uint32_t header_size = read_le32(buf+4);
    /* uint32_t data_size = read_le32(buf+8); */
    ft->signal.rate = read_le32(buf+12);
    ft->signal.channels = read_le32(buf+16);
    unsigned bits = read_le32(buf+20);

    ft->encoding.encoding = SOX_ENCODING_SIGN2;
    ft->encoding.bits_per_sample = bits;
    ft->signal.precision = bits;

    fseek(ft->fp, header_size, SEEK_SET);
    ft->data_start = header_size;

    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);

    uint32_t data_bytes = (uint32_t)(ft->filesize - header_size);
    unsigned bps = (bits + 7) / 8;
    if (bps > 0 && ft->signal.channels > 0)
