        if (line[0] == ';') {
            if (strstr(line, "SampleRate")) {
                sscanf(line + 1, " SampleRate %lf", &ft->signal.rate);
            } else if (strstr(line, "Channels")) {
                unsigned ch;
                sscanf(line + 1, " Channels %u", &ch);
                ft->signal.channels = ch;
            }
        } else {
            break;
        }
    }

    fseek(ft->fp, start, SEEK_SET);
    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    fseek(ft->fp, start, SEEK_SET);
    return SOX_SUCCESS;
}

static size_t dat_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    size_t n = 0;
    char line[1024];
    while (n < len) {
        if (!fgets(line, sizeof(line), ft->fp)) break;
        if (line[0] == ';') continue;
        /* Parse time + samples */
        char *p = line;
        /* Skip time value */
        while (*p && !my_isspace(*p)) p++;
        while (*p && my_isspace(*p)) p++;
        /* Read channel values */
        unsigned ch;
        for (ch = 0; ch < ft->signal.channels && n < len; ch++) {
            double v = strtod(p, &p);
            while (*p && my_isspace(*p)) p++;
            double d = v;
            if (d >= 1.0) d = 1.0 - 1e-15;
            if (d < -1.0) d = -1.0;
            buf[n++] = (sox_sample_t)(d * 2147483648.0);
        }
    }
    return n;
}

static int dat_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int dat_startwrite(sox_format_t *ft) {
    fprintf(ft->fp, "; Sample Rate %g\n", ft->signal.rate);
    fprintf(ft->fp, "; Channels %u\n", ft->signal.channels);
    ft->data_start = 0;
    return SOX_SUCCESS;
}

static size_t dat_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    static uint64_t sample_count = 0;
    size_t i = 0;
    unsigned ch;

    while (i < len) {
        double t = (double)sample_count / ft->signal.rate;
        fprintf(ft->fp, "%-16.8g", t);
        for (ch = 0; ch < ft->signal.channels && i < len; ch++, i++) {
            double v = (double)buf[i] / 2147483648.0;
            fprintf(ft->fp, " % .8f", v);
        }
        fprintf(ft->fp, "\n");
        sample_count++;
    }
    return i;
}

static int dat_stopwrite(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

/* =====================================================================
 * FORMAT: SOX (native)
 * ===================================================================== */

#define SOX_MAGIC  "Sox!"
#define SOX_MAGIC_V2 0x534f5821

typedef struct {
    uint32_t version;
} soxfmt_priv_t;

static int sox_fmt_startread(sox_format_t *ft) {
    uint8_t buf[32];
    if (fread(buf, 1, 32, ft->fp) != 32) return SOX_EOF;

    if (memcmp(buf, SOX_MAGIC, 4) != 0) {
        lsx_fail("sox: not a Sox format file");
        return SOX_EOF;
    }

    /* Little-endian header */
    uint32_t header_size = read_le32(buf+4);
    /* uint32_t data_size = read_le32(buf+8); */
    ft->signal.rate = read_le32(buf+12);
    ft->signal.channels = read_le32(buf+16);
    unsigned bits = read_le32(buf+20);

    ft->encoding.encoding = SOX_ENCODING_SIGN2;
    ft->encoding.bits_per_sample = bits;
    ft->signal.precision = bits;

    fseek(ft->fp, header_size, SEEK_SET);
    ft->data_start = header_size;

    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);

    uint32_t data_bytes = (uint32_t)(ft->filesize - header_size);
    unsigned bps = (bits + 7) / 8;
    if (bps > 0 && ft->signal.channels > 0)
        ft->signal.length = (data_bytes / bps) / ft->signal.channels;

    fseek(ft->fp, ft->data_start, SEEK_SET);
    return SOX_SUCCESS;
}

static size_t sox_fmt_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    return raw_read(ft, buf, len);
}

static int sox_fmt_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

static int sox_fmt_startwrite(sox_format_t *ft) {
    uint8_t header[32];
    memset(header, 0, sizeof(header));
    memcpy(header, SOX_MAGIC, 4);
    write_le32(header+4, 32);  /* header size */
    write_le32(header+8, 0);   /* data size placeholder */
    write_le32(header+12, (uint32_t)ft->signal.rate);
    write_le32(header+16, ft->signal.channels);
    write_le32(header+20, ft->encoding.bits_per_sample);
    fwrite(header, 1, 32, ft->fp);
    ft->data_start = 32;
    return SOX_SUCCESS;
}

static size_t sox_fmt_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    return raw_write(ft, buf, len);
}

static int sox_fmt_stopwrite(sox_format_t *ft) {
    long end_pos = ftell(ft->fp);
    uint32_t data_size = (uint32_t)(end_pos - 32);
    fseek(ft->fp, 8, SEEK_SET);
    uint8_t buf[4];
    write_le32(buf, data_size);
    fwrite(buf, 1, 4, ft->fp);
    return SOX_SUCCESS;
}

/* =====================================================================
 * FORMAT: VOC
 * ===================================================================== */

static int voc_startread(sox_format_t *ft) {
    uint8_t header[26];
    if (fread(header, 1, 26, ft->fp) != 26) return SOX_EOF;

    if (memcmp(header, "Creative Voice File\x1a", 20) != 0) {
        lsx_fail("voc: not a VOC file");
        return SOX_EOF;
    }

    uint16_t data_offset = read_le16(header+20);
    fseek(ft->fp, data_offset, SEEK_SET);

    ft->signal.rate = 8000;
    ft->signal.channels = 1;
    ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
    ft->encoding.bits_per_sample = 8;
    ft->signal.precision = 8;

    /* Parse blocks */
    while (1) {
        uint8_t block_type;
        if (fread(&block_type, 1, 1, ft->fp) != 1) break;
        if (block_type == 0) break;  /* terminator */

        uint8_t size_buf[3];
        if (fread(size_buf, 1, 3, ft->fp) != 3) break;
        uint32_t block_size = size_buf[0] | ((uint32_t)size_buf[1] << 8) | ((uint32_t)size_buf[2] << 16);

        if (block_type == 1) {
            /* Sound data */
            uint8_t info[2];
            if (fread(info, 1, 2, ft->fp) != 2) break;
            uint8_t freq_divisor = info[0];
            uint8_t codec = info[1];

            ft->signal.rate = 1000000.0 / (256 - freq_divisor);
            if (codec == 0) {
                ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
                ft->encoding.bits_per_sample = 8;
            }

            ft->data_start = ftell(ft->fp);
            ft->signal.length = (block_size - 2) / ft->signal.channels;
            break;
        } else if (block_type == 9) {
            /* Extended sound data */
            uint8_t info[12];
            if (fread(info, 1, 12, ft->fp) != 12) break;
            ft->signal.rate = read_le32(info);
            uint8_t codec = info[4];
            ft->signal.channels = info[5] + 1;
            if (codec == 4) {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = 16;
            } else {
                ft->encoding.encoding = SOX_ENCODING_UNSIGNED;
                ft->encoding.bits_per_sample = 8;
            }
            ft->signal.precision = ft->encoding.bits_per_sample;
            ft->data_start = ftell(ft->fp);
            unsigned bps = ft->encoding.bits_per_sample / 8;
            ft->signal.length = (block_size - 12) / bps / ft->signal.channels;
            break;
        } else {
            fseek(ft->fp, block_size, SEEK_CUR);
        }
    }

    fseek(ft->fp, 0, SEEK_END);
    ft->filesize = ftell(ft->fp);
    if (ft->data_start > 0) fseek(ft->fp, ft->data_start, SEEK_SET);
    return SOX_SUCCESS;
}

static size_t voc_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    return raw_read(ft, buf, len);
}

static int voc_stopread(sox_format_t *ft) { (void)ft; return SOX_SUCCESS; }

