static format_rec_t *find_format(const char *name) {
    if (!name) return NULL;
    for (int i = 0; g_formats[i].names[0] != NULL; i++) {
        for (int j = 0; g_formats[i].names[j] != NULL; j++) {
            if (strcasecmp(g_formats[i].names[j], name) == 0)
                return &g_formats[i];
        }
    }
    return NULL;
}

