/* Raw format variants */
static int raw_be_startread(sox_format_t *ft) {
    ft->encoding.reverse_bytes = 1;
    return raw_startread(ft);
}
static int raw_be_startwrite(sox_format_t *ft) {
    ft->encoding.reverse_bytes = 1;
    return raw_startwrite(ft);
}

/* Helper function to set up typed raw format */
static void setup_typed_raw(sox_format_t *ft, sox_encoding_t enc, unsigned bits, int big_endian) {
    if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN) {
        ft->encoding.encoding = enc;
        ft->encoding.bits_per_sample = bits;
    }
    if (big_endian) ft->encoding.reverse_bytes = 1;
}

