/* =====================================================================
 * DETECT FORMAT FROM FILENAME / CONTENT
 * ===================================================================== */

static const char *filename_to_type(const char *filename) {
    if (!filename) return NULL;
    const char *ext = strrchr(filename, '.');
    if (!ext) return NULL;
    ext++;  /* skip the dot */
    return ext;
}

static const char *detect_format_magic(FILE *fp) {
    uint8_t magic[12];
    long pos = ftell(fp);
    size_t n = fread(magic, 1, 12, fp);
    fseek(fp, pos, SEEK_SET);
    if (n < 4) return NULL;

    if (memcmp(magic, "RIFF", 4) == 0 && n >= 12 && memcmp(magic+8, "WAVE", 4) == 0)
        return "wav";
    if (memcmp(magic, "RIFX", 4) == 0 && n >= 12 && memcmp(magic+8, "WAVE", 4) == 0)
        return "wav";
    if (memcmp(magic, "FORM", 4) == 0 && n >= 12) {
        if (memcmp(magic+8, "AIFF", 4) == 0) return "aiff";
        if (memcmp(magic+8, "AIFC", 4) == 0) return "aifc";
    }
    if (memcmp(magic, ".snd", 4) == 0) return "au";
    if (magic[0] == 0 && magic[1] == 0 && magic[2] == 0x73 && magic[3] == 0x4e) {
        /* Maybe AU big-endian */
        uint32_t m = read_be32(magic);
        if (m == 0x2e736e64) return "au";
    }
    if (memcmp(magic, "Sox!", 4) == 0) return "sox";
    if (memcmp(magic, "Creative Voice File", 19) == 0) return "voc";

    return NULL;
}

static sox_format_t *open_format(const char *filename, const char *type,
                                  const sox_signalinfo_t *signal,
                                  const sox_encodinginfo_t *encoding,
                                  const sox_oob_t *oob, int mode) {
    if (!filename) return NULL;

    /* Determine format */
    const char *fmt_name = type;
    format_rec_t *fmt = NULL;

    if (fmt_name) {
        fmt = find_format(fmt_name);
        if (!fmt) {
            lsx_fail("formats: no handler for format `%s'", fmt_name);
            return NULL;
        }
    }

    /* Open the file */
    FILE *fp = NULL;
    int is_stdin_stdout = 0;

    if (strcmp(filename, "-") == 0) {
        fp = (mode == 'r') ? stdin : stdout;
        is_stdin_stdout = 1;
    } else if (filename[0] == '|') {
        /* Pipe */
        fp = popen(filename + 1, (mode == 'r') ? "r" : "w");
        if (!fp) {
            lsx_fail("formats: can't open pipe `%s': %s", filename, strerror(errno));
            return NULL;
        }
    } else {
        fp = fopen(filename, (mode == 'r') ? "rb" : "wb");
        if (!fp) {
            lsx_fail("formats: can't open %s file `%s': %s",
                     mode == 'r' ? "input" : "output",
                     filename, strerror(errno));
            return NULL;
        }
    }

    /* Detect format if not specified */
    if (!fmt && mode == 'r' && !is_stdin_stdout) {
        /* Try magic */
        const char *magic_type = detect_format_magic(fp);
        if (magic_type) {
            fmt = find_format(magic_type);
        }
        if (!fmt) {
            /* Try extension */
            const char *ext = filename_to_type(filename);
            if (ext) fmt = find_format(ext);
        }
        if (!fmt) {
            lsx_fail("formats: no handler found for format of `%s'", filename);
            fclose(fp);
            return NULL;
        }
    } else if (!fmt && mode == 'w' && !is_stdin_stdout) {
        const char *ext = filename_to_type(filename);
        if (ext) fmt = find_format(ext);
        if (!fmt) {
            lsx_fail("formats: no handler found for format of `%s'", filename);
            fclose(fp);
            return NULL;
        }
    }

    if (!fmt) {
        lsx_fail("formats: no format handler");
        if (!is_stdin_stdout) fclose(fp);
        return NULL;
    }

    /* Allocate format structure */
    sox_format_t *ft = (sox_format_t *)calloc(1, sizeof(sox_format_t));
    if (!ft) {
        if (!is_stdin_stdout) fclose(fp);
        return NULL;
    }

    ft->filename = strdup(filename);
    ft->fp = fp;
    ft->mode = mode;
    ft->filetype = strdup(fmt->names[0]);

    /* Apply signal info if provided */
    if (signal) {
        if (signal->rate != 0) ft->signal.rate = signal->rate;
        if (signal->channels != 0) ft->signal.channels = signal->channels;
        if (signal->precision != 0) ft->signal.precision = signal->precision;
    }

    /* Apply encoding info if provided */
    if (encoding) {
        if (encoding->encoding != SOX_ENCODING_UNKNOWN)
            ft->encoding.encoding = encoding->encoding;
        if (encoding->bits_per_sample != 0)
            ft->encoding.bits_per_sample = encoding->bits_per_sample;
        if (encoding->reverse_bytes) ft->encoding.reverse_bytes = 1;
        if (encoding->opposite_endian) ft->encoding.opposite_endian = 1;
    }

    /* Set OOB comment for writes */
    if (oob && oob->comment) {
        ft->oob.comment = strdup(oob->comment);
    }

    /* Allocate private data */
    if (fmt->priv_size > 0) {
        ft->priv = calloc(1, fmt->priv_size);
        if (!ft->priv) {
            free(ft->filename); free(ft->filetype); free(ft);
            if (!is_stdin_stdout) fclose(fp);
            return NULL;
        }
    }

