    int ret;
    if (mode == 'r') {
        ret = fmt->startread ? fmt->startread(ft) : SOX_SUCCESS;
    } else {
        /* For writes, set up encoding from output format options */
        if (ft->encoding.encoding == SOX_ENCODING_UNKNOWN) {
            /* Default encoding for each format */
            if (strcmp(fmt->names[0], "wav") == 0) {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = 16;
            } else if (strcmp(fmt->names[0], "au") == 0 ||
                       strcmp(fmt->names[0], "snd") == 0) {
                ft->encoding.encoding = SOX_ENCODING_ULAW;
                ft->encoding.bits_per_sample = 8;
            } else if (strcmp(fmt->names[0], "aiff") == 0 ||
                       strcmp(fmt->names[0], "aif") == 0) {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = 16;
            } else {
                ft->encoding.encoding = SOX_ENCODING_SIGN2;
                ft->encoding.bits_per_sample = 16;
            }
        }
        ret = fmt->startwrite ? fmt->startwrite(ft) : SOX_SUCCESS;
    }

    if (ret != SOX_SUCCESS) {
        if (ft->priv) free(ft->priv);
        free(ft->filename); free(ft->filetype);
        if (ft->oob.comment) free(ft->oob.comment);
        free(ft);
        if (!is_stdin_stdout) fclose(fp);
        return NULL;
    }

    /* Associate handler with format */
    ft->priv = ft->priv;  /* already set */
