    return ft;
}

static format_rec_t *get_format_for_ft(sox_format_t *ft) {
    if (!ft->filetype) return NULL;
    return find_format(ft->filetype);
}

static sox_format_t *sox_open_read(const char *path, 
                                    const sox_signalinfo_t *signal,
                                    const sox_encodinginfo_t *encoding,
                                    const char *type) {
    return open_format(path, type, signal, encoding, NULL, 'r');
}

static sox_format_t *sox_open_write(const char *path,
                                     const sox_signalinfo_t *signal,
                                     const sox_encodinginfo_t *encoding,
                                     const char *type,
                                     const sox_oob_t *oob) {
    return open_format(path, type, signal, encoding, oob, 'w');
}

static int sox_close(sox_format_t *ft) {
    if (!ft) return SOX_EOF;

    format_rec_t *fmt = find_format(ft->filetype ? ft->filetype : "");

    if (ft->mode == 'w' && fmt && fmt->stopwrite) {
        fmt->stopwrite(ft);
    } else if (ft->mode == 'r' && fmt && fmt->stopread) {
        fmt->stopread(ft);
    }

    if (ft->fp && ft->fp != stdin && ft->fp != stdout) {
        fclose(ft->fp);
    }

    if (ft->priv) free(ft->priv);
    if (ft->filename) free(ft->filename);
    if (ft->filetype) free(ft->filetype);
    if (ft->oob.comment) free(ft->oob.comment);
    free(ft);
    return SOX_SUCCESS;
}

static size_t sox_read(sox_format_t *ft, sox_sample_t *buf, size_t len) {
    format_rec_t *fmt = find_format(ft->filetype ? ft->filetype : "");
    if (!fmt || !fmt->read) return 0;
    return fmt->read(ft, buf, len);
}

static size_t sox_write(sox_format_t *ft, const sox_sample_t *buf, size_t len) {
    format_rec_t *fmt = find_format(ft->filetype ? ft->filetype : "");
    if (!fmt || !fmt->write) return 0;
    return fmt->write(ft, buf, len);
}

