static int norm_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    norm_priv_t *p = (norm_priv_t *)eff->priv;
    p->level = -1.0;  /* default: 0 dBFS */
    if (argc > 0) p->level = strtod(argv[0], NULL);
    return SOX_SUCCESS;
}

static int norm_start(sox_effect_t *eff) {
    norm_priv_t *p = (norm_priv_t *)eff->priv;
    p->peak = 0;
    p->samples = 0;
    p->buf = NULL;
    p->buf_size = 0;
    p->buf_used = 0;
    return SOX_SUCCESS;
}

static int norm_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    norm_priv_t *p = (norm_priv_t *)eff->priv;
    size_t len = *isamp;
    size_t i;

    /* Buffer all samples */
    if (p->buf_used + len > p->buf_size) {
        p->buf_size = (p->buf_used + len) * 2;
        p->buf = realloc(p->buf, p->buf_size * sizeof(sox_sample_t));
    }
    memcpy(p->buf + p->buf_used, ibuf, len * sizeof(sox_sample_t));
    p->buf_used += len;

    /* Find peak */
    for (i = 0; i < len; i++) {
        double s = fabs((double)ibuf[i]);
        if (s > p->peak) p->peak = s;
    }
    p->samples += len;

    *isamp = len;
    *osamp = 0;  /* no output yet */
    return SOX_SUCCESS;
}

static int norm_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    norm_priv_t *p = (norm_priv_t *)eff->priv;

    if (p->buf_used == 0) { *osamp = 0; return SOX_EOF; }

    /* Calculate gain */
    double target = pow(10.0, p->level / 20.0) * (double)SOX_SAMPLE_MAX;
    double gain = (p->peak > 0) ? (target / p->peak) : 1.0;

    size_t to_output = p->buf_used < *osamp ? p->buf_used : *osamp;
    size_t i;
    for (i = 0; i < to_output; i++) {
        double s = (double)p->buf[i] * gain;
        if (s > SOX_SAMPLE_MAX) { s = SOX_SAMPLE_MAX; eff->clips++; }
        else if (s < SOX_SAMPLE_MIN) { s = SOX_SAMPLE_MIN; eff->clips++; }
        obuf[i] = (sox_sample_t)s;
    }

    /* Shift remaining data */
    p->buf_used -= to_output;
    if (p->buf_used > 0)
        memmove(p->buf, p->buf + to_output, p->buf_used * sizeof(sox_sample_t));

    *osamp = to_output;
    return (p->buf_used == 0) ? SOX_EOF : SOX_SUCCESS;
}

