} trim_priv_t;

static int trim_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    trim_priv_t *p = (trim_priv_t *)eff->priv;
    p->start = 0;
    p->end = -1;

    if (argc >= 1) p->start = parse_time(argv[0]);
    if (argc >= 2) p->end = parse_time(argv[1]);
    return SOX_SUCCESS;
}

static int trim_start(sox_effect_t *eff) {
    trim_priv_t *p = (trim_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    unsigned chans = eff->in_signal.channels;

    p->start_samples = (uint64_t)(p->start * rate) * chans;
    if (p->end >= 0) {
        p->end_samples = (uint64_t)(p->end * rate) * chans;
    } else {
        p->end_samples = UINT64_MAX;
    }
    p->samples_read = 0;
    p->started = 0;

    /* Update output length */
    if (p->end >= 0) {
        double out_dur = p->end - p->start;
        if (out_dur < 0) out_dur = 0;
        eff->out_signal.length = (uint64_t)(out_dur * rate);
    }

    return SOX_SUCCESS;
}

static int trim_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    trim_priv_t *p = (trim_priv_t *)eff->priv;
    size_t in_len = *isamp;
    size_t out_idx = 0;
    size_t i;

    for (i = 0; i < in_len && out_idx < *osamp; i++) {
        uint64_t sample_idx = p->samples_read + i;

        if (sample_idx < p->start_samples) continue;
        if (sample_idx >= p->end_samples) {
            *isamp = i + 1;
            *osamp = out_idx;
            return SOX_EOF;
        }
        obuf[out_idx++] = ibuf[i];
    }

    p->samples_read += in_len;
    *isamp = in_len;
    *osamp = out_idx;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: pad
 * ===================================================================== */

typedef struct {
    double start_pad;   /* seconds of padding at start */
    double end_pad;     /* seconds of padding at end */
    uint64_t start_samples;
    uint64_t end_samples;
    uint64_t samples_out;
    int in_eof;
} pad_priv_t;

static int pad_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    pad_priv_t *p = (pad_priv_t *)eff->priv;
    p->start_pad = 0;
    p->end_pad = 0;

    if (argc >= 1) p->start_pad = parse_time(argv[0]);
    if (argc >= 2) p->end_pad = parse_time(argv[1]);
    return SOX_SUCCESS;
}

static int pad_start(sox_effect_t *eff) {
    pad_priv_t *p = (pad_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    unsigned chans = eff->in_signal.channels;
    p->start_samples = (uint64_t)(p->start_pad * rate) * chans;
    p->end_samples = (uint64_t)(p->end_pad * rate) * chans;
    p->samples_out = 0;
    p->in_eof = 0;
    return SOX_SUCCESS;
}

static int pad_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                    size_t *isamp, size_t *osamp) {
    pad_priv_t *p = (pad_priv_t *)eff->priv;
    size_t out_idx = 0;
    size_t in_idx = 0;

    /* Output start padding */
    while (p->samples_out < p->start_samples && out_idx < *osamp) {
        obuf[out_idx++] = 0;
        p->samples_out++;
    }

    /* Copy input */
    while (in_idx < *isamp && out_idx < *osamp) {
        obuf[out_idx++] = ibuf[in_idx++];
        p->samples_out++;
    }

    *isamp = in_idx;
    *osamp = out_idx;
    return SOX_SUCCESS;
}

static int pad_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    pad_priv_t *p = (pad_priv_t *)eff->priv;
    size_t out_idx = 0;

    while (out_idx < *osamp && p->end_samples > 0) {
        obuf[out_idx++] = 0;
        p->end_samples--;
    }

    *osamp = out_idx;
    return (p->end_samples == 0) ? SOX_EOF : SOX_SUCCESS;
}

