/* =====================================================================
 * EFFECT: channels (channel conversion)
 * ===================================================================== */

typedef struct {
    unsigned out_channels;
} channels_priv_t;

static int channels_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("channels: missing argument"); return SOX_EOF; }
    p->out_channels = (unsigned)atoi(argv[0]);
    eff->out_signal.channels = p->out_channels;
    return SOX_SUCCESS;
}

static int channels_start(sox_effect_t *eff) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    eff->out_signal.channels = p->out_channels;
    return SOX_SUCCESS;
}

static int channels_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    unsigned in_ch = eff->in_signal.channels;
    unsigned out_ch = p->out_channels;

    if (in_ch == 0) in_ch = 1;
    if (out_ch == 0) out_ch = 1;

    size_t in_frames = *isamp / in_ch;
    size_t out_frames = *osamp / out_ch;
    size_t frames = in_frames < out_frames ? in_frames : out_frames;
    size_t f;

    for (f = 0; f < frames; f++) {
        if (out_ch == 1) {
            /* Mix all inputs to mono */
            double sum = 0;
            unsigned ch;
            for (ch = 0; ch < in_ch; ch++)
                sum += (double)ibuf[f * in_ch + ch];
            obuf[f] = (sox_sample_t)(sum / in_ch);
        } else if (in_ch == 1) {
            /* Duplicate mono to all channels */
            unsigned ch;
            for (ch = 0; ch < out_ch; ch++)
                obuf[f * out_ch + ch] = ibuf[f];
        } else if (in_ch == out_ch) {
            memcpy(obuf + f * out_ch, ibuf + f * in_ch, in_ch * sizeof(sox_sample_t));
        } else {
            /* Remix: copy available channels, zero rest */
            unsigned ch;
            for (ch = 0; ch < out_ch; ch++) {
                if (ch < in_ch)
                    obuf[f * out_ch + ch] = ibuf[f * in_ch + ch];
                else
                    obuf[f * out_ch + ch] = 0;
            }
        }
    }

    *isamp = frames * in_ch;
    *osamp = frames * out_ch;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: rate (sample rate conversion)
 * ===================================================================== */

typedef struct {
    double out_rate;
    double ratio;
    /* Polyphase filter state */
    double *history;
    size_t hist_len;
    double phase;
    double step;
    /* Input buffer */
    sox_sample_t *ibuf;
    size_t ibuf_size;
    size_t ibuf_len;
    size_t ibuf_pos;
} rate_priv_t;

static int rate_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("rate: missing argument"); return SOX_EOF; }

    /* Skip quality flags */
    int i;
    p->out_rate = 0;
    for (i = 0; i < argc; i++) {
        if (argv[i][0] == '-') continue;  /* skip flags */
        char *end;
        p->out_rate = strtod(argv[i], &end);
        if (*end == 'k' || *end == 'K') p->out_rate *= 1000;
        break;
    }

    if (p->out_rate <= 0) { lsx_fail("rate: invalid rate"); return SOX_EOF; }
    eff->out_signal.rate = p->out_rate;
    return SOX_SUCCESS;
}

/* Simple linear interpolation resampler */
static int rate_start(sox_effect_t *eff) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    p->ratio = p->out_rate / eff->in_signal.rate;
    p->phase = 0.0;
    p->ibuf = NULL;
    p->ibuf_size = 0;
    p->ibuf_len = 0;
    p->ibuf_pos = 0;
    eff->out_signal.rate = p->out_rate;
    return SOX_SUCCESS;
}

static int rate_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;

    if (channels == 0) channels = 1;

    size_t in_frames = *isamp / channels;
    size_t out_frames_max = *osamp / channels;
    size_t out_frames = 0;

    /* Extend input buffer */
    size_t total_frames = p->ibuf_len / channels + in_frames;
    if (p->ibuf_size < (total_frames + 2) * channels) {
        p->ibuf_size = (total_frames + 2) * channels;
        p->ibuf = realloc(p->ibuf, p->ibuf_size * sizeof(sox_sample_t));
    }

    /* Append new input to buffer */
    memcpy(p->ibuf + p->ibuf_len, ibuf, in_frames * channels * sizeof(sox_sample_t));
    p->ibuf_len += in_frames * channels;

    size_t ibuf_frames = p->ibuf_len / channels;

    /* Linear interpolation */
    while (out_frames < out_frames_max) {
        size_t idx = (size_t)p->phase;
        if (idx + 1 >= ibuf_frames) break;

        double frac = p->phase - idx;
        unsigned ch;
        for (ch = 0; ch < channels; ch++) {
            double a = (double)p->ibuf[idx * channels + ch];
            double b = (double)p->ibuf[(idx+1) * channels + ch];
            double s = a + frac * (b - a);
            obuf[out_frames * channels + ch] = (sox_sample_t)s;
        }
        out_frames++;
        p->phase += 1.0 / p->ratio;
    }

    /* Update input buffer - remove consumed frames */
    size_t consumed_frames = (size_t)p->phase;
    if (consumed_frames > 0) {
        size_t remaining_frames = ibuf_frames - consumed_frames;
        if (remaining_frames > 0) {
            memmove(p->ibuf, p->ibuf + consumed_frames * channels,
                    remaining_frames * channels * sizeof(sox_sample_t));
        }
        p->ibuf_len = remaining_frames * channels;
        p->phase -= (double)consumed_frames;
    }

    *isamp = in_frames * channels;
    *osamp = out_frames * channels;
    return SOX_SUCCESS;
}

static int rate_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    size_t out_frames_max = *osamp / channels;
    size_t out_frames = 0;
    size_t ibuf_frames = p->ibuf_len / channels;

    while (out_frames < out_frames_max) {
        size_t idx = (size_t)p->phase;
        if (idx >= ibuf_frames) break;

        double frac = p->phase - idx;
        unsigned ch;
        for (ch = 0; ch < channels; ch++) {
            double a = (double)p->ibuf[idx * channels + ch];
            double b = (idx + 1 < ibuf_frames) ?
                       (double)p->ibuf[(idx+1) * channels + ch] : a;
            double s = a + frac * (b - a);
            obuf[out_frames * channels + ch] = (sox_sample_t)s;
        }
        out_frames++;
        p->phase += 1.0 / p->ratio;
    }

    *osamp = out_frames * channels;
    if (out_frames == 0) return SOX_EOF;
    return SOX_SUCCESS;
}

static int rate_stop(sox_effect_t *eff) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    if (p->ibuf) free(p->ibuf);
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: stat (statistics)
 * ===================================================================== */

typedef struct {
    int rms_flag;
    int freq_flag;
    int verbose;
    int disp_flag;
    double scale;
    /* Statistics accumulators */
    double sum;
    double sum_sq;
    double peak_amp;
    double min_amp;
    double delta_max;
    double delta_min;
    double delta_sum;
    double delta_sum_sq;
    double prev_sample;
    int64_t n;
    /* Frequency estimation */
    int64_t zero_crossings;
    double prev_sign;
    double rough_freq;
    double min_amp_val;
    double max_amp_val;
} stat_priv_t;

static int stat_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    stat_priv_t *p = (stat_priv_t *)eff->priv;
    int i;
    p->scale = 1.0;

    for (i = 0; i < argc; i++) {
        if (strcmp(argv[i], "-rms") == 0) p->rms_flag = 1;
        else if (strcmp(argv[i], "-freq") == 0) p->freq_flag = 1;
        else if (strcmp(argv[i], "-v") == 0) p->verbose = 1;
        else if (strcmp(argv[i], "-d") == 0) p->disp_flag = 1;
        else if (strcmp(argv[i], "-s") == 0 && i+1 < argc) {
            p->scale = strtod(argv[++i], NULL);
        }
    }
    return SOX_SUCCESS;
}

static int stat_start(sox_effect_t *eff) {
    stat_priv_t *p = (stat_priv_t *)eff->priv;
    p->sum = 0;
    p->sum_sq = 0;
    p->peak_amp = 0;
    p->min_amp = 0;
    p->max_amp_val = 0;
    p->min_amp_val = 0;
    p->delta_max = 0;
    p->delta_min = 0;
    p->delta_sum = 0;
    p->delta_sum_sq = 0;
    p->prev_sample = 0;
    p->n = 0;
    p->zero_crossings = 0;
    p->prev_sign = 0;
    return SOX_SUCCESS;
}

static int stat_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    stat_priv_t *p = (stat_priv_t *)eff->priv;
    size_t len = *isamp;
    size_t i;

    /* Pass through */
    memcpy(obuf, ibuf, len * sizeof(sox_sample_t));
    *osamp = len;

    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] / 2147483648.0;  /* normalize to [-1, 1) */

        p->sum += s;
        p->sum_sq += s * s;

        double abs_s = fabs(s);
        if (abs_s > p->peak_amp) p->peak_amp = abs_s;
        if (abs_s < p->min_amp || p->n == 0) p->min_amp = abs_s;
        if (p->n == 0 || s > p->max_amp_val) p->max_amp_val = s;
        if (p->n == 0 || s < p->min_amp_val) p->min_amp_val = s;

        if (p->n > 0) {
            double delta = s - p->prev_sample;
            double abs_delta = fabs(delta);
            if (abs_delta > p->delta_max) p->delta_max = abs_delta;
            if (p->n == 1 || abs_delta < p->delta_min) p->delta_min = abs_delta;
            p->delta_sum += delta;
            p->delta_sum_sq += delta * delta;
        }

        /* Zero crossing detection */
        double sign = (s >= 0) ? 1.0 : -1.0;
        if (p->n > 0 && sign != p->prev_sign && p->prev_sign != 0) {
            p->zero_crossings++;
        }
        p->prev_sign = sign;
        p->prev_sample = s;
        p->n++;
    }

    return SOX_SUCCESS;
}

static int stat_stop(sox_effect_t *eff) {
    stat_priv_t *p = (stat_priv_t *)eff->priv;
    double n = (double)p->n;
    double rate = eff->in_signal.rate;

    if (p->rms_flag) {
        double rms = (n > 0) ? sqrt(p->sum_sq / n) : 0;
        double scaled_rms = (n > 0) ? (rms * p->scale) : 0;

        fprintf(stderr, "Samples read:          %14" PRId64 "\n", (int64_t)p->n);
        fprintf(stderr, "Length (seconds):      %14.6f\n", 
                (rate > 0 && eff->in_signal.channels > 0) ? 
                n / rate / eff->in_signal.channels : 0.0);
        fprintf(stderr, "Scaled by rms:         %14.1f\n", scaled_rms > 0 ? 1.0 / scaled_rms : 0.0/0.0);
        fprintf(stderr, "Maximum amplitude:     %14.6f\n", p->n > 0 ? p->max_amp_val : 0.0/0.0);
        fprintf(stderr, "Minimum amplitude:     %14.6f\n", p->n > 0 ? p->min_amp_val : 0.0/0.0);
        fprintf(stderr, "Midline amplitude:     %14.6f\n", p->n > 0 ? (p->max_amp_val + p->min_amp_val) / 2.0 : 0.0/0.0);
        fprintf(stderr, "Mean    norm:          %14.6f\n", p->n > 0 ? fabs(p->sum / n) : 0.0/0.0);
        fprintf(stderr, "Mean    amplitude:     %14.6f\n", p->n > 0 ? p->sum / n : 0.0/0.0);
        fprintf(stderr, "RMS     amplitude:     %14.6f\n", p->n > 0 ? rms : 0.0/0.0);
        double d_rms = (p->n > 1) ? sqrt(p->delta_sum_sq / (n-1)) : 0.0/0.0;
        fprintf(stderr, "Maximum delta:         %14.6f\n", p->n > 1 ? p->delta_max : 0.0/0.0);
        fprintf(stderr, "Minimum delta:         %14.6f\n", p->n > 1 ? p->delta_min : 0.0/0.0);
        fprintf(stderr, "Mean    delta:         %14.6f\n", p->n > 1 ? p->delta_sum / (n-1) : 0.0/0.0);
        fprintf(stderr, "RMS     delta:         %14.6f\n", p->n > 1 ? d_rms : 0.0/0.0);
        fprintf(stderr, "Rough   frequency:  %12" PRId64 "\n", 
                (p->n > 1 && rate > 0) ? (int64_t)(p->zero_crossings * rate / 2 / (eff->in_signal.channels > 0 ? eff->in_signal.channels : 1) / n * eff->in_signal.channels) : (int64_t)-2147483648);
    } else {
        double rms = (n > 0) ? sqrt(p->sum_sq / n) : 0;
        double peak_db = (p->peak_amp > 0) ? 20.0 * log10(p->peak_amp) : -200.0;
        double vol_adj = (p->peak_amp > 0) ? 1.0 / p->peak_amp : 1.0;
        double scaled = p->scale;

        fprintf(stderr, "Samples read:          %14" PRId64 "\n", (int64_t)p->n);
        fprintf(stderr, "Length (seconds):      %14.6f\n",
                (rate > 0 && eff->in_signal.channels > 0) ?
                n / rate / eff->in_signal.channels : 0.0);
        fprintf(stderr, "Scaled by:         %18.1f\n", (double)SOX_SAMPLE_MAX);
        fprintf(stderr, "Maximum amplitude:     %14.6f\n", p->max_amp_val);
        fprintf(stderr, "Minimum amplitude:     %14.6f\n", p->min_amp_val);
        fprintf(stderr, "Midline amplitude:     %14.6f\n", (p->max_amp_val + p->min_amp_val) / 2.0);
        fprintf(stderr, "Mean    norm:          %14.6f\n", (n > 0) ? fabs(p->sum / n) : 0.0/0.0);
        fprintf(stderr, "Mean    amplitude:     %14.6f\n", (n > 0) ? p->sum / n : 0.0/0.0);
        fprintf(stderr, "RMS     amplitude:     %14.6f\n", rms);

        double d_mean = (p->n > 1) ? p->delta_sum / (n - 1) : 0;
        double d_rms = (p->n > 1) ? sqrt(p->delta_sum_sq / (n - 1)) : 0;

        fprintf(stderr, "Maximum delta:         %14.6f\n", p->delta_max);
        fprintf(stderr, "Minimum delta:         %14.6f\n", p->delta_min);
        fprintf(stderr, "Mean    delta:         %14.6f\n", d_mean);
        fprintf(stderr, "RMS     delta:         %14.6f\n", d_rms);

        /* Rough frequency - zero crossings / 2 / duration */
        int64_t rough_freq = -2147483648LL;
        if (p->n > 1 && rate > 0) {
            double duration = n / rate / (eff->in_signal.channels > 0 ? eff->in_signal.channels : 1);
            rough_freq = (int64_t)(p->zero_crossings / 2.0 / duration);
        }
        fprintf(stderr, "Rough   frequency:  %12" PRId64 "\n", rough_freq);

        fprintf(stderr, "Volume adjustment:        %6.3f\n", vol_adj);
        fprintf(stderr, "\n");

        /* Suggest best encoding */
        if (rms < 0.01) {
            fprintf(stderr, "Probably text, not sound\n");
        } else {
            /* Suggest encoding based on peak */
            if (p->peak_amp < 0.5) {
                fprintf(stderr, "Try: -t raw -e mu-law -b 8 \n");
            } else {
                fprintf(stderr, "Try: -t raw -e mu-law -b 8 \n");
            }
        }
    }

    return SOX_SUCCESS;
}

