/* =====================================================================
 * EFFECT: channels (channel conversion)
 * ===================================================================== */

typedef struct {
    unsigned out_channels;
} channels_priv_t;

static int channels_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("channels: missing argument"); return SOX_EOF; }
    p->out_channels = (unsigned)atoi(argv[0]);
    eff->out_signal.channels = p->out_channels;
    return SOX_SUCCESS;
}

static int channels_start(sox_effect_t *eff) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    eff->out_signal.channels = p->out_channels;
    return SOX_SUCCESS;
}

static int channels_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    channels_priv_t *p = (channels_priv_t *)eff->priv;
    unsigned in_ch = eff->in_signal.channels;
    unsigned out_ch = p->out_channels;

    if (in_ch == 0) in_ch = 1;
    if (out_ch == 0) out_ch = 1;

    size_t in_frames = *isamp / in_ch;
    size_t out_frames = *osamp / out_ch;
    size_t frames = in_frames < out_frames ? in_frames : out_frames;
    size_t f;

    for (f = 0; f < frames; f++) {
        if (out_ch == 1) {
            /* Mix all inputs to mono */
            double sum = 0;
            unsigned ch;
            for (ch = 0; ch < in_ch; ch++)
                sum += (double)ibuf[f * in_ch + ch];
            obuf[f] = (sox_sample_t)(sum / in_ch);
        } else if (in_ch == 1) {
            /* Duplicate mono to all channels */
            unsigned ch;
            for (ch = 0; ch < out_ch; ch++)
                obuf[f * out_ch + ch] = ibuf[f];
        } else if (in_ch == out_ch) {
            memcpy(obuf + f * out_ch, ibuf + f * in_ch, in_ch * sizeof(sox_sample_t));
        } else {
            /* Remix: copy available channels, zero rest */
            unsigned ch;
            for (ch = 0; ch < out_ch; ch++) {
                if (ch < in_ch)
                    obuf[f * out_ch + ch] = ibuf[f * in_ch + ch];
                else
                    obuf[f * out_ch + ch] = 0;
            }
        }
    }

    *isamp = frames * in_ch;
    *osamp = frames * out_ch;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: rate (sample rate conversion)
 * ===================================================================== */

typedef struct {
    double out_rate;
    double ratio;
    /* Polyphase filter state */
    double *history;
    size_t hist_len;
    double phase;
    double step;
    /* Input buffer */
    sox_sample_t *ibuf;
    size_t ibuf_size;
    size_t ibuf_len;
    size_t ibuf_pos;
} rate_priv_t;

static int rate_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("rate: missing argument"); return SOX_EOF; }

    /* Skip quality flags */
    int i;
    p->out_rate = 0;
    for (i = 0; i < argc; i++) {
        if (argv[i][0] == '-') continue;  /* skip flags */
        char *end;
        p->out_rate = strtod(argv[i], &end);
        if (*end == 'k' || *end == 'K') p->out_rate *= 1000;
        break;
    }

    if (p->out_rate <= 0) { lsx_fail("rate: invalid rate"); return SOX_EOF; }
    eff->out_signal.rate = p->out_rate;
    return SOX_SUCCESS;
}

/* Simple linear interpolation resampler */
static int rate_start(sox_effect_t *eff) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    p->ratio = p->out_rate / eff->in_signal.rate;
    p->phase = 0.0;
    p->ibuf = NULL;
    p->ibuf_size = 0;
    p->ibuf_len = 0;
    p->ibuf_pos = 0;
    eff->out_signal.rate = p->out_rate;
    return SOX_SUCCESS;
}

static int rate_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;

    if (channels == 0) channels = 1;

    size_t in_frames = *isamp / channels;
    size_t out_frames_max = *osamp / channels;
    size_t out_frames = 0;

    /* Extend input buffer */
    size_t total_frames = p->ibuf_len / channels + in_frames;
    if (p->ibuf_size < (total_frames + 2) * channels) {
        p->ibuf_size = (total_frames + 2) * channels;
        p->ibuf = realloc(p->ibuf, p->ibuf_size * sizeof(sox_sample_t));
    }

    /* Append new input to buffer */
    memcpy(p->ibuf + p->ibuf_len, ibuf, in_frames * channels * sizeof(sox_sample_t));
    p->ibuf_len += in_frames * channels;

    size_t ibuf_frames = p->ibuf_len / channels;

    /* Linear interpolation */
    while (out_frames < out_frames_max) {
        size_t idx = (size_t)p->phase;
        if (idx + 1 >= ibuf_frames) break;

        double frac = p->phase - idx;
        unsigned ch;
        for (ch = 0; ch < channels; ch++) {
            double a = (double)p->ibuf[idx * channels + ch];
            double b = (double)p->ibuf[(idx+1) * channels + ch];
            double s = a + frac * (b - a);
            obuf[out_frames * channels + ch] = (sox_sample_t)s;
        }
        out_frames++;
        p->phase += 1.0 / p->ratio;
    }

    /* Update input buffer - remove consumed frames */
    size_t consumed_frames = (size_t)p->phase;
    if (consumed_frames > 0) {
        size_t remaining_frames = ibuf_frames - consumed_frames;
        if (remaining_frames > 0) {
            memmove(p->ibuf, p->ibuf + consumed_frames * channels,
                    remaining_frames * channels * sizeof(sox_sample_t));
        }
        p->ibuf_len = remaining_frames * channels;
        p->phase -= (double)consumed_frames;
    }

    *isamp = in_frames * channels;
    *osamp = out_frames * channels;
    return SOX_SUCCESS;
}

static int rate_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    size_t out_frames_max = *osamp / channels;
    size_t out_frames = 0;
    size_t ibuf_frames = p->ibuf_len / channels;

    while (out_frames < out_frames_max) {
        size_t idx = (size_t)p->phase;
        if (idx >= ibuf_frames) break;

        double frac = p->phase - idx;
        unsigned ch;
        for (ch = 0; ch < channels; ch++) {
            double a = (double)p->ibuf[idx * channels + ch];
            double b = (idx + 1 < ibuf_frames) ?
                       (double)p->ibuf[(idx+1) * channels + ch] : a;
            double s = a + frac * (b - a);
            obuf[out_frames * channels + ch] = (sox_sample_t)s;
        }
        out_frames++;
        p->phase += 1.0 / p->ratio;
    }

    *osamp = out_frames * channels;
    if (out_frames == 0) return SOX_EOF;
    return SOX_SUCCESS;
}

static int rate_stop(sox_effect_t *eff) {
    rate_priv_t *p = (rate_priv_t *)eff->priv;
    if (p->ibuf) free(p->ibuf);
    return SOX_SUCCESS;
}

