/* =====================================================================
 * EFFECT: synth (signal synthesizer)
 * ===================================================================== */

typedef enum { SYNTH_SIN, SYNTH_SQU, SYNTH_SAW, SYNTH_TRI, SYNTH_WHI, SYNTH_PIN, SYNTH_BROWNI, SYNTH_TRAPEZ, SYNTH_EXP } synth_type_t;
typedef enum { SYNTH_MIX, SYNTH_ADD, SYNTH_AMPL, SYNTH_FM, SYNTH_PM } synth_combine_t;

typedef struct {
    synth_type_t type;
    synth_combine_t combine;
    double freq;
    double freq2;
    double offset;
    double phase;
    double p1, p2, p3;
} synth_channel_t;

typedef struct {
    double dur;
    double off;
    int null_input;  /* 1 if -n was used */
    unsigned n_channels;
    synth_channel_t ch[8];
    double cur_phase[8];
    double prev_sample[8];  /* for brownian noise */
    double white[8];
    uint64_t samples_done;
    unsigned random_state;
} synth_priv_t;

static double synth_rand(synth_priv_t *p) {
    p->random_state = p->random_state * 1103515245 + 12345;
    return (double)((p->random_state >> 16) & 0x7FFF) / 16384.0 - 1.0;
}

static int synth_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    synth_priv_t *p = (synth_priv_t *)eff->priv;
    int i = 0;

    p->dur = -1;
    p->off = 0;
    p->random_state = 1;

    /* Check for -n flag (used with null input) */
    if (i < argc && strcmp(argv[i], "-n") == 0) {
        p->null_input = 1;
        i++;
    }

    /* Check for -j KEY flag */
    if (i < argc && strcmp(argv[i], "-j") == 0) {
        i += 2;  /* skip -j and KEY */
    }

    /* Optional length */
    if (i < argc) {
        char *end;
        double v = strtod(argv[i], &end);
        if (end != argv[i] && *end != ':' && strchr("0123456789.", argv[i][0])) {
            p->dur = parse_time(argv[i]);
            i++;
        } else if (argv[i][0] != '-' && !isalpha(argv[i][0])) {
            /* Maybe a length */
            p->dur = parse_time(argv[i]);
            i++;
        } else if (strstr(argv[i], ":")) {
            p->dur = parse_time(argv[i]);
            i++;
        }
        (void)v;
    }

    /* Parse channel specifications */
    p->n_channels = 0;

    while (i < argc && p->n_channels < 8) {
        synth_channel_t *ch = &p->ch[p->n_channels];

        /* Type */
        ch->type = SYNTH_SIN;
        ch->combine = SYNTH_MIX;
        ch->freq = 440.0;
        ch->freq2 = 0;
        ch->offset = 0;
        ch->phase = 0;
        ch->p1 = 50.0;  /* default duty cycle */
        ch->p2 = 0;
        ch->p3 = 0;

        /* Parse type */
        if (strncasecmp(argv[i], "sin", 3) == 0) ch->type = SYNTH_SIN;
        else if (strncasecmp(argv[i], "squ", 3) == 0) ch->type = SYNTH_SQU;
        else if (strncasecmp(argv[i], "saw", 3) == 0) ch->type = SYNTH_SAW;
        else if (strncasecmp(argv[i], "tri", 3) == 0) ch->type = SYNTH_TRI;
        else if (strncasecmp(argv[i], "whi", 3) == 0 || 
                 strncasecmp(argv[i], "whitenoise", 10) == 0) ch->type = SYNTH_WHI;
        else if (strncasecmp(argv[i], "pin", 3) == 0 ||
                 strncasecmp(argv[i], "pinknoise", 9) == 0) ch->type = SYNTH_PIN;
        else if (strncasecmp(argv[i], "bro", 3) == 0 ||
                 strncasecmp(argv[i], "browni", 6) == 0) ch->type = SYNTH_BROWNI;
        else if (strncasecmp(argv[i], "exp", 3) == 0) ch->type = SYNTH_EXP;
        else if (strncasecmp(argv[i], "tra", 3) == 0) ch->type = SYNTH_TRAPEZ;
        else { ch->type = SYNTH_SIN; }  /* unknown, default to sine */
        i++;

        /* Check for combine type */
        if (i < argc) {
            if (strcasecmp(argv[i], "mix") == 0) { ch->combine = SYNTH_MIX; i++; }
            else if (strcasecmp(argv[i], "add") == 0) { ch->combine = SYNTH_ADD; i++; }
            else if (strcasecmp(argv[i], "ampl") == 0) { ch->combine = SYNTH_AMPL; i++; }
            else if (strcasecmp(argv[i], "fm") == 0) { ch->combine = SYNTH_FM; i++; }
            else if (strcasecmp(argv[i], "pm") == 0) { ch->combine = SYNTH_PM; i++; }
        }

        /* Parse frequency */
        if (i < argc) {
            char *s = argv[i];
            if (s[0] == '%') {
                /* MIDI note relative */
                int midi_rel = atoi(s+1);
                /* A4 = 69 = 440Hz */
                ch->freq = 440.0 * pow(2.0, (69 + midi_rel) / 12.0);
                i++;
            } else {
                char *end;
                double v = strtod(s, &end);
                if (end != s) {
                    if (*end == 'k' || *end == 'K') v *= 1000;
                    ch->freq = v;
                    i++;
                }
            }
        }

        p->cur_phase[p->n_channels] = 0;
        p->prev_sample[p->n_channels] = 0;
        p->n_channels++;
    }

    if (p->n_channels == 0) {
        /* Default: one sine wave at 440Hz */
        p->ch[0].type = SYNTH_SIN;
        p->ch[0].freq = 440.0;
        p->n_channels = 1;
    }

    return SOX_SUCCESS;
}

static int synth_start(sox_effect_t *eff) {
    synth_priv_t *p = (synth_priv_t *)eff->priv;
    p->samples_done = 0;

    /* Set output channels */
    if (p->n_channels > 1) {
        eff->out_signal.channels = p->n_channels;
    }

    /* Set output length */
    if (p->dur >= 0 && eff->out_signal.rate > 0) {
        eff->out_signal.length = (uint64_t)(p->dur * eff->out_signal.rate);
    }

    return SOX_SUCCESS;
}

static double gen_sample(synth_priv_t *p, int ch_idx, double rate) {
    synth_channel_t *ch = &p->ch[ch_idx];
    double phase = p->cur_phase[ch_idx];
    double s = 0;

    switch (ch->type) {
        case SYNTH_SIN:
            s = sin(2.0 * M_PI * phase);
            break;
        case SYNTH_SQU:
            s = (phase < 0.5) ? 1.0 : -1.0;
            break;
        case SYNTH_SAW:
            s = 2.0 * phase - 1.0;
            break;
        case SYNTH_TRI:
            s = (phase < 0.25) ? (4.0 * phase) :
                (phase < 0.75) ? (2.0 - 4.0 * phase) :
                (4.0 * phase - 4.0);
            break;
        case SYNTH_WHI:
            s = synth_rand(p);
            break;
        case SYNTH_PIN: {
            /* Simple pink noise approximation */
            double white = synth_rand(p);
            static double b[8] = {0};
            b[0] = 0.99886 * b[0] + white * 0.0555179;
            b[1] = 0.99332 * b[1] + white * 0.0750759;
            b[2] = 0.96900 * b[2] + white * 0.1538520;
            b[3] = 0.86650 * b[3] + white * 0.3104856;
            b[4] = 0.55000 * b[4] + white * 0.5329522;
            b[5] = -0.7616 * b[5] - white * 0.0168980;
            s = (b[0] + b[1] + b[2] + b[3] + b[4] + b[5] + b[6] + white * 0.5362) / 7.0;
            b[6] = white * 0.115926;
            break;
        }
        case SYNTH_BROWNI: {
            double white = synth_rand(p);
            p->prev_sample[ch_idx] = (p->prev_sample[ch_idx] + 0.02 * white) * 0.999;
            s = p->prev_sample[ch_idx];
            if (s > 1.0) s = 1.0;
            if (s < -1.0) s = -1.0;
            break;
        }
        default:
            s = sin(2.0 * M_PI * phase);
            break;
    }

    /* Advance phase */
    if (ch->type != SYNTH_WHI && ch->type != SYNTH_PIN && ch->type != SYNTH_BROWNI) {
        p->cur_phase[ch_idx] += ch->freq / rate;
        while (p->cur_phase[ch_idx] >= 1.0) p->cur_phase[ch_idx] -= 1.0;
    }

    return s;
}

static int synth_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                      size_t *isamp, size_t *osamp) {
    synth_priv_t *p = (synth_priv_t *)eff->priv;
    double rate = eff->out_signal.rate;
    unsigned out_chans = eff->out_signal.channels;

    if (out_chans == 0) out_chans = 1;
    if (rate == 0) rate = SOX_DEFAULT_RATE;

    size_t frames = *osamp / out_chans;
    if (p->dur >= 0) {
        uint64_t max_frames = (uint64_t)(p->dur * rate) - p->samples_done;
        if (frames > max_frames) frames = (size_t)max_frames;
    }

    size_t f;
    for (f = 0; f < frames; f++) {
        unsigned ch;
        for (ch = 0; ch < out_chans; ch++) {
            int synth_ch = (ch < p->n_channels) ? ch : (p->n_channels - 1);
            double s = gen_sample(p, synth_ch, rate);

            /* Apply combine with input */
            if (ibuf && *isamp > 0) {
                size_t in_idx = f * out_chans + ch;
                if (in_idx < *isamp) {
                    double in_s = (double)ibuf[in_idx] / 2147483648.0;
                    switch (p->ch[synth_ch].combine) {
                        case SYNTH_MIX: s = (s + in_s) / 2.0; break;
                        case SYNTH_ADD: s = s + in_s; break;
                        case SYNTH_AMPL: s = s * in_s; break;
                        default: break;
                    }
                }
            }

            if (s > 1.0) s = 1.0;
            if (s < -1.0) s = -1.0;
            obuf[f * out_chans + ch] = (sox_sample_t)(s * 2147483647.0);
        }
    }

    p->samples_done += frames;

    *isamp = 0;
    *osamp = frames * out_chans;

    if (p->dur >= 0 && p->samples_done >= (uint64_t)(p->dur * rate)) {
        return SOX_EOF;
    }

    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: remix (mix channels)
 * ===================================================================== */

typedef struct {
    unsigned out_chans;
    int in_chan[32][32];  /* in_chan[out][in] - which input channels to mix */
    int n_in[32];         /* number of inputs for each output channel */
    double gain[32][32];  /* gain for each input channel */
} remix_priv_t;

static int remix_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    remix_priv_t *p = (remix_priv_t *)eff->priv;
    int i;

    p->out_chans = 0;

    /* Parse channel specifications */
    for (i = 0; i < argc && p->out_chans < 32; i++) {
        int out_ch = p->out_chans++;
        p->n_in[out_ch] = 0;

        if (strcmp(argv[i], "0") == 0) {
            /* Silence */
            continue;
        }

        /* Parse comma-separated list of input channels */
        char *s = argv[i];
        char *end;
        while (*s) {
            int in_ch = (int)strtol(s, &end, 10);
            if (end == s) break;
            if (in_ch >= 1 && p->n_in[out_ch] < 32) {
                p->in_chan[out_ch][p->n_in[out_ch]] = in_ch - 1;  /* 0-based */
                p->gain[out_ch][p->n_in[out_ch]] = 1.0;
                p->n_in[out_ch]++;
            }
            s = end;
            if (*s == ',') s++;
        }
    }

    eff->out_signal.channels = p->out_chans;
    return SOX_SUCCESS;
}

static int remix_start(sox_effect_t *eff) {
    remix_priv_t *p = (remix_priv_t *)eff->priv;
    eff->out_signal.channels = p->out_chans;
    return SOX_SUCCESS;
}

static int remix_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                      size_t *isamp, size_t *osamp) {
    remix_priv_t *p = (remix_priv_t *)eff->priv;
    unsigned in_ch = eff->in_signal.channels;
    unsigned out_ch = p->out_chans;

    if (in_ch == 0) in_ch = 1;
    if (out_ch == 0) out_ch = 1;

    size_t in_frames = *isamp / in_ch;
    size_t out_frames = *osamp / out_ch;
    size_t frames = in_frames < out_frames ? in_frames : out_frames;
    size_t f;
    unsigned och;

    for (f = 0; f < frames; f++) {
        for (och = 0; och < out_ch; och++) {
            if (p->n_in[och] == 0) {
                obuf[f * out_ch + och] = 0;
            } else {
                double sum = 0;
                int j;
                for (j = 0; j < p->n_in[och]; j++) {
                    int ich = p->in_chan[och][j];
                    if ((unsigned)ich < in_ch)
                        sum += (double)ibuf[f * in_ch + ich] * p->gain[och][j];
                }
                sum /= p->n_in[och];
                if (sum > SOX_SAMPLE_MAX) sum = SOX_SAMPLE_MAX;
                if (sum < SOX_SAMPLE_MIN) sum = SOX_SAMPLE_MIN;
                obuf[f * out_ch + och] = (sox_sample_t)sum;
            }
        }
    }

    *isamp = frames * in_ch;
    *osamp = frames * out_ch;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: reverse
 * ===================================================================== */

typedef struct {
    sox_sample_t *buf;
    size_t buf_size;
    size_t buf_used;
} reverse_priv_t;

static int reverse_start(sox_effect_t *eff) {
    reverse_priv_t *p = (reverse_priv_t *)eff->priv;
    p->buf = NULL; p->buf_size = 0; p->buf_used = 0;
    return SOX_SUCCESS;
}

static int reverse_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                         size_t *isamp, size_t *osamp) {
    reverse_priv_t *p = (reverse_priv_t *)eff->priv;
    size_t len = *isamp;

    if (p->buf_used + len > p->buf_size) {
        p->buf_size = (p->buf_used + len) * 2;
        p->buf = realloc(p->buf, p->buf_size * sizeof(sox_sample_t));
    }
    memcpy(p->buf + p->buf_used, ibuf, len * sizeof(sox_sample_t));
    p->buf_used += len;

    *isamp = len;
    *osamp = 0;
    return SOX_SUCCESS;
}

static int reverse_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    reverse_priv_t *p = (reverse_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    if (p->buf_used == 0) { *osamp = 0; return SOX_EOF; }

    /* Reverse the buffer */
    size_t frames = p->buf_used / channels;
    for (size_t i = 0; i < frames / 2; i++) {
        size_t j = frames - 1 - i;
        for (unsigned ch = 0; ch < channels; ch++) {
            sox_sample_t tmp = p->buf[i * channels + ch];
            p->buf[i * channels + ch] = p->buf[j * channels + ch];
            p->buf[j * channels + ch] = tmp;
        }
    }

    size_t to_output = p->buf_used < *osamp ? p->buf_used : *osamp;
    memcpy(obuf, p->buf, to_output * sizeof(sox_sample_t));
    p->buf_used -= to_output;
    if (p->buf_used > 0)
        memmove(p->buf, p->buf + to_output, p->buf_used * sizeof(sox_sample_t));

    *osamp = to_output;
    return (p->buf_used == 0) ? SOX_EOF : SOX_SUCCESS;
}

static int reverse_stop(sox_effect_t *eff) {
    reverse_priv_t *p = (reverse_priv_t *)eff->priv;
    if (p->buf) free(p->buf);
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: swap (swap channels)
 * ===================================================================== */

static int swap_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t frames = len / channels;
    size_t f;

    for (f = 0; f < frames; f++) {
        if (channels >= 2) {
            obuf[f * channels + 0] = ibuf[f * channels + 1];
            obuf[f * channels + 1] = ibuf[f * channels + 0];
            unsigned ch;
            for (ch = 2; ch < channels; ch++)
                obuf[f * channels + ch] = ibuf[f * channels + ch];
        } else {
            obuf[f] = ibuf[f];
        }
    }

    *isamp = frames * channels;
    *osamp = frames * channels;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: repeat
 * ===================================================================== */

typedef struct {
    int count;
    sox_sample_t *buf;
    size_t buf_size;
    size_t buf_used;
    int repeat_idx;
    size_t read_pos;
} repeat_priv_t;

static int repeat_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    repeat_priv_t *p = (repeat_priv_t *)eff->priv;
    p->count = 1;
    if (argc > 0) p->count = atoi(argv[0]);
    return SOX_SUCCESS;
}

static int repeat_start(sox_effect_t *eff) {
    repeat_priv_t *p = (repeat_priv_t *)eff->priv;
    p->buf = NULL; p->buf_size = 0; p->buf_used = 0;
    p->repeat_idx = 0; p->read_pos = 0;
    if (eff->in_signal.length != 0) {
        eff->out_signal.length = eff->in_signal.length * (1 + p->count);
    }
    return SOX_SUCCESS;
}

static int repeat_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                        size_t *isamp, size_t *osamp) {
    repeat_priv_t *p = (repeat_priv_t *)eff->priv;

    /* Buffer all input */
    if (p->buf_used + *isamp > p->buf_size) {
        p->buf_size = (p->buf_used + *isamp) * 2;
        p->buf = realloc(p->buf, p->buf_size * sizeof(sox_sample_t));
    }
    memcpy(p->buf + p->buf_used, ibuf, *isamp * sizeof(sox_sample_t));
    p->buf_used += *isamp;

    /* Output from buffer directly */
    size_t to_out = *isamp < *osamp ? *isamp : *osamp;
    memcpy(obuf, ibuf, to_out * sizeof(sox_sample_t));
    *osamp = to_out;
    return SOX_SUCCESS;
}

static int repeat_drain(sox_effect_t *eff, sox_sample_t *obuf, size_t *osamp) {
    repeat_priv_t *p = (repeat_priv_t *)eff->priv;

    if (p->repeat_idx >= p->count) { *osamp = 0; return SOX_EOF; }

    size_t remaining = p->buf_used - p->read_pos;
    size_t to_out = remaining < *osamp ? remaining : *osamp;

    memcpy(obuf, p->buf + p->read_pos, to_out * sizeof(sox_sample_t));
    p->read_pos += to_out;

    if (p->read_pos >= p->buf_used) {
        p->read_pos = 0;
        p->repeat_idx++;
    }

    *osamp = to_out;
    return (p->repeat_idx >= p->count && to_out == 0) ? SOX_EOF : SOX_SUCCESS;
}

static int repeat_stop(sox_effect_t *eff) {
    repeat_priv_t *p = (repeat_priv_t *)eff->priv;
    if (p->buf) free(p->buf);
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: dcshift
 * ===================================================================== */

typedef struct {
    double shift;
    double limiter;
} dcshift_priv_t;

static int dcshift_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    dcshift_priv_t *p = (dcshift_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("dcshift: missing argument"); return SOX_EOF; }
    p->shift = strtod(argv[0], NULL);
    p->limiter = 0;
    if (argc > 1) p->limiter = strtod(argv[1], NULL);
    return SOX_SUCCESS;
}

static int dcshift_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                         size_t *isamp, size_t *osamp) {
    dcshift_priv_t *p = (dcshift_priv_t *)eff->priv;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;
    double shift = p->shift;

    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] / 2147483648.0 + shift;
        if (s > 1.0) { s = 1.0; eff->clips++; }
        if (s < -1.0) { s = -1.0; eff->clips++; }
        obuf[i] = (sox_sample_t)(s * 2147483647.0);
    }
    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: fade
 * ===================================================================== */

typedef struct {
    char type;   /* q, h, t, l, p */
    double in_len;
    double stop_pos;
    double out_len;
    uint64_t samples_done;
    uint64_t in_samples;
    uint64_t total_samples;
    uint64_t out_start;
    unsigned channels;
} fade_priv_t;

static double fade_curve(char type, double pos) {
    switch (type) {
        case 'q': return pos * pos;
        case 'h': return (1.0 - cos(M_PI * pos)) / 2.0;
        case 't': return pos;
        case 'l': return pow(0.1, (1.0 - pos) * 5.0);
        case 'p': {
            double t = pos;
            return 3*t*t - 2*t*t*t;
        }
        default: return pos;
    }
}

static int fade_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    fade_priv_t *p = (fade_priv_t *)eff->priv;
    int i = 0;

    p->type = 'l';
    p->in_len = 0;
    p->stop_pos = -1;
    p->out_len = 0;

    /* Check for type */
    if (i < argc && strlen(argv[i]) == 1 && strchr("qhtlp", argv[i][0])) {
        p->type = argv[i][0];
        i++;
    }

    if (i < argc) { p->in_len = parse_time(argv[i]); i++; }
    if (i < argc) { p->stop_pos = parse_time(argv[i]); i++; }
    if (i < argc) { p->out_len = parse_time(argv[i]); i++; }

    return SOX_SUCCESS;
}

static int fade_start(sox_effect_t *eff) {
    fade_priv_t *p = (fade_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    unsigned channels = eff->in_signal.channels;

    if (channels == 0) channels = 1;
    p->channels = channels;
    p->samples_done = 0;
    p->in_samples = (uint64_t)(p->in_len * rate) * channels;

    if (p->stop_pos >= 0) {
        p->total_samples = (uint64_t)(p->stop_pos * rate) * channels;
        if (p->out_len > 0) {
            p->out_start = p->total_samples - (uint64_t)(p->out_len * rate) * channels;
        } else {
            p->out_start = p->total_samples;
        }
    } else {
        p->total_samples = UINT64_MAX;
        p->out_start = UINT64_MAX;
    }

    return SOX_SUCCESS;
}

static int fade_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    fade_priv_t *p = (fade_priv_t *)eff->priv;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;

    for (i = 0; i < len; i++) {
        uint64_t idx = p->samples_done + i;
        double gain = 1.0;

        /* Fade in */
        if (idx < p->in_samples) {
            double pos = (double)idx / (double)p->in_samples;
            gain = fade_curve(p->type, pos);
        }

        /* Fade out */
        if (p->out_start != UINT64_MAX && idx >= p->out_start) {
            uint64_t out_len_samp = p->total_samples - p->out_start;
            double pos = 1.0;
            if (out_len_samp > 0)
                pos = (double)(idx - p->out_start) / (double)out_len_samp;
            gain *= fade_curve(p->type, 1.0 - pos);
        }

        /* Stop at total */
        if (p->total_samples != UINT64_MAX && idx >= p->total_samples) {
            *isamp = i;
            *osamp = i;
            return SOX_EOF;
        }

        double s = (double)ibuf[i] * gain;
        if (s > SOX_SAMPLE_MAX) { s = SOX_SAMPLE_MAX; eff->clips++; }
        if (s < SOX_SAMPLE_MIN) { s = SOX_SAMPLE_MIN; eff->clips++; }
        obuf[i] = (sox_sample_t)s;
    }

    p->samples_done += len;
    *isamp = len;
    *osamp = len;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: echo
 * ===================================================================== */

typedef struct {
    double gain_in;
    double gain_out;
    int n_delays;
    double delay[8];
    double decay[8];
    sox_sample_t *buf;
    size_t buf_size;
    size_t *buf_pos;
    size_t *delay_samp;
} echo_priv_t;

static int echo_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    echo_priv_t *p = (echo_priv_t *)eff->priv;
    if (argc < 4) { lsx_fail("echo: need gain-in gain-out delay decay [...]"); return SOX_EOF; }

    p->gain_in = strtod(argv[0], NULL);
    p->gain_out = strtod(argv[1], NULL);
    p->n_delays = 0;

    int i;
    for (i = 2; i+1 < argc && p->n_delays < 8; i += 2) {
        p->delay[p->n_delays] = strtod(argv[i], NULL);      /* ms */
        p->decay[p->n_delays] = strtod(argv[i+1], NULL);
        p->n_delays++;
    }
    return SOX_SUCCESS;
}

static int echo_start(sox_effect_t *eff) {
    echo_priv_t *p = (echo_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    p->buf_pos = calloc(p->n_delays, sizeof(size_t));
    p->delay_samp = calloc(p->n_delays, sizeof(size_t));

    size_t max_delay_samp = 0;
    int i;
    for (i = 0; i < p->n_delays; i++) {
        p->delay_samp[i] = (size_t)(p->delay[i] * rate / 1000.0) * channels;
        if (p->delay_samp[i] > max_delay_samp) max_delay_samp = p->delay_samp[i];
    }

    p->buf_size = max_delay_samp + 1;
    p->buf = calloc(p->buf_size, sizeof(sox_sample_t));

    return SOX_SUCCESS;
}

static int echo_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    echo_priv_t *p = (echo_priv_t *)eff->priv;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;

    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] * p->gain_in;
        int j;
        for (j = 0; j < p->n_delays; j++) {
            /* Add echo from delay buffer */
            size_t pos = (p->buf_pos[j] + p->buf_size - p->delay_samp[j]) % p->buf_size;
            s += (double)p->buf[pos] * p->decay[j];
        }

        s *= p->gain_out;
        if (s > SOX_SAMPLE_MAX) { s = SOX_SAMPLE_MAX; eff->clips++; }
        if (s < SOX_SAMPLE_MIN) { s = SOX_SAMPLE_MIN; eff->clips++; }
        obuf[i] = (sox_sample_t)s;

        /* Update delay buffer */
        for (j = 0; j < p->n_delays; j++) {
            p->buf[p->buf_pos[j]] = ibuf[i];
            p->buf_pos[j] = (p->buf_pos[j] + 1) % p->buf_size;
        }
    }

    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

static int echo_stop(sox_effect_t *eff) {
    echo_priv_t *p = (echo_priv_t *)eff->priv;
    if (p->buf) free(p->buf);
    if (p->buf_pos) free(p->buf_pos);
    if (p->delay_samp) free(p->delay_samp);
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: echos (echo with feedback)
 * ===================================================================== */

static int echos_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                       size_t *isamp, size_t *osamp) {
    echo_priv_t *p = (echo_priv_t *)eff->priv;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;

    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] * p->gain_in;
        int j;
        for (j = 0; j < p->n_delays; j++) {
            size_t pos = (p->buf_pos[j] + p->buf_size - p->delay_samp[j]) % p->buf_size;
            s += (double)p->buf[pos] * p->decay[j];
        }

        s *= p->gain_out;
        sox_sample_t out_s;
        if (s > SOX_SAMPLE_MAX) { out_s = SOX_SAMPLE_MAX; eff->clips++; }
        else if (s < SOX_SAMPLE_MIN) { out_s = SOX_SAMPLE_MIN; eff->clips++; }
        else out_s = (sox_sample_t)s;
        obuf[i] = out_s;

        for (j = 0; j < p->n_delays; j++) {
            p->buf[p->buf_pos[j]] = out_s;  /* echo feeds back from output */
            p->buf_pos[j] = (p->buf_pos[j] + 1) % p->buf_size;
        }
    }

    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

