}

/* Equalizer */
typedef struct {
    biquad_priv_t b;
    double freq, width, gain;
    int width_type;
} eq_priv_t;

static void set_biquad_peaking(biquad_priv_t *p, double freq, double q, double gain_db, double rate) {
    double A = pow(10.0, gain_db / 40.0);
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha / A;
    p->b0 = (1.0 + alpha * A) / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = (1.0 - alpha * A) / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha / A) / a0;
}

static int equalizer_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    eq_priv_t *p = (eq_priv_t *)eff->priv;
    p->width = 0.5; p->width_type = 2;
    if (argc > 0) p->freq = strtod(argv[0], NULL);
    if (argc > 1) p->width = parse_freq_width(argv[1], p->freq, &p->width_type);
    if (argc > 2) p->gain = strtod(argv[2], NULL);
    return SOX_SUCCESS;
}

static int equalizer_start(sox_effect_t *eff) {
    eq_priv_t *p = (eq_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double q = width_to_q(p->width, p->width_type, p->freq);
    set_biquad_peaking(&p->b, p->freq, q, p->gain, rate);
    biquad_start(eff);
    eff->priv = &p->b;  /* point to biquad state */
    return SOX_SUCCESS;
}

/* This won't work as written - the priv pointer change is a hack */
/* Let's use a different approach */

static int eq_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                    size_t *isamp, size_t *osamp) {
    eq_priv_t *p = (eq_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;
    size_t frames = (*isamp < *osamp ? *isamp : *osamp) / channels;
    size_t f;
    unsigned ch;

    for (f = 0; f < frames; f++) {
        for (ch = 0; ch < channels && ch < 8; ch++) {
            double x0 = (double)ibuf[f*channels+ch] / 2147483648.0;
            double y0 = p->b.b0 * x0 + p->b.b1 * p->b.x1[ch] + p->b.b2 * p->b.x2[ch]
                        - p->b.a1 * p->b.y1[ch] - p->b.a2 * p->b.y2[ch];
            p->b.x2[ch] = p->b.x1[ch]; p->b.x1[ch] = x0;
            p->b.y2[ch] = p->b.y1[ch]; p->b.y1[ch] = y0;
            if (y0 > 1.0) { y0 = 1.0; eff->clips++; }
            if (y0 < -1.0) { y0 = -1.0; eff->clips++; }
            obuf[f*channels+ch] = (sox_sample_t)(y0 * 2147483647.0);
        }
    }
    *isamp = frames * channels;
    *osamp = frames * channels;
    return SOX_SUCCESS;
}

static int equalizer_start2(sox_effect_t *eff) {
