}

static int bandpass_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double bw = p->width;
    set_biquad_bandpass(&p->b, p->freq, bw, rate, p->poles == 3);
    return biquad_start(eff);
}

/* Bandreject */
static void set_biquad_bandreject(biquad_priv_t *p, double freq, double bw, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) * sinh(log(2.0) / 2.0 * bw * w0 / sin(w0));
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = 1.0 / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = 1.0 / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

static int bandreject_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    set_biquad_bandreject(&p->b, p->freq, p->width, rate);
    return biquad_start(eff);
}

/* Allpass */
static void set_biquad_allpass(biquad_priv_t *p, double freq, double q, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = (1.0 - alpha) / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = 1.0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

static int allpass_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    p->width = 0.5; p->width_type = 2;
    if (argc > 0) p->freq = strtod(argv[0], NULL);
    if (argc > 1) p->width = parse_freq_width(argv[1], p->freq, &p->width_type);
    return SOX_SUCCESS;
}

static int allpass_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double q = width_to_q(p->width, p->width_type, p->freq);
    set_biquad_allpass(&p->b, p->freq, q, rate);
    return biquad_start(eff);
}

/* Equalizer */
typedef struct {
    biquad_priv_t b;
    double freq, width, gain;
    int width_type;
} eq_priv_t;

static void set_biquad_peaking(biquad_priv_t *p, double freq, double q, double gain_db, double rate) {
    double A = pow(10.0, gain_db / 40.0);
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha / A;
    p->b0 = (1.0 + alpha * A) / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = (1.0 - alpha * A) / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha / A) / a0;
}

static int equalizer_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    eq_priv_t *p = (eq_priv_t *)eff->priv;
    p->width = 0.5; p->width_type = 2;
    if (argc > 0) p->freq = strtod(argv[0], NULL);
    if (argc > 1) p->width = parse_freq_width(argv[1], p->freq, &p->width_type);
    if (argc > 2) p->gain = strtod(argv[2], NULL);
    return SOX_SUCCESS;
}

static int equalizer_start(sox_effect_t *eff) {
    eq_priv_t *p = (eq_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double q = width_to_q(p->width, p->width_type, p->freq);
    set_biquad_peaking(&p->b, p->freq, q, p->gain, rate);
    biquad_start(eff);
    eff->priv = &p->b;  /* point to biquad state */
    return SOX_SUCCESS;
}

/* This won't work as written - the priv pointer change is a hack */
