}

static int biquad_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                        size_t *isamp, size_t *osamp) {
    biquad_priv_t *p = (biquad_priv_t *)eff->priv;
    unsigned channels = p->channels;
    size_t frames = (*isamp < *osamp ? *isamp : *osamp) / channels;
