/* Bandreject */
static void set_biquad_bandreject(biquad_priv_t *p, double freq, double bw, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) * sinh(log(2.0) / 2.0 * bw * w0 / sin(w0));
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = 1.0 / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = 1.0 / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

static int bandreject_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    set_biquad_bandreject(&p->b, p->freq, p->width, rate);
    return biquad_start(eff);
}

/* Allpass */
static void set_biquad_allpass(biquad_priv_t *p, double freq, double q, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = (1.0 - alpha) / a0;
    p->b1 = -2.0 * cos_w0 / a0;
    p->b2 = 1.0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

