static int loudness_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    loudness_priv_t *p = (loudness_priv_t *)eff->priv;
    double gain = pow(10.0, p->gain_db / 20.0);
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;
