static int overdrive_start(sox_effect_t *eff) { (void)eff; return SOX_SUCCESS; }
static int overdrive_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                           size_t *isamp, size_t *osamp) {
    overdrive_priv_t *p = (overdrive_priv_t *)eff->priv;
    double gain = pow(10.0, p->gain / 20.0);
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;
    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] / 2147483648.0 * gain;
        /* Soft clipping */
        if (s >= 1.0) s = 1.0;
        else if (s <= -1.0) s = -1.0;
        else if (s > 2.0/3.0) s = (3.0 - (2.0 - s*3.0)*(2.0 - s*3.0)) / 3.0;
        else if (s < -2.0/3.0) s = -(3.0 - (2.0 + s*3.0)*(2.0 + s*3.0)) / 3.0;
        else s = 2.0 * s;
        s /= 2.0;
        obuf[i] = (sox_sample_t)(s * 2147483647.0);
    }
    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

/* contrast */
typedef struct { double enhancement; } contrast_priv_t;
static int contrast_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    contrast_priv_t *p = (contrast_priv_t *)eff->priv;
    p->enhancement = 75.0;
    if (argc > 0) p->enhancement = strtod(argv[0], NULL);
    return SOX_SUCCESS;
}
static int contrast_start(sox_effect_t *eff) { (void)eff; return SOX_SUCCESS; }
static int contrast_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    contrast_priv_t *p = (contrast_priv_t *)eff->priv;
    double enh = p->enhancement / 100.0;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;
    for (i = 0; i < len; i++) {
        double s = (double)ibuf[i] / 2147483648.0;
        /* Wavefold distortion */
        s = sin(M_PI / 2.0 * s * (1.0 + enh));
        obuf[i] = (sox_sample_t)(s * 2147483647.0);
    }
    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

