/* =====================================================================
 * EFFECT: oops (stereo to mono, out-of-phase)
 * ===================================================================== */

static int oops_start(sox_effect_t *eff) {
    eff->out_signal.channels = 1;
    return SOX_SUCCESS;
}

static int oops_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                     size_t *isamp, size_t *osamp) {
    unsigned in_ch = eff->in_signal.channels;
    if (in_ch < 2) {
        size_t len = *isamp < *osamp ? *isamp : *osamp;
        memcpy(obuf, ibuf, len * sizeof(sox_sample_t));
        *isamp = len; *osamp = len;
        return SOX_SUCCESS;
    }
    size_t in_frames = *isamp / in_ch;
    size_t out_frames = *osamp;
    size_t frames = in_frames < out_frames ? in_frames : out_frames;
    size_t f;
    for (f = 0; f < frames; f++) {
        double l = (double)ibuf[f*in_ch+0];
        double r = (double)ibuf[f*in_ch+1];
        double s = (l - r) / 2.0;
        obuf[f] = (sox_sample_t)s;
    }
    *isamp = frames * in_ch;
    *osamp = frames;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: deemph (de-emphasis)
 * ===================================================================== */

typedef struct {
    double b0, b1, a1;
    double y1[8];  /* per-channel history */
} deemph_priv_t;

static int deemph_start(sox_effect_t *eff) {
    deemph_priv_t *p = (deemph_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    /* De-emphasis filter for 44100 Hz */
    /* Bilinear transform of analog: H(s) = (1 + s/318e-6) / (1 + s/75e-6) */
    double w0 = 2.0 * M_PI * (1.0 / (318e-6 * 2.0 * rate));
    /* Simplified de-emphasis for standard rates */
    p->b0 = 1.0; p->b1 = -0.5; p->a1 = -0.5;
    memset(p->y1, 0, sizeof(p->y1));
    (void)w0;
    return SOX_SUCCESS;
}

static int deemph_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                       size_t *isamp, size_t *osamp) {
    deemph_priv_t *p = (deemph_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;
    size_t frames = (*isamp < *osamp ? *isamp : *osamp) / channels;
    size_t f;
    unsigned ch;
    for (f = 0; f < frames; f++) {
        for (ch = 0; ch < channels && ch < 8; ch++) {
            double x = (double)ibuf[f*channels+ch];
            double y = p->b0 * x + p->b1 * p->y1[ch] - p->a1 * p->y1[ch];
            /* Simple high-shelf filter */
            obuf[f*channels+ch] = (sox_sample_t)x;  /* pass through for now */
            p->y1[ch] = x;
        }
    }
    *isamp = frames * channels; *osamp = frames * channels;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: speed
 * ===================================================================== */

typedef struct {
    double factor;
} speed_priv_t;

static int speed_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    speed_priv_t *p = (speed_priv_t *)eff->priv;
    if (argc < 1) { lsx_fail("speed: missing argument"); return SOX_EOF; }
    p->factor = strtod(argv[0], NULL);
    return SOX_SUCCESS;
}

static int speed_start(sox_effect_t *eff) {
    speed_priv_t *p = (speed_priv_t *)eff->priv;
    if (p->factor > 0) {
        eff->out_signal.rate = eff->in_signal.rate * p->factor;
    }
    return SOX_SUCCESS;
}

static int speed_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                      size_t *isamp, size_t *osamp) {
    /* Speed change = resample the rate */
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    memcpy(obuf, ibuf, len * sizeof(sox_sample_t));
    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

/* =====================================================================
 * EFFECT: downsample / upsample
 * ===================================================================== */

typedef struct { int factor; } downsample_priv_t;

static int downsample_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    p->factor = 2;
    if (argc > 0) p->factor = atoi(argv[0]);
    eff->out_signal.rate = eff->in_signal.rate / p->factor;
    return SOX_SUCCESS;
}

static int downsample_start(sox_effect_t *eff) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    eff->out_signal.rate = eff->in_signal.rate / p->factor;
    return SOX_SUCCESS;
}

static int downsample_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                           size_t *isamp, size_t *osamp) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    size_t in_frames = *isamp / channels;
    size_t out_idx = 0;
    size_t f;

    for (f = 0; f < in_frames; f += p->factor) {
        if (out_idx * channels + channels > *osamp) break;
        unsigned ch;
        for (ch = 0; ch < channels; ch++) {
            obuf[out_idx * channels + ch] = ibuf[f * channels + ch];
        }
        out_idx++;
    }

    *isamp = in_frames * channels;
    *osamp = out_idx * channels;
    return SOX_SUCCESS;
}

static int upsample_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    p->factor = 2;
    if (argc > 0) p->factor = atoi(argv[0]);
    eff->out_signal.rate = eff->in_signal.rate * p->factor;
    return SOX_SUCCESS;
}

static int upsample_start(sox_effect_t *eff) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    eff->out_signal.rate = eff->in_signal.rate * p->factor;
    return SOX_SUCCESS;
}

static int upsample_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    downsample_priv_t *p = (downsample_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;

    size_t in_frames = *isamp / channels;
    size_t out_idx = 0;
    size_t f;

    for (f = 0; f < in_frames; f++) {
        int rep;
        for (rep = 0; rep < p->factor; rep++) {
            if ((out_idx + 1) * channels > *osamp) goto done_up;
            unsigned ch;
            for (ch = 0; ch < channels; ch++) {
                obuf[out_idx * channels + ch] = ibuf[f * channels + ch];
            }
            out_idx++;
        }
    }
done_up:
    *isamp = in_frames * channels;
    *osamp = out_idx * channels;
    return SOX_SUCCESS;
}

/* =====================================================================
 * BIQUAD FILTER BASE
 * ===================================================================== */

typedef struct {
    double b0, b1, b2, a1, a2;
    double x1[8], x2[8], y1[8], y2[8];
    unsigned channels;
} biquad_priv_t;

static int biquad_start(sox_effect_t *eff) {
    biquad_priv_t *p = (biquad_priv_t *)eff->priv;
    p->channels = eff->in_signal.channels;
    if (p->channels == 0) p->channels = 1;
    memset(p->x1, 0, sizeof(p->x1));
    memset(p->x2, 0, sizeof(p->x2));
    memset(p->y1, 0, sizeof(p->y1));
    memset(p->y2, 0, sizeof(p->y2));
    return SOX_SUCCESS;
}

static int biquad_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                        size_t *isamp, size_t *osamp) {
    biquad_priv_t *p = (biquad_priv_t *)eff->priv;
    unsigned channels = p->channels;
    size_t frames = (*isamp < *osamp ? *isamp : *osamp) / channels;
    size_t f;
    unsigned ch;

    for (f = 0; f < frames; f++) {
        for (ch = 0; ch < channels && ch < 8; ch++) {
            double x0 = (double)ibuf[f*channels+ch] / 2147483648.0;
            double y0 = p->b0 * x0 + p->b1 * p->x1[ch] + p->b2 * p->x2[ch]
                        - p->a1 * p->y1[ch] - p->a2 * p->y2[ch];
            p->x2[ch] = p->x1[ch]; p->x1[ch] = x0;
            p->y2[ch] = p->y1[ch]; p->y1[ch] = y0;
            if (y0 > 1.0) { y0 = 1.0; eff->clips++; }
            if (y0 < -1.0) { y0 = -1.0; eff->clips++; }
            obuf[f*channels+ch] = (sox_sample_t)(y0 * 2147483647.0);
        }
    }
    *isamp = frames * channels;
    *osamp = frames * channels;
    return SOX_SUCCESS;
}

/* Parse width with suffix (h=Hz, k=kHz, q=Q, o=octave, s=slope) */
static double parse_freq_width(const char *s, double freq, int *type) {
    char *end;
    double v = strtod(s, &end);
    *type = 0;
    if (*end == 'k' || *end == 'K') v *= 1000;
    else if (*end == 'h' || *end == 'H') *type = 1;  /* Hz BW */
    else if (*end == 'q' || *end == 'Q') *type = 2;  /* Q */
    else if (*end == 'o' || *end == 'O') *type = 3;  /* octaves */
    else if (*end == 's' || *end == 'S') *type = 4;  /* slope */
    return v;
}

static double width_to_q(double width, int type, double freq) {
    switch (type) {
        case 1: return freq / width;  /* Hz to Q */
        case 2: return width;
        case 3: {  /* octaves to Q */
            double w = width * M_PI / 2.0 * log(2.0);
            return 1.0 / (2.0 * sinh(w));
        }
        case 4: return sqrt(width) / width;  /* slope to Q */
        default: return width;  /* assume Q */
    }
}

/* Allpass, bandpass, etc. using biquad */
static void set_biquad_lowpass(biquad_priv_t *p, double freq, double q, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = (1.0 - cos_w0) / 2.0 / a0;
    p->b1 = (1.0 - cos_w0) / a0;
    p->b2 = (1.0 - cos_w0) / 2.0 / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

static void set_biquad_highpass(biquad_priv_t *p, double freq, double q, double rate) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / (2.0 * q);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    p->b0 = (1.0 + cos_w0) / 2.0 / a0;
    p->b1 = -(1.0 + cos_w0) / a0;
    p->b2 = (1.0 + cos_w0) / 2.0 / a0;
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

static void set_biquad_bandpass(biquad_priv_t *p, double freq, double bw, double rate, int const_skirt) {
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) * sinh(log(2.0) / 2.0 * bw * w0 / sin(w0));
    double sin_w0 = sin(w0);
    double cos_w0 = cos(w0);
    double a0 = 1.0 + alpha;
    if (const_skirt) {
        p->b0 = sin_w0 / 2.0 / a0;
        p->b1 = 0;
        p->b2 = -sin_w0 / 2.0 / a0;
    } else {
        p->b0 = alpha / a0;
        p->b1 = 0;
        p->b2 = -alpha / a0;
    }
    p->a1 = -2.0 * cos_w0 / a0;
    p->a2 = (1.0 - alpha) / a0;
}

/* Lowpass effect */
typedef struct {
    biquad_priv_t b;
    double freq;
    double width;
    int width_type;
    int poles;
} filt_priv_t;

static int lowpass_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    int i = 0;
    p->poles = 2;
    p->width = 0.707;
    p->width_type = 2;  /* Q */

    if (i < argc && strcmp(argv[i], "-1") == 0) { p->poles = 1; i++; }
    else if (i < argc && strcmp(argv[i], "-2") == 0) { p->poles = 2; i++; }

    if (i < argc) { p->freq = strtod(argv[i], NULL); i++; }
    if (i < argc) {
        p->width = parse_freq_width(argv[i], p->freq, &p->width_type);
    }
    return SOX_SUCCESS;
}

static int lowpass_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double q = width_to_q(p->width, p->width_type, p->freq);
    set_biquad_lowpass(&p->b, p->freq, q, rate);
    return biquad_start(eff);
}

static int lowpass_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                         size_t *isamp, size_t *osamp) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    biquad_priv_t *b = &p->b;
    biquad_priv_t *save = (biquad_priv_t *)eff->priv;
    eff->priv = b;
    int ret = biquad_flow(eff, ibuf, obuf, isamp, osamp);
    eff->priv = save;
    return ret;
}

/* Highpass */
static int highpass_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    return lowpass_getopts(eff, argc, argv);
}

static int highpass_start(sox_effect_t *eff) {
    filt_priv_t *p = (filt_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    double q = width_to_q(p->width, p->width_type, p->freq);
    set_biquad_highpass(&p->b, p->freq, q, rate);
    return biquad_start(eff);
}

static int highpass_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
