    memset(p->b.y2, 0, sizeof(p->b.y2));
    return SOX_SUCCESS;
}

/* bass and treble effects */
static void set_biquad_shelf(biquad_priv_t *p, double freq, double q, double gain_db, double rate, int is_high) {
    double A = pow(10.0, gain_db / 40.0);
    double w0 = 2.0 * M_PI * freq / rate;
    double alpha = sin(w0) / 2.0 * sqrt((A + 1.0/A) * (1.0/0.9 - 1.0) + 2.0);
    double cos_w0 = cos(w0);
    double a0;

    if (!is_high) {
        /* Low shelf */
        a0 = (A+1.0) + (A-1.0)*cos_w0 + 2.0*sqrt(A)*alpha;
        p->b0 = A * ((A+1.0) - (A-1.0)*cos_w0 + 2.0*sqrt(A)*alpha) / a0;
        p->b1 = 2.0 * A * ((A-1.0) - (A+1.0)*cos_w0) / a0;
        p->b2 = A * ((A+1.0) - (A-1.0)*cos_w0 - 2.0*sqrt(A)*alpha) / a0;
        p->a1 = -2.0 * ((A-1.0) + (A+1.0)*cos_w0) / a0;
        p->a2 = ((A+1.0) + (A-1.0)*cos_w0 - 2.0*sqrt(A)*alpha) / a0;
    } else {
        /* High shelf */
        a0 = (A+1.0) - (A-1.0)*cos_w0 + 2.0*sqrt(A)*alpha;
        p->b0 = A * ((A+1.0) + (A-1.0)*cos_w0 + 2.0*sqrt(A)*alpha) / a0;
        p->b1 = -2.0 * A * ((A-1.0) + (A+1.0)*cos_w0) / a0;
        p->b2 = A * ((A+1.0) + (A-1.0)*cos_w0 - 2.0*sqrt(A)*alpha) / a0;
        p->a1 = 2.0 * ((A-1.0) - (A+1.0)*cos_w0) / a0;
        p->a2 = ((A+1.0) - (A-1.0)*cos_w0 - 2.0*sqrt(A)*alpha) / a0;
    }
}

typedef eq_priv_t bass_priv_t;

static int bass_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    bass_priv_t *p = (bass_priv_t *)eff->priv;
    p->freq = 100.0; p->width = 0.5; p->width_type = 4; /* slope */
    if (argc > 0) p->gain = strtod(argv[0], NULL);
    if (argc > 1) p->freq = strtod(argv[1], NULL);
    if (argc > 2) p->width = parse_freq_width(argv[2], p->freq, &p->width_type);
    return SOX_SUCCESS;
}

static int bass_start(sox_effect_t *eff) {
    bass_priv_t *p = (bass_priv_t *)eff->priv;
    double rate = eff->in_signal.rate;
    set_biquad_shelf(&p->b, p->freq, 1.0, p->gain, rate, 0);
    p->b.channels = eff->in_signal.channels; if (!p->b.channels) p->b.channels = 1;
    memset(p->b.x1,0,sizeof(p->b.x1)); memset(p->b.x2,0,sizeof(p->b.x2));
    memset(p->b.y1,0,sizeof(p->b.y1)); memset(p->b.y2,0,sizeof(p->b.y2));
    return SOX_SUCCESS;
