static int treble_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    return bass_getopts(eff, argc, argv);
}

static int treble_start(sox_effect_t *eff) {
    bass_priv_t *p = (bass_priv_t *)eff->priv;
    p->freq = p->freq > 0 ? p->freq : 3000.0;
    double rate = eff->in_signal.rate;
    set_biquad_shelf(&p->b, p->freq, 1.0, p->gain, rate, 1);
    p->b.channels = eff->in_signal.channels; if (!p->b.channels) p->b.channels = 1;
    memset(p->b.x1,0,sizeof(p->b.x1)); memset(p->b.x2,0,sizeof(p->b.x2));
    memset(p->b.y1,0,sizeof(p->b.y1)); memset(p->b.y2,0,sizeof(p->b.y2));
    return SOX_SUCCESS;
}

/* Pass-through effect */
static int passthru_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                          size_t *isamp, size_t *osamp) {
    (void)eff;
    size_t len = *isamp < *osamp ? *isamp : *osamp;
    memcpy(obuf, ibuf, len * sizeof(sox_sample_t));
    *isamp = len; *osamp = len;
    return SOX_SUCCESS;
}

