/* Dither effect (noise shaping) */
typedef struct {
    int shaped;
    int auto_dither;
    char filter[32];
    unsigned prec;
    double err[8];  /* error feedback per channel */
    unsigned random_state;
} dither_priv_t;

static double dither_rand(dither_priv_t *p) {
    p->random_state = p->random_state * 1664525 + 1013904223;
    return (double)(int32_t)p->random_state / (double)0x80000000;
}

static int dither_getopts(sox_effect_t *eff, int argc, char *argv[]) {
    dither_priv_t *p = (dither_priv_t *)eff->priv;
    int i;
    p->random_state = time(NULL);
    for (i = 0; i < argc; i++) {
        if (strcmp(argv[i], "-S") == 0) p->shaped = 1;
        else if (strcmp(argv[i], "-s") == 0) p->shaped = 2;
        else if (strcmp(argv[i], "-a") == 0) p->auto_dither = 1;
        else if (strcmp(argv[i], "-f") == 0 && i+1 < argc) {
            strncpy(p->filter, argv[++i], sizeof(p->filter)-1);
        } else if (strcmp(argv[i], "-p") == 0 && i+1 < argc) {
            p->prec = (unsigned)atoi(argv[++i]);
        }
    }
    return SOX_SUCCESS;
}

static int dither_start(sox_effect_t *eff) {
    dither_priv_t *p = (dither_priv_t *)eff->priv;
    memset(p->err, 0, sizeof(p->err));
    if (p->prec == 0) p->prec = eff->out_encoding.bits_per_sample;
    return SOX_SUCCESS;
}

static int dither_flow(sox_effect_t *eff, const sox_sample_t *ibuf, sox_sample_t *obuf,
                        size_t *isamp, size_t *osamp) {
    dither_priv_t *p = (dither_priv_t *)eff->priv;
    unsigned channels = eff->in_signal.channels;
    if (channels == 0) channels = 1;
    unsigned prec = p->prec ? p->prec : eff->out_encoding.bits_per_sample;
    if (prec == 0) prec = 16;

    size_t len = *isamp < *osamp ? *isamp : *osamp;
    size_t i;

    /* Quantization step */
    double q_step = 1.0 / (double)(1u << (prec - 1));
    double dither_amp = q_step;

    size_t clip_count = 0;
    for (i = 0; i < len; i++) {
        unsigned ch = i % channels;
        if (ch >= 8) ch = 0;
        double s = (double)ibuf[i] / 2147483648.0;

        /* Add TPDF dither */
        if (!globals.no_dither) {
            double d = dither_rand(p) * dither_amp;
            s += d;
        }

        /* Error diffusion */
        if (p->shaped) {
            s += p->err[ch];
        }

        /* Quantize */
        double q = floor(s / q_step + 0.5) * q_step;
        p->err[ch] = s - q;

        if (q >= 1.0) { q = 1.0 - q_step; clip_count++; }
        if (q < -1.0) { q = -1.0; clip_count++; }

        obuf[i] = (sox_sample_t)(q * 2147483647.0);
    }

    if (clip_count > 0) {
        eff->clips += clip_count;
        lsx_warn("dither: dither clipped %zu samples; decrease volume?", clip_count);
    }

    *isamp = len;
    *osamp = len;
    return SOX_SUCCESS;
}

