static effect_entry_t *find_effect(const char *name) {
    for (int i = 0; g_effects[i].name != NULL; i++) {
        if (strcasecmp(g_effects[i].name, name) == 0)
            return &g_effects[i];
    }
    return NULL;
}

static sox_effect_t *create_effect(const char *name) {
    effect_entry_t *e = find_effect(name);
    if (!e) return NULL;

    sox_effect_t *eff = (sox_effect_t *)calloc(1, sizeof(sox_effect_t));
    if (!eff) return NULL;

    eff->handler.name = e->name;
    eff->handler.usage = e->usage;
    eff->handler.flags = e->flags;
    eff->handler.getopts = e->getopts;
    eff->handler.start = e->start;
    eff->handler.flow = e->flow;
    eff->handler.drain = e->drain;
    eff->handler.stop = e->stop;
    eff->handler.priv_size = e->priv_size;

    if (e->priv_size > 0) {
        eff->priv = calloc(1, e->priv_size);
        if (!eff->priv) { free(eff); return NULL; }
    }

    return eff;
}

static void destroy_effect(sox_effect_t *eff) {
    if (!eff) return;
    if (eff->priv) free(eff->priv);
    free(eff);
}

