/* Display soxi info for a file */
static void display_soxi(sox_format_t *ft, const char *info_opt, int total_mode,
                          double *total_duration, uint64_t *total_samples) {
    double duration = 0;
    if (ft->signal.rate > 0 && ft->signal.length > 0) {
        duration = (double)ft->signal.length / ft->signal.rate;
    }

    if (total_samples) *total_samples += ft->signal.length;
    if (total_duration) *total_duration += duration;

    if (!info_opt) {
        /* Full display */
        printf("\n");
        printf("Input File     : '%s'\n", ft->filename);
        printf("Channels       : %u\n", ft->signal.channels);
        printf("Sample Rate    : %g\n", ft->signal.rate);
        printf("Precision      : %u-bit\n", ft->signal.precision);
        if (ft->signal.length > 0 && ft->signal.rate > 0) {
            char dur_buf[32];
            format_duration(dur_buf, sizeof(dur_buf), duration);
            double cdda = duration * 75.0;
            int exact_cdda = (fabs(ft->signal.rate - 44100.0) < 1.0);
            if (exact_cdda) {
                printf("Duration       : %s = %" PRIu64 " samples = %g CDDA sectors\n",
                       dur_buf, ft->signal.length, cdda);
            } else {
                printf("Duration       : %s = %" PRIu64 " samples ~ %g CDDA sectors\n",
                       dur_buf, ft->signal.length, cdda);
            }
        }
        if (ft->filesize > 0) {
            char size_buf[32];
            format_si(size_buf, sizeof(size_buf), (double)ft->filesize);
            printf("File Size      : %s\n", size_buf);
        }
        if (ft->signal.rate > 0 && ft->signal.channels > 0 && ft->encoding.bits_per_sample > 0) {
            double bitrate = ft->signal.rate * ft->signal.channels * ft->encoding.bits_per_sample;
            char br_buf[32];
            format_si(br_buf, sizeof(br_buf), bitrate);
            printf("Bit Rate       : %s\n", br_buf);
        }
        printf("Sample Encoding: %s\n",
               encoding_human(ft->encoding.encoding, ft->encoding.bits_per_sample));
        if (ft->oob.comment && *ft->oob.comment) {
            printf("Comment        : '%s'\n", ft->oob.comment);
        }
        printf("\n");
    } else {
        /* Single field display */
        if (strcmp(info_opt, "-t") == 0) {
            printf("%s\n", ft->filetype ? ft->filetype : "unknown");
        } else if (strcmp(info_opt, "-r") == 0) {
            printf("%g\n", ft->signal.rate);
        } else if (strcmp(info_opt, "-c") == 0) {
            printf("%u\n", ft->signal.channels);
        } else if (strcmp(info_opt, "-s") == 0) {
            if (total_mode) {
                /* handled separately */
            } else {
                printf("%" PRIu64 "\n", ft->signal.length);
            }
        } else if (strcmp(info_opt, "-d") == 0) {
            if (total_mode) {
                /* handled separately */
            } else {
                char dur_buf[32];
                format_duration(dur_buf, sizeof(dur_buf), duration);
                printf("%s\n", dur_buf);
            }
        } else if (strcmp(info_opt, "-D") == 0) {
            if (total_mode) {
                /* handled separately */
            } else {
                printf("%f\n", duration);
            }
        } else if (strcmp(info_opt, "-b") == 0) {
            printf("%u\n", ft->encoding.bits_per_sample);
        } else if (strcmp(info_opt, "-B") == 0) {
            double bitrate = ft->signal.rate * ft->signal.channels * ft->encoding.bits_per_sample;
            char br_buf[32];
            format_si(br_buf, sizeof(br_buf), bitrate);
            printf("%s\n", br_buf);
        } else if (strcmp(info_opt, "-p") == 0) {
            printf("%u\n", ft->signal.precision);
        } else if (strcmp(info_opt, "-e") == 0) {
            printf("%s\n", encoding_short(ft->encoding.encoding));
        } else if (strcmp(info_opt, "-a") == 0) {
            if (ft->oob.comment && *ft->oob.comment) {
                printf("%s\n", ft->oob.comment);
            }
        }
    }
}

