    sox_encodinginfo_t encoding;
    char *type;
    double volume;
    int ignore_length;
    char *comment;
    char *add_comment;
} file_opts_t;

static void init_file_opts(file_opts_t *opts) {
    memset(opts, 0, sizeof(*opts));
    opts->volume = 1.0;
}

/* Progress display */
static void display_progress(uint64_t out_samples, uint64_t total_samples,
                               double elapsed_secs, uint64_t clips,
                               double rate, unsigned channels) {
    if (!globals.show_progress) return;

    double dur = (total_samples > 0 && rate > 0 && channels > 0) ?
                 (double)total_samples / rate / channels : 0;

    double progress = (dur > 0 && elapsed_secs >= 0) ?
                      elapsed_secs / dur : 0;
    if (progress > 1.0) progress = 1.0;

    char elapsed_str[16], remain_str[16], out_str[16];
    format_duration(elapsed_str, sizeof(elapsed_str), elapsed_secs);
    double remain = dur - elapsed_secs;
    if (remain < 0) remain = 0;
    format_duration(remain_str, sizeof(remain_str), remain);
    format_si(out_str, sizeof(out_str), (double)out_samples);

    /* VU meter: 11 chars wide */
    char vu[16];
    int vu_pos = (int)(progress * 10.5);
    memset(vu, ' ', 11);
    vu[5] = '|';
    int i;
    for (i = 0; i < vu_pos && i < 11; i++) {
        if (i < 5) vu[i] = '=';
        else if (i == 5) vu[5] = '|';
        else vu[i] = '=';
    }
    vu[11] = '\0';

    int in_pct = (int)(progress * 100);

    fprintf(stderr, "\rIn:%d%%  %s [%s] Out:%-6s [%s]        Clip:%-6" PRIu64 "  ",
            in_pct, elapsed_str, remain_str, out_str, vu, clips);
    fflush(stderr);
}

