/* Print help for a specific effect or all effects */
static void print_effect_help(const char *name) {
    fprintf(stderr, "%s:      SoX v%s\n\n", g_progname, SOX_VERSION);
    fprintf(stderr, "Effect usage:\n\n");

    if (strcmp(name, "all") == 0) {
        /* Print all effects */
        for (int i = 0; g_effects[i].name != NULL; i++) {
            if (g_effects[i].flags & SOX_EFF_INTERNAL) continue;
            if (g_effects[i].usage) {
                fprintf(stderr, "%s %s\n\n\n", g_effects[i].name, g_effects[i].usage);
            } else {
                fprintf(stderr, "%s \n\n\n", g_effects[i].name);
            }
        }
    } else {
        effect_entry_t *e = find_effect(name);
        if (!e) {
            lsx_fail("--help-effect: `%s' is not a known effect", name);
            return;
        }
        if (e->usage) {
            fprintf(stderr, "%s %s\n\n\n", e->name, e->usage);
        } else {
            fprintf(stderr, "%s \n\n\n", e->name);
        }
    }
}

/* Print help for a specific format */
static void print_format_help(const char *name) {
    fprintf(stderr, "%s:      SoX v%s\n\n", g_progname, SOX_VERSION);

    if (strcmp(name, "all") == 0) {
        for (int i = 0; g_formats[i].names[0] != NULL; i++) {
            format_rec_t *f = &g_formats[i];
            if (f->is_device) continue;

            fprintf(stderr, "Format: %s\n", f->names[0]);
            if (f->description)
                fprintf(stderr, "Description: %s\n", f->description);

            /* Print "Also handles:" for alternate names */
            if (f->names[1] != NULL) {
                fprintf(stderr, "Also handles:");
                for (int j = 1; f->names[j] != NULL; j++) {
                    fprintf(stderr, " %s", f->names[j]);
                }
                fprintf(stderr, "\n");
            }

            if (f->can_read) fprintf(stderr, "Reads: yes\n");
            if (f->can_write) {
                fprintf(stderr, "Writes:\n");
                if (f->write_formats_str) {
                    fprintf(stderr, "%s", f->write_formats_str);
                }
            }
            fprintf(stderr, "\n");
        }
    } else {
        format_rec_t *f = find_format(name);
        if (!f) {
            lsx_fail("--help-format: `%s' is not a known format", name);
            return;
        }
        fprintf(stderr, "Format: %s\n", f->names[0]);
        if (f->description) fprintf(stderr, "Description: %s\n", f->description);
        if (f->names[1]) {
            fprintf(stderr, "Also handles:");
            for (int j = 1; f->names[j] != NULL; j++)
                fprintf(stderr, " %s", f->names[j]);
            fprintf(stderr, "\n");
        }
        if (f->can_read) fprintf(stderr, "Reads: yes\n");
        if (f->can_write) {
            fprintf(stderr, "Writes:\n");
            if (f->write_formats_str)
                fprintf(stderr, "%s", f->write_formats_str);
        }
        fprintf(stderr, "\n");
    }
}

