/* =====================================================================
 * ARGUMENT PARSING
 * ===================================================================== */

static int parse_rate(const char *s, double *rate) {
    char *end;
    *rate = strtod(s, &end);
    if (*end == 'k' || *end == 'K') *rate *= 1000;
    return (*rate > 0) ? 0 : -1;
}

/* Parse format options starting at argv[*idx], update idx */
static int parse_file_opts(file_opts_t *opts, int argc, char *argv[], int *idx) {
    while (*idx < argc) {
        char *arg = argv[*idx];

        if (strcmp(arg, "-t") == 0 || strcmp(arg, "--type") == 0) {
            if (*idx + 1 >= argc) { lsx_fail("option `%s' requires an argument", arg); return -1; }
            opts->type = argv[++(*idx)];
        } else if (strncmp(arg, "--type=", 7) == 0) {
            opts->type = arg + 7;
        } else if (strcmp(arg, "-e") == 0 || strcmp(arg, "--encoding") == 0) {
            if (*idx + 1 >= argc) { lsx_fail("option `%s' requires an argument", arg); return -1; }
            opts->encoding.encoding = parse_encoding(argv[++(*idx)]);
        } else if (strncmp(arg, "--encoding=", 11) == 0) {
            opts->encoding.encoding = parse_encoding(arg + 11);
        } else if (strcmp(arg, "-b") == 0 || strcmp(arg, "--bits") == 0) {
            if (*idx + 1 >= argc) { lsx_fail("option `%s' requires an argument", arg); return -1; }
            opts->encoding.bits_per_sample = (unsigned)atoi(argv[++(*idx)]);
        } else if (strcmp(arg, "-r") == 0 || strcmp(arg, "--rate") == 0) {
            if (*idx + 1 >= argc) { lsx_fail("option `%s' requires an argument", arg); return -1; }
            parse_rate(argv[++(*idx)], &opts->signal.rate);
        } else if (strcmp(arg, "-c") == 0 || strcmp(arg, "--channels") == 0) {
            if (*idx + 1 >= argc) { lsx_fail("option `%s' requires an argument", arg); return -1; }
            opts->signal.channels = (unsigned)atoi(argv[++(*idx)]);
        } else if (strcmp(arg, "-L") == 0 || strcmp(arg, "--endian") == 0) {
            if (strcmp(arg, "--endian") == 0) {
                if (*idx + 1 >= argc) return -1;
                const char *end = argv[++(*idx)];
                if (strcmp(end, "big") == 0) opts->encoding.reverse_bytes = is_bigendian() ? 0 : 1;
                else if (strcmp(end, "little") == 0) opts->encoding.reverse_bytes = is_bigendian() ? 1 : 0;
                else if (strcmp(end, "swap") == 0) opts->encoding.opposite_endian = 1;
            } else {
                /* -L = little endian */
                opts->encoding.reverse_bytes = is_bigendian() ? 1 : 0;
            }
        } else if (strcmp(arg, "-B") == 0) {
            opts->encoding.reverse_bytes = is_bigendian() ? 0 : 1;
        } else if (strcmp(arg, "-x") == 0 || strcmp(arg, "-N") == 0 || strcmp(arg, "--reverse-nibbles") == 0) {
            opts->encoding.reverse_nibbles = 1;
        } else if (strcmp(arg, "-X") == 0 || strcmp(arg, "--reverse-bits") == 0) {
            opts->encoding.reverse_bits = 1;
        } else if (strcmp(arg, "-v") == 0 || strcmp(arg, "--volume") == 0) {
            if (*idx + 1 >= argc) return -1;
            opts->volume = strtod(argv[++(*idx)], NULL);
        } else if (strcmp(arg, "--ignore-length") == 0) {
            opts->ignore_length = 1;
        } else if (strcmp(arg, "--comment") == 0) {
            if (*idx + 1 >= argc) return -1;
            opts->comment = argv[++(*idx)];
        } else if (strcmp(arg, "--add-comment") == 0) {
            if (*idx + 1 >= argc) return -1;
            opts->add_comment = argv[++(*idx)];
        } else if (strcmp(arg, "--comment-file") == 0) {
            if (*idx + 1 >= argc) return -1;
            /* Read comment from file */
            ++(*idx);
            /* TODO: read file */
        } else if (strcmp(arg, "-C") == 0 || strcmp(arg, "--compression") == 0) {
            if (*idx + 1 >= argc) return -1;
            opts->encoding.compression = strtod(argv[++(*idx)], NULL);
        } else if (strcmp(arg, "--no-glob") == 0) {
            /* ignore */
        } else {
            break;  /* not a format option */
        }
        (*idx)++;
    }
    return 0;
}

/* =====================================================================
 * PROCESSING PIPELINE
 * ===================================================================== */

#define MAX_INPUTS 256
#define MAX_EFFECTS 256

typedef struct {
    sox_format_t **inputs;
    int n_inputs;
    sox_format_t *output;
    sox_effect_t *effects[MAX_EFFECTS];
    int n_effects;
    size_t bufsize;
    int combine_method;
    uint64_t total_out_samples;
    uint64_t total_clips;
    int is_null_output;
} pipeline_t;

/* Main processing function */
static int process(pipeline_t *pipe) {
    size_t bufsize = pipe->bufsize;
    sox_sample_t *ibuf = (sox_sample_t *)malloc(bufsize * sizeof(sox_sample_t));
    sox_sample_t *obuf = (sox_sample_t *)malloc(bufsize * sizeof(sox_sample_t));
    if (!ibuf || !obuf) {
        free(ibuf); free(obuf);
        lsx_fail("out of memory");
        return -1;
    }

    /* Determine total samples */
    uint64_t total_in_samples = 0;
    sox_signalinfo_t out_signal;
    if (pipe->n_inputs > 0) {
        out_signal = pipe->inputs[0]->signal;
        total_in_samples = pipe->inputs[0]->signal.length * pipe->inputs[0]->signal.channels;
        for (int i = 1; i < pipe->n_inputs; i++) {
            if (pipe->combine_method == 0) {  /* concatenate */
                total_in_samples += pipe->inputs[i]->signal.length * pipe->inputs[i]->signal.channels;
            }
        }
    } else {
        memset(&out_signal, 0, sizeof(out_signal));
        out_signal.rate = SOX_DEFAULT_RATE;
        out_signal.channels = SOX_DEFAULT_CHANNELS;
    }

    /* Set up effects chain signal info */
    for (int i = 0; i < pipe->n_effects; i++) {
        sox_effect_t *eff = pipe->effects[i];
        eff->in_signal = out_signal;
        eff->out_signal = out_signal;
        /* Set encoding for dither etc. */
        if (pipe->output && !pipe->is_null_output) {
            eff->out_encoding = pipe->output->encoding;
        }

        if (eff->handler.start) {
            int ret = eff->handler.start(eff);
            if (ret != SOX_SUCCESS) {
                lsx_fail("effect `%s' failed to start", eff->handler.name);
                free(ibuf); free(obuf);
                return -1;
            }
        }

        /* Update signal info for next effect */
        out_signal = eff->out_signal;
    }

    /* Make sure output has right signal info */
    if (pipe->output && !pipe->is_null_output) {
        if (pipe->output->signal.rate == 0)
            pipe->output->signal.rate = out_signal.rate;
        if (pipe->output->signal.channels == 0)
            pipe->output->signal.channels = out_signal.channels;
    }

    /* Display file info if verbose */
    if (globals.show_progress && pipe->n_inputs > 0) {
        sox_format_t *ft = pipe->inputs[0];
        fprintf(stderr, "\nInput File     : '%s'\n", ft->filename);
        fprintf(stderr, "Channels       : %u\n", ft->signal.channels);
        fprintf(stderr, "Sample Rate    : %g\n", ft->signal.rate);
        fprintf(stderr, "Precision      : %u-bit\n", ft->signal.precision);

        if (ft->signal.length > 0 && ft->signal.rate > 0) {
            double dur = (double)ft->signal.length / ft->signal.rate;
            char dur_buf[32];
            format_duration(dur_buf, sizeof(dur_buf), dur);
            double cdda = dur * 75.0;
            int exact_cdda = (fabs(ft->signal.rate - 44100.0) < 1.0);
            if (exact_cdda)
                fprintf(stderr, "Duration       : %s = %" PRIu64 " samples = %g CDDA sectors\n",
                        dur_buf, ft->signal.length, cdda);
            else
                fprintf(stderr, "Duration       : %s = %" PRIu64 " samples ~ %g CDDA sectors\n",
                        dur_buf, ft->signal.length, cdda);
        }
        if (ft->filesize > 0) {
            char size_buf[32];
            format_si(size_buf, sizeof(size_buf), (double)ft->filesize);
            fprintf(stderr, "File Size      : %s\n", size_buf);
        }
        if (ft->signal.rate > 0 && ft->signal.channels > 0 && ft->encoding.bits_per_sample > 0) {
            double bitrate = ft->signal.rate * ft->signal.channels * ft->encoding.bits_per_sample;
            char br_buf[32];
            format_si(br_buf, sizeof(br_buf), bitrate);
            fprintf(stderr, "Bit Rate       : %s\n", br_buf);
        }
        fprintf(stderr, "Sample Encoding: %s\n",
                encoding_human(ft->encoding.encoding, ft->encoding.bits_per_sample));
        if (ft->oob.comment && *ft->oob.comment)
            fprintf(stderr, "Comment        : '%s'\n", ft->oob.comment);
        fprintf(stderr, "\n");
    }

    /* Initial progress display */
    if (globals.show_progress) {
        /* Display initial state */
        double dur = (pipe->n_inputs > 0 && pipe->inputs[0]->signal.rate > 0) ?
                     (double)total_in_samples / pipe->inputs[0]->signal.rate / 
                     (pipe->inputs[0]->signal.channels > 0 ? pipe->inputs[0]->signal.channels : 1) : 0;
        char dur_buf[16]; format_duration(dur_buf, sizeof(dur_buf), dur);
        char zero_buf[16]; format_duration(zero_buf, sizeof(zero_buf), 0.0);
        fprintf(stderr, "\nIn:0.00%% %s [%s] Out:0     [      |      ]        Clip:0    \n",
                zero_buf, dur_buf);
    }

    /* Main processing loop */
    int current_input = 0;
    uint64_t samples_processed = 0;
    time_t start_time = time(NULL);
    int all_done = 0;
    uint64_t total_clips = 0;

    while (!all_done) {
        /* Read from current input */
        size_t nread = 0;

        if (pipe->n_inputs == 0 || pipe->n_inputs <= current_input) {
            all_done = 1;
            break;
        }

        sox_format_t *in = pipe->inputs[current_input];
        nread = sox_read(in, ibuf, bufsize);

        if (nread == 0) {
            current_input++;
            if (current_input >= pipe->n_inputs) {
                all_done = 1;
            }
            continue;
        }

        samples_processed += nread;

        /* Apply volume adjustment */
        if (in->volume != 1.0) {
            for (size_t k = 0; k < nread; k++) {
                double s = (double)ibuf[k] * in->volume;
                if (s > SOX_SAMPLE_MAX) s = SOX_SAMPLE_MAX;
                if (s < SOX_SAMPLE_MIN) s = SOX_SAMPLE_MIN;
                ibuf[k] = (sox_sample_t)s;
            }
        }

        /* Run through effects chain */
        sox_sample_t *cur_buf = ibuf;
        size_t cur_len = nread;

        for (int ei = 0; ei < pipe->n_effects; ei++) {
            sox_effect_t *eff = pipe->effects[ei];
            if (!eff->handler.flow) continue;

            size_t isamp = cur_len;
            size_t osamp = bufsize;

            int ret = eff->handler.flow(eff, cur_buf, obuf, &isamp, &osamp);

            if (ret == SOX_EOF) {
                all_done = 1;
            }

            /* Swap buffers */
            sox_sample_t *tmp = cur_buf;
            if (cur_buf == ibuf) {
                cur_buf = obuf;
                obuf = ibuf;
            } else {
                cur_buf = obuf;
                obuf = tmp;
            }
            cur_len = osamp;
        }

        /* Write output */
        if (cur_len > 0 && pipe->output && !pipe->is_null_output) {
            sox_write(pipe->output, cur_buf, cur_len);
        }

        pipe->total_out_samples += cur_len;

        /* Accumulate clips */
        for (int ei = 0; ei < pipe->n_effects; ei++) {
            total_clips += pipe->effects[ei]->clips;
            pipe->effects[ei]->clips = 0;
        }
        total_clips += pipe->output ? pipe->output->clips : 0;
        if (pipe->output) pipe->output->clips = 0;
    }

    /* Drain effects */
    while (1) {
        int any_output = 0;

        for (int ei = 0; ei < pipe->n_effects; ei++) {
            sox_effect_t *eff = pipe->effects[ei];
            if (!eff->handler.drain || eff->eof) continue;

            size_t osamp = bufsize;
            int ret = eff->handler.drain(eff, obuf, &osamp);

            if (osamp > 0) {
                /* Write drained output */
                if (pipe->output && !pipe->is_null_output) {
                    sox_write(pipe->output, obuf, osamp);
                }
                pipe->total_out_samples += osamp;
                any_output = 1;
            }

            if (ret == SOX_EOF) {
                eff->eof = 1;
            }
        }

        if (!any_output) break;
    }

    /* Call stop on all effects */
    for (int ei = 0; ei < pipe->n_effects; ei++) {
        sox_effect_t *eff = pipe->effects[ei];
        if (eff->handler.stop) eff->handler.stop(eff);
    }

    /* Final progress display */
    if (globals.show_progress) {
        double dur = (pipe->n_inputs > 0 && pipe->inputs[0]->signal.rate > 0) ?
                     (double)total_in_samples / pipe->inputs[0]->signal.rate / 
                     (pipe->inputs[0]->signal.channels > 0 ? pipe->inputs[0]->signal.channels : 1) : 0;
        char dur_buf[16]; format_duration(dur_buf, sizeof(dur_buf), dur);
        char elapsed_buf[16]; format_duration(elapsed_buf, sizeof(elapsed_buf), dur);
        char zero_buf[16]; format_duration(zero_buf, sizeof(zero_buf), 0.0);
        char out_str[16]; format_si(out_str, sizeof(out_str), (double)pipe->total_out_samples);

        /* VU meter at full */
        fprintf(stderr, "In:100%%  %s [%s] Out:%-6s [ =====|===== ]        Clip:%-6" PRIu64 "  \n",
                dur_buf, zero_buf, out_str, total_clips);
        fprintf(stderr, "Done.\n");
    }

    free(ibuf);
    free(obuf);
    return 0;
}

/* =====================================================================
 * MAIN
 * ===================================================================== */

int main(int argc, char *argv[]) {
    int i;
    int is_soxi = 0;
    int soxi_total = 0;
    char *soxi_opt = NULL;

    /* Determine program name */
    const char *progname = strrchr(argv[0], '/');
    progname = progname ? progname + 1 : argv[0];
    g_progname = progname;

    /* Check if invoked as soxi, play, or rec */
    if (strcmp(progname, "soxi") == 0) {
        is_soxi = 1;
    } else if (strcmp(progname, "play") == 0) {
        /* TODO: play mode */
    } else if (strcmp(progname, "rec") == 0) {
        /* TODO: rec mode */
    }

    if (argc < 2) {
        if (is_soxi) {
            print_soxi_help();
        } else {
            print_help();
        }
        return 0;
    }

    /* Parse global options */
    i = 1;

    /* Lists for files and effects */
    char *input_files[MAX_INPUTS];
    file_opts_t input_opts[MAX_INPUTS];
    int n_inputs = 0;
    char *output_file = NULL;
    file_opts_t output_opts_data;
    file_opts_t *output_opts = &output_opts_data;
    init_file_opts(output_opts);

    /* Effect arguments */
    char *effect_names[MAX_EFFECTS];
    int effect_argc[MAX_EFFECTS];
    char *effect_argv[MAX_EFFECTS][64];
    int n_effects = 0;

    int effects_started = 0;

    while (i < argc) {
        char *arg = argv[i];

        /* Check if this is the --i / --info flag (soxi mode) */
        if (strcmp(arg, "--i") == 0 || strcmp(arg, "--info") == 0) {
            is_soxi = 1;
            i++;
            continue;
        }

        /* Global options */
        if (!effects_started && !is_soxi) {
            if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
                print_help();
                return 0;
            } else if (strcmp(arg, "--version") == 0) {
                print_version();
                return 0;
            } else if (strncmp(arg, "--help-effect", 13) == 0) {
                const char *name = strchr(arg, '=');
                if (name) name++;
                else if (i+1 < argc) name = argv[++i];
                else { lsx_fail("--help-effect: missing argument"); return 1; }
                print_effect_help(name);
                return 0;
            } else if (strncmp(arg, "--help-format", 13) == 0) {
                const char *name = strchr(arg, '=');
                if (name) name++;
                else if (i+1 < argc) name = argv[++i];
                else { lsx_fail("--help-format: missing argument"); return 1; }
                print_format_help(name);
                return 0;
            } else if (strcmp(arg, "-q") == 0 || strcmp(arg, "--no-show-progress") == 0) {
                globals.show_progress = -1;  /* explicitly disabled */
                i++;
                continue;
            } else if (strcmp(arg, "-S") == 0 || strcmp(arg, "--show-progress") == 0) {
                globals.show_progress = 1;
                i++;
                continue;
            } else if (strcmp(arg, "-D") == 0 || strcmp(arg, "--no-dither") == 0) {
                globals.no_dither = 1;
                i++;
                continue;
            } else if (strcmp(arg, "-G") == 0 || strcmp(arg, "--guard") == 0) {
                globals.guard = 1;
                i++;
                continue;
            } else if (strcmp(arg, "--norm") == 0) {
                globals.norm = 1;
                i++;
                continue;
            } else if (strcmp(arg, "-m") == 0 || 
                       (strcmp(arg, "--combine") == 0 && i+1 < argc && strcmp(argv[i+1], "mix") == 0)) {
                globals.combine_method = 1;
                if (strcmp(arg, "--combine") == 0) i++;
                i++;
                continue;
            } else if (strcmp(arg, "-M") == 0 ||
                       (strcmp(arg, "--combine") == 0 && i+1 < argc && strcmp(argv[i+1], "merge") == 0)) {
                globals.combine_method = 2;
                if (strcmp(arg, "--combine") == 0) i++;
                i++;
                continue;
            } else if (strcmp(arg, "-T") == 0 ||
                       (strcmp(arg, "--combine") == 0 && i+1 < argc && strcmp(argv[i+1], "multiply") == 0)) {
                globals.combine_method = 3;
                if (strcmp(arg, "--combine") == 0) i++;
                i++;
                continue;
            } else if (strcmp(arg, "--combine") == 0 && i+1 < argc) {
                /* Handle all combine modes */
                i++;
                if (strcmp(argv[i], "concatenate") == 0) globals.combine_method = 0;
                else if (strcmp(argv[i], "sequence") == 0) globals.combine_method = 0;
                else if (strcmp(argv[i], "mix") == 0) globals.combine_method = 1;
                else if (strcmp(argv[i], "mix-power") == 0) globals.combine_method = 1;
                else if (strcmp(argv[i], "merge") == 0) globals.combine_method = 2;
                else if (strcmp(argv[i], "multiply") == 0) globals.combine_method = 3;
                i++;
                continue;
            } else if (strcmp(arg, "--no-clobber") == 0) {
                globals.no_clobber = 1;
                i++;
                continue;
            } else if (strcmp(arg, "--clobber") == 0) {
                globals.no_clobber = 0;
                i++;
                continue;
            } else if (strncmp(arg, "-V", 2) == 0) {
                if (arg[2] != '\0') {
                    globals.verbosity = atoi(arg + 2);
                } else if (i+1 < argc && isdigit(argv[i+1][0])) {
                    globals.verbosity = atoi(argv[++i]);
                } else {
                    globals.verbosity++;
                }
                i++;
                continue;
            } else if (strcmp(arg, "-R") == 0) {
                /* Use deterministic random */
                i++;
                continue;
            } else if (strcmp(arg, "--buffer") == 0 && i+1 < argc) {
                globals.bufsiz = (size_t)atol(argv[++i]);
                i++;
                continue;
            } else if (strcmp(arg, "--input-buffer") == 0 && i+1 < argc) {
                globals.input_bufsiz = (size_t)atol(argv[++i]);
                i++;
                continue;
            } else if (strcmp(arg, "--temp") == 0 && i+1 < argc) {
                globals.temp_dir = argv[++i];
                i++;
                continue;
            } else if (strcmp(arg, "--effects-file") == 0 && i+1 < argc) {
                globals.effects_file = argv[++i];
                i++;
                continue;
            } else if (strcmp(arg, "--dft-min") == 0 && i+1 < argc) {
                globals.dft_min = (unsigned)atoi(argv[++i]);
                i++;
                continue;
            } else if (strcmp(arg, "--play-rate-arg") == 0 && i+1 < argc) {
                globals.play_rate_arg = argv[++i];
                i++;
                continue;
            } else if (strcmp(arg, "--plot") == 0 && i+1 < argc) {
                ++i;  /* skip argument */
                i++;
                continue;
            } else if (strcmp(arg, "--multi-threaded") == 0) {
                globals.multi_threaded = 1;
                i++;
                continue;
            } else if (strcmp(arg, "--single-threaded") == 0) {
                globals.single_threaded = 1;
                i++;
                continue;
            } else if (strcmp(arg, "--replay-gain") == 0 && i+1 < argc) {
                ++i;
                i++;
                continue;
            }
        }

        /* SOXI handling */
        if (is_soxi) {
            /* Parse soxi options */
            if (strcmp(arg, "-T") == 0) {
                soxi_total = 1;
                i++;
                continue;
            } else if (strcmp(arg, "-t") == 0 || strcmp(arg, "-r") == 0 ||
                       strcmp(arg, "-c") == 0 || strcmp(arg, "-s") == 0 ||
                       strcmp(arg, "-d") == 0 || strcmp(arg, "-D") == 0 ||
                       strcmp(arg, "-b") == 0 || strcmp(arg, "-B") == 0 ||
                       strcmp(arg, "-p") == 0 || strcmp(arg, "-e") == 0 ||
                       strcmp(arg, "-a") == 0) {
                soxi_opt = arg;
                i++;
                continue;
            } else if (strncmp(arg, "-V", 2) == 0) {
                if (arg[2] != '\0') globals.verbosity = atoi(arg + 2);
                else globals.verbosity++;
                i++;
                continue;
            } else if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
                print_soxi_help();
                return 0;
            }

            /* It's a filename */
            input_files[n_inputs] = arg;
            init_file_opts(&input_opts[n_inputs]);
            n_inputs++;
            i++;
            continue;
        }

        /* Check if we've started the effects section */
        if (!effects_started && n_inputs > 0 && output_file != NULL) {
            /* Check if this is an effect name */
            if (find_effect(arg) != NULL) {
                effects_started = 1;
            } else if (arg[0] == '-') {
                /* Might be a format option for the output file */
                /* Actually we already parsed output file, so these might be effect options */
                /* Or there could be more input files... complicated */
                /* For simplicity, treat as effect */
                if (!find_effect(arg)) {
                    /* Not an effect, might be something else */
                }
                effects_started = 1;
            }
        }

        if (effects_started) {
            /* Parse effects */
            effect_entry_t *e = find_effect(arg);
            if (e) {
                int eff_idx = n_effects++;
                effect_names[eff_idx] = arg;
                effect_argc[eff_idx] = 0;
                i++;
                /* Collect effect arguments until next effect name */
                while (i < argc && effect_argc[eff_idx] < 64) {
                    if (find_effect(argv[i]) != NULL) break;
                    /* Check if it's a special token like ':' */
                    if (strcmp(argv[i], ":") == 0) break;
                    effect_argv[eff_idx][effect_argc[eff_idx]++] = argv[i];
                    i++;
                }
            } else {
                lsx_warn("Unknown effect `%s'", arg);
                i++;
            }
            continue;
        }

        /* File or format options */
        if (arg[0] == '-' && arg[1] != '\0' && arg[1] != 'n' && arg[1] != 'd' && arg[1] != 'p') {
            /* Might be a format option */
            file_opts_t *opts = (n_inputs == 0) ? &input_opts[0] : 
                                 (output_file == NULL) ? output_opts : &input_opts[n_inputs];
            if (output_file != NULL) opts = output_opts;
            else if (n_inputs > 0) opts = &input_opts[n_inputs];
            else { init_file_opts(opts = &input_opts[0]); }

            int save_i = i;
            if (parse_file_opts(opts, argc, argv, &i) == 0 && i > save_i) {
                continue;
            }
            /* If not recognized as format option, might be a file */
        }

        /* Special filenames */
        if (strcmp(arg, "-n") == 0 || strcmp(arg, "--null") == 0) {
            /* null file */
            if (n_inputs == 0 || (output_file == NULL && n_inputs > 0)) {
                /* Could be input or output */
                /* If we already have input, it's output */
                if (n_inputs > 0) {
                    output_file = "-n";
                } else {
                    input_files[n_inputs] = "-n";
                    init_file_opts(&input_opts[n_inputs]);
                    n_inputs++;
                }
            }
            i++;
            continue;
        }

        if (strcmp(arg, "-d") == 0 || strcmp(arg, "--default-device") == 0) {
            /* default device */
            if (n_inputs > 0 && output_file == NULL) {
                output_file = "-d";
            } else {
                input_files[n_inputs] = "-d";
                init_file_opts(&input_opts[n_inputs]);
                n_inputs++;
            }
            i++;
            continue;
        }

        if (strcmp(arg, "-p") == 0 || strcmp(arg, "--sox-pipe") == 0) {
            /* sox pipe */
            if (n_inputs > 0 && output_file == NULL) {
                output_file = "-p";
            } else {
                input_files[n_inputs] = "-p";
                init_file_opts(&input_opts[n_inputs]);
                n_inputs++;
            }
            i++;
            continue;
        }

        /* Regular filename */
        if (n_inputs == 0) {
            /* First file or files are inputs */
            init_file_opts(&input_opts[n_inputs]);
            input_files[n_inputs++] = arg;
            i++;

            /* After first input, keep reading format options and more inputs */
            /* We'll figure out which is output at the end */
        } else {
            /* Could be another input or the output */
            /* For now, treat all non-effect args as additional files */
            /* The last non-effect arg is the output */

            /* Collect format options for this file */
            file_opts_t tmp_opts;
            init_file_opts(&tmp_opts);
            int save_i2 = i;
            ++i;
            if (parse_file_opts(&tmp_opts, argc, argv, &i) == 0) {
                /* Check if next arg is a file */
            }
            /* Back off - this is a file */
            i = save_i2 + 1;

            /* Push current output candidate as input */
            if (output_file != NULL) {
                input_files[n_inputs] = output_file;
                input_opts[n_inputs] = *output_opts;
                n_inputs++;
                init_file_opts(output_opts);
            }
            output_file = arg;
        }

        continue;
    }

    /* SOXI mode */
    if (is_soxi) {
        if (n_inputs == 0) {
            print_soxi_help();
            return 0;
        }

        double total_dur = 0;
        uint64_t total_samp = 0;
        int any_error = 0;

        for (int fi = 0; fi < n_inputs; fi++) {
            sox_format_t *ft = sox_open_read(input_files[fi], NULL, NULL, NULL);
            if (!ft) {
                any_error = 1;
                continue;
            }

            display_soxi(ft, soxi_opt, soxi_total, &total_dur, &total_samp);
            sox_close(ft);
        }

        /* Print totals if applicable */
        if (n_inputs > 1 && !soxi_opt) {
            /* Total duration at the bottom */
            char dur_buf[32];
            format_duration(dur_buf, sizeof(dur_buf), total_dur);
            printf("Total Duration of %d files: %s\n", n_inputs, dur_buf);
        } else if (soxi_total && soxi_opt) {
            if (strcmp(soxi_opt, "-s") == 0) {
                printf("%g\n", (double)total_samp);
            } else if (strcmp(soxi_opt, "-d") == 0) {
                char dur_buf[32];
                format_duration(dur_buf, sizeof(dur_buf), total_dur);
                printf("%s\n", dur_buf);
            } else if (strcmp(soxi_opt, "-D") == 0) {
                printf("%f\n", total_dur);
            }
        }

        return any_error ? 1 : 0;
    }

    /* Normal sox processing mode */
    if (n_inputs == 0) {
        lsx_fail("no input files specified");
        return 1;
    }

    if (output_file == NULL) {
        lsx_fail("no output file specified");
        return 1;
    }

    /* Check for --no-clobber */
    if (globals.no_clobber && strcmp(output_file, "-n") != 0 && strcmp(output_file, "-") != 0) {
        struct stat st;
        if (stat(output_file, &st) == 0) {
            lsx_warn("sox: Output file `%s' already exists", output_file);
            lsx_fail("formats: permission to overwrite `%s' denied", output_file);
            return 2;
        }
    }

    /* Open input files */
    sox_format_t *inputs[MAX_INPUTS];
    int actual_n_inputs = 0;

    for (int fi = 0; fi < n_inputs; fi++) {
        if (strcmp(input_files[fi], "-n") == 0) {
            /* null input */
            sox_format_t *ft = (sox_format_t *)calloc(1, sizeof(sox_format_t));
            ft->filename = strdup("-n");
            ft->filetype = strdup("null");
            ft->mode = 'r';
            ft->signal.rate = input_opts[fi].signal.rate > 0 ? input_opts[fi].signal.rate : SOX_DEFAULT_RATE;
            ft->signal.channels = input_opts[fi].signal.channels > 0 ? input_opts[fi].signal.channels : SOX_DEFAULT_CHANNELS;
            ft->signal.length = 0;
            inputs[actual_n_inputs++] = ft;
            continue;
        }

        sox_signalinfo_t sig = input_opts[fi].signal;
        sox_encodinginfo_t enc = input_opts[fi].encoding;

        sox_format_t *ft = sox_open_read(input_files[fi], 
                                          (sig.rate > 0 || sig.channels > 0) ? &sig : NULL,
                                          (enc.encoding != SOX_ENCODING_UNKNOWN || enc.bits_per_sample > 0) ? &enc : NULL,
                                          input_opts[fi].type);
        if (!ft) {
            /* Error already printed */
            for (int j = 0; j < actual_n_inputs; j++) sox_close(inputs[j]);
            return 1;
        }

        ft->volume = input_opts[fi].volume;
        if (input_opts[fi].ignore_length) ft->ignore_length = 1;
        inputs[actual_n_inputs++] = ft;
    }

    if (actual_n_inputs == 0) {
        lsx_fail("no valid input files");
        return 1;
    }

    /* Determine output signal format */
    sox_signalinfo_t out_sig = inputs[0]->signal;
    sox_encodinginfo_t out_enc = inputs[0]->encoding;

    /* Apply output options */
    if (output_opts->signal.rate > 0) out_sig.rate = output_opts->signal.rate;
    if (output_opts->signal.channels > 0) out_sig.channels = output_opts->signal.channels;
    if (output_opts->encoding.encoding != SOX_ENCODING_UNKNOWN) out_enc.encoding = output_opts->encoding.encoding;
    if (output_opts->encoding.bits_per_sample > 0) out_enc.bits_per_sample = output_opts->encoding.bits_per_sample;

    /* Check for effects that change signal format */
    for (int ei = 0; ei < n_effects; ei++) {
        effect_entry_t *e = find_effect(effect_names[ei]);
        if (!e) continue;
        if ((e->flags & SOX_EFF_RATE) && strcmp(effect_names[ei], "rate") == 0) {
            /* Rate effect changes the rate */
            for (int eai = 0; eai < effect_argc[ei]; eai++) {
                char *ea = effect_argv[ei][eai];
                if (ea[0] != '-') {
                    char *end;
                    double r = strtod(ea, &end);
                    if (*end == 'k' || *end == 'K') r *= 1000;
                    if (r > 0) out_sig.rate = r;
                    break;
                }
            }
        } else if ((e->flags & SOX_EFF_CHAN) && strcmp(effect_names[ei], "channels") == 0) {
            if (effect_argc[ei] > 0)
                out_sig.channels = (unsigned)atoi(effect_argv[ei][0]);
        }
    }

    /* For the output, set bits from encoding */
    if (out_enc.bits_per_sample == 0) {
        /* Default based on encoding */
        switch (out_enc.encoding) {
            case SOX_ENCODING_ULAW:
            case SOX_ENCODING_ALAW:
                out_enc.bits_per_sample = 8;
                break;
            default:
                out_enc.bits_per_sample = inputs[0]->encoding.bits_per_sample;
                if (out_enc.bits_per_sample == 0) out_enc.bits_per_sample = 16;
                break;
        }
    }

    /* Open output file */
    sox_format_t *output = NULL;
    int is_null_output = 0;

    if (strcmp(output_file, "-n") == 0) {
        is_null_output = 1;
        output = (sox_format_t *)calloc(1, sizeof(sox_format_t));
        output->filename = strdup("-n");
        output->filetype = strdup("null");
        output->mode = 'w';
        output->signal = out_sig;
        output->encoding = out_enc;
    } else {
        /* Set output comment */
        sox_oob_t oob;
        memset(&oob, 0, sizeof(oob));
        if (output_opts->comment) {
            oob.comment = output_opts->comment;
        } else {
            oob.comment = "Processed by SoX";
        }

        /* Make sure output encoding is set */
        output = sox_open_write(output_file, &out_sig, &out_enc,
                                 output_opts->type,
                                 &oob);
        if (!output) {
            for (int j = 0; j < actual_n_inputs; j++) sox_close(inputs[j]);
            return 1;
        }
    }

    /* Create effects chain */
    sox_effect_t *effects[MAX_EFFECTS];
    int n_eff = 0;

    /* Add dither effect before bit reduction if needed */
    int needs_dither = 0;
    if (!globals.no_dither && inputs[0]->encoding.bits_per_sample > out_enc.bits_per_sample &&
        out_enc.bits_per_sample > 0 && out_enc.bits_per_sample <= 24) {
        needs_dither = 1;
    }

    /* Create and initialize effects */
    for (int ei = 0; ei < n_effects; ei++) {
        effect_entry_t *e = find_effect(effect_names[ei]);
        if (!e) {
            lsx_warn("Unknown effect `%s'", effect_names[ei]);
            continue;
        }

        sox_effect_t *eff = create_effect(effect_names[ei]);
        if (!eff) { lsx_fail("out of memory"); continue; }

        /* Set initial signal info */
        eff->in_signal = out_sig;
        eff->out_signal = out_sig;

        /* Parse options */
        if (eff->handler.getopts) {
            int ret = eff->handler.getopts(eff, effect_argc[ei], effect_argv[ei]);
            if (ret != SOX_SUCCESS) {
                destroy_effect(eff);
                continue;
            }
        }

        /* Update out_sig for next effect */
        out_sig = eff->out_signal;
        if (out_sig.rate == 0) out_sig = eff->in_signal;
        if (eff->out_signal.rate > 0) out_sig.rate = eff->out_signal.rate;
        if (eff->out_signal.channels > 0) out_sig.channels = eff->out_signal.channels;

        effects[n_eff++] = eff;
    }

    /* Add dither before output if needed */
    if (needs_dither) {
        sox_effect_t *dith_eff = create_effect("dither");
        if (dith_eff) {
            /* Set up dither for target bit depth */
            dith_eff->out_encoding.bits_per_sample = out_enc.bits_per_sample;
            char *dith_args[] = {"-p", NULL};
            char bits_str[16];
            snprintf(bits_str, sizeof(bits_str), "%u", out_enc.bits_per_sample);
            dith_args[1] = bits_str;
            if (dith_eff->handler.getopts)
                dith_eff->handler.getopts(dith_eff, 2, dith_args);
            dith_eff->in_signal = out_sig;
            dith_eff->out_signal = out_sig;
            dith_eff->out_encoding = out_enc;
            effects[n_eff++] = dith_eff;
        }
    }

    /* Set up and run pipeline */
    pipeline_t pipe;
    memset(&pipe, 0, sizeof(pipe));
    pipe.inputs = inputs;
    pipe.n_inputs = actual_n_inputs;
    pipe.output = output;
    pipe.is_null_output = is_null_output;
    memcpy(pipe.effects, effects, n_eff * sizeof(sox_effect_t *));
    pipe.n_effects = n_eff;
    pipe.bufsize = globals.bufsiz > 0 ? globals.bufsiz : 8192;
    pipe.combine_method = globals.combine_method;

    int ret = process(&pipe);

    /* Cleanup */
    for (int j = 0; j < actual_n_inputs; j++) sox_close(inputs[j]);
    sox_close(output);
    for (int ei = 0; ei < n_eff; ei++) destroy_effect(effects[ei]);

    return (ret == 0) ? 0 : 1;
}
